const TransformableCharacter: React.FC<{
    character: Character;
    rotation: number;
    position: { x: number, y: number };
    onRotationChange: (rot: number) => void;
    onPositionChange: (pos: { x: number, y: number }) => void;
    isSelected: boolean;
    onSelect: () => void;
    containerRef: React.RefObject<HTMLDivElement>;
}> = ({ character, rotation, position, onRotationChange, onPositionChange, isSelected, onSelect, containerRef }) => {
    const [isDragging, setIsDragging] = useState(false);
    const [isRotating, setIsRotating] = useState(false);
    const startPosRef = useRef({ x: 0, y: 0 });
    const startRotationRef = useRef(0);
    const centerRef = useRef({ x: 0, y: 0 }); // Cache center point during rotation
    const elementRef = useRef<HTMLDivElement>(null);

    const handleMouseDown = (e: React.MouseEvent) => {
        if (e.button !== 0) return; // Only left click
        e.stopPropagation();
        onSelect();
        setIsDragging(true);
        startPosRef.current = { x: e.clientX - position.x, y: e.clientY - position.y };
    };

    const handleRotateMouseDown = (e: React.MouseEvent) => {
        e.stopPropagation();
        e.preventDefault();
        setIsRotating(true);
        if (elementRef.current) {
             const rect = elementRef.current.getBoundingClientRect();
             // Calculate center based on the rect at the start of rotation
             const centerX = rect.left + rect.width / 2;
             const centerY = rect.top + rect.height / 2;
             centerRef.current = { x: centerX, y: centerY };

             // Store initial angle relative to current rotation
             const currentAngle = Math.atan2(e.clientY - centerY, e.clientX - centerX) * (180 / Math.PI);
             startRotationRef.current = currentAngle - rotation;
        }
    };

    const handleRotateStep = (e: React.MouseEvent, degrees: number) => {
        e.stopPropagation();
        onRotationChange(rotation + degrees);
    };

    const handleManualRotationChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = parseInt(e.target.value, 10);
        if (!isNaN(val)) {
            onRotationChange(val);
        }
    };

    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            if (isDragging) {
                const newX = e.clientX - startPosRef.current.x;
                const newY = e.clientY - startPosRef.current.y;
                onPositionChange({ x: newX, y: newY });
            } else if (isRotating) {
                // Use cached center to prevent jitter as element transform changes
                const { x: centerX, y: centerY } = centerRef.current;
                const angle = Math.atan2(e.clientY - centerY, e.clientX - centerX) * (180 / Math.PI);
                let newRotation = angle - startRotationRef.current;

                // Snap to 45 degrees if Shift is held
                if (e.shiftKey) {
                    newRotation = Math.round(newRotation / 45) * 45;
                }

                onRotationChange(newRotation);
            }
        };

        const handleMouseUp = () => {
            setIsDragging(false);
            setIsRotating(false);
        };

        if (isDragging || isRotating) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
        }

        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [isDragging, isRotating, onPositionChange, onRotationChange]);

    return (
        <div
            ref={elementRef}
            style={{
                transform: `translate(${position.x}px, ${position.y}px) rotate(${rotation}deg)`,
                position: 'absolute',
                top: 0,
                left: 0,
                cursor: isDragging ? 'grabbing' : 'grab',
                zIndex: isSelected ? 50 : undefined
            }}
            onMouseDown={handleMouseDown}
            className={`select-none ${isSelected ? 'z-50' : ''}`}
        >
            <div className={`relative ${isSelected ? 'ring-2 ring-indigo-500' : ''}`}>
                <img 
                    src={character.imageUrl} 
                    alt={character.name} 
                    className="w-48 h-auto object-contain pointer-events-none"
                    draggable={false}
                />

                {isSelected && (
                    <div 
                        className="absolute -top-8 left-1/2 transform -translate-x-1/2 w-6 h-6 bg-white rounded-full shadow-md cursor-crosshair flex items-center justify-center border border-gray-300 hover:bg-indigo-100"
                        onMouseDown={handleRotateMouseDown}
                        title="Drag to rotate (Hold Shift to snap)"
                    >
                        <div className="w-1.5 h-1.5 bg-indigo-600 rounded-full"></div>
                        <div className="absolute h-4 w-0.5 bg-indigo-500 top-full left-1/2 transform -translate-x-1/2"></div>
                    </div>
                )}

                {isSelected && (
                    <div className="absolute -bottom-8 left-1/2 transform -translate-x-1/2 flex gap-2 pointer-events-auto">
                        <button 
                            onClick={(e) => handleRotateStep(e, -45)}
                            className="bg-gray-800 text-white p-1.5 rounded-full shadow hover:bg-indigo-600 transition-colors border border-gray-600"
                            title="Rotate Left 45°"
                        >
                            <RotateLeftIcon className="w-4 h-4" />
                        </button>
                        <button 
                            onClick={(e) => handleRotateStep(e, 45)}
                            className="bg-gray-800 text-white p-1.5 rounded-full shadow hover:bg-indigo-600 transition-colors border border-gray-600"
                            title="Rotate Right 45°"
                        >
                            <RotateRightIcon className="w-4 h-4" />
                        </button>
                    </div>
                )}

                {isSelected && (
                    <div className="absolute top-0 right-0 pointer-events-auto">
                        <input
                            type="number"
                            step={45}
                            value={Math.round(rotation)}
                            onChange={handleManualRotationChange}
                            onMouseDown={(e) => e.stopPropagation()}
                            className="w-14 bg-indigo-600 text-white text-xs px-1 py-0.5 rounded-bl border-none focus:outline-none focus:ring-1 focus:ring-white text-center font-mono"
                            title="Rotation angle (step 45°)"
                        />
                    </div>
                )}
            </div>
        </div>
    );
};

export const Canvas: React.FC<CanvasProps> = ({ 
    isLoading, 
    loadingMessage, 
    generatedContent, 
    error, 
    selectedCharacters, 
    onCharacterReorder,
    characterRotations,
    onRotationChange,
    characterPositions,
    onPositionChange
}) => {
  const [showDownloadModal, setShowDownloadModal] = useState(false);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Close modal if content changes
  useEffect(() => {
    setShowDownloadModal(false);
  }, [generatedContent]);

  // Set initial position to center for newly added characters
  useEffect(() => {
    if (containerRef.current) {
        const { width, height } = containerRef.current.getBoundingClientRect();
        selectedCharacters.forEach(char => {
            if (!characterPositions[char.id]) {
                // Initialize at center roughly (assuming char width 200px)
                onPositionChange(char.id, { x: width / 2 - 100, y: height / 2 - 100 });
            }
        });
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedCharacters.length]);

  const downloadMedia = (url: string, type: 'video' | 'audio' | 'json') => {
      const a = document.createElement('a');
      a.href = url;
      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');

      let extension = 'dat';
      if (type === 'video') extension = 'mp4';
      if (type === 'audio') extension = 'wav';
      if (type === 'json') extension = 'json';

      a.download = `character-studio-${type}-${timestamp}.${extension}`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
  };

  const renderContent = () => {
    if (isLoading) {
      return <Loader message={loadingMessage} />;
    }
    if (error) {
      return (
        <div className="text-center text-red-400 bg-red-900/50 p-6 rounded-lg">
          <h3 className="font-bold text-lg mb-2">An Error Occurred</h3>
          <p>{error}</p>
        </div>
      );
    }
    if (generatedContent) {
      if (generatedContent.type === 'image') {
        return (
          <div className="relative group max-w-full max-h-full flex flex-col items-center" key={generatedContent.url}>
            {generatedContent.soundEffectUrl && <AudioPlayer url={generatedContent.soundEffectUrl} />}
            <img src={generatedContent.url} alt="Generated content" className="max-w-full max-h-full object-contain rounded-lg shadow-2xl" />
            <button 
                onClick={() => setShowDownloadModal(true)}
                className="absolute top-4 right-4 bg-gray-900/80 hover:bg-indigo-600 text-white p-2 rounded-full opacity-0 group-hover:opacity-100 transition-all shadow-lg transform translate-y-2 group-hover:translate-y-0"
                title="Download Options"
            >
                <DownloadIcon className="w-6 h-6" />
            </button>
          </div>
        );
      }
      if (generatedContent.type === 'video') {
        return (
          <div className="relative group max-w-full max-h-full flex flex-col items-center" key={generatedContent.url}>
             <video src={generatedContent.url} controls autoPlay loop className="max-w-full max-h-full object-contain rounded-lg shadow-2xl" />
             <button 
                onClick={() => downloadMedia(generatedContent.url, 'video')}
                className="absolute top-4 right-4 bg-gray-900/80 hover:bg-indigo-600 text-white p-2 rounded-full opacity-0 group-hover:opacity-100 transition-all shadow-lg transform translate-y-2 group-hover:translate-y-0 z-10"
                title="Download Video"
            >
                <DownloadIcon className="w-6 h-6" />
            </button>
          </div>
        );
      }
      if (generatedContent.type === 'audio') {
          const character = selectedCharacters.find(c => c.id === generatedContent.characterId) || selectedCharacters[0];
          return (
              <div className="flex flex-col items-center gap-6 bg-gray-800/80 p-8 rounded-xl border border-gray-700 backdrop-blur-sm max-w-lg w-full relative" key={generatedContent.url}>
                  <div className="relative w-48 h-48 rounded-full overflow-hidden border-4 border-indigo-500 shadow-xl">
                      {character ? (
                          <img src={character.imageUrl} alt={character.name} className="w-full h-full object-cover" />
                      ) : (
                          <div className="w-full h-full bg-gray-700 flex items-center justify-center">
                              <MicrophoneIcon className="w-16 h-16 text-gray-500" />
                          </div>
                      )}
                  </div>
                  <div className="text-center">
                    <h3 className="text-xl font-bold text-white mb-1">{character?.name || 'Unknown Character'}</h3>
                    <p className="text-sm text-gray-400">Generated Voice Audio</p>
                  </div>
                  <div className="w-full flex items-center gap-2">
                    <audio src={generatedContent.url} controls autoPlay className="w-full" />
                    <button 
                        onClick={() => downloadMedia(generatedContent.url, 'audio')}
                        className="bg-gray-700 hover:bg-indigo-600 text-white p-2.5 rounded-full transition-colors"
                        title="Download Audio"
                    >
                        <DownloadIcon className="w-5 h-5" />
                    </button>
                  </div>
              </div>
          )
      }
      if (generatedContent.type === 'json') {
          return (
              <div className="flex flex-col w-full h-full max-w-4xl bg-gray-800/80 p-6 rounded-xl border border-gray-700 backdrop-blur-sm relative" key={generatedContent.url}>
                  <div className="flex justify-between items-center mb-4">
                      <div className="flex items-center gap-2">
                          <CodeBracketIcon className="w-6 h-6 text-indigo-400" />
                          <h3 className="text-xl font-bold text-white">JSON Context Profile</h3>
                      </div>
                      <div className="flex gap-2">
                        <Button 
                            onClick={() => {
                                navigator.clipboard.writeText(JSON.stringify(generatedContent.data, null, 2));
                                alert("Copied to clipboard!");
                            }}
                            variant="secondary"
                            className="text-xs"
                        >
                            Copy JSON
                        </Button>
                        <Button 
                            onClick={() => downloadMedia(generatedContent.url, 'json')}
                            className="text-xs"
                        >
                            Download
                        </Button>
                      </div>
                  </div>
                  <div className="flex-grow overflow-auto bg-gray-900/80 rounded-lg border border-gray-700 p-4 font-mono text-xs text-indigo-300 leading-relaxed custom-scrollbar">
                      <pre>{JSON.stringify(generatedContent.data, null, 2)}</pre>
                  </div>
              </div>
          )
      }
    }

    // Default: Interactive Stage
    if (selectedCharacters.length > 0) {
        return (
            <div 
                ref={containerRef}
                className="w-full h-full relative overflow-hidden bg-gray-800/30 rounded-xl border-2 border-dashed border-gray-700"
                onClick={() => setSelectedId(null)}
            >
                <div className="absolute top-4 left-4 text-gray-500 pointer-events-none z-0">
                    <p className="text-sm font-medium">Composition Stage</p>
                    <p className="text-xs">Drag to move, use handle to rotate.</p>
                </div>
                {selectedCharacters.map(char => (
                    <TransformableCharacter 
                        key={char.id}
                        character={char}
                        rotation={characterRotations[char.id] || 0}
                        position={characterPositions[char.id] || {x: 0, y: 0}}
                        onRotationChange={(rot) => onRotationChange(char.id, rot)}
                        onPositionChange={(pos) => onPositionChange(char.id, pos)}
                        isSelected={selectedId === char.id}
                        onSelect={() => setSelectedId(char.id)}
                        containerRef={containerRef}
                    />
                ))}
            </div>
        )
    }

    return (
      <div className="text-center text-gray-500 flex flex-col items-center gap-4">
        <SceneIcon className="w-24 h-24 text-gray-700" />
        <h2 className="text-2xl font-bold">Your Scene Awaits</h2>
        <p>Select characters from the library to start building.</p>
      </div>
    );
  };

  return (
    <main className="relative flex-grow p-6 flex items-center justify-center bg-gray-900/70">
      <div className="w-full h-full flex items-center justify-center">
        {renderContent()}
      </div>
      <LayerManager characters={selectedCharacters} onReorder={onCharacterReorder} />
      {showDownloadModal && generatedContent?.type === 'image' && (
        <ImageDownloadModal 
            imageUrl={generatedContent.url} 
            onClose={() => setShowDownloadModal(false)} 
        />
      )}
    </main>
  );
};

import React, { useState, useCallback } from 'react';
import { AspectRatio, Character, ToolType, SoundEffect, Scene } from '../types';
import { Button } from './common/Button';
import { generateScene, editImage, generateVideo, generateCharacterSpeech, generateImageFromInput, animateImage, generateJsonContextProfile } from '../services/geminiService';
import { ApiKeySelector } from './ApiKeySelector';
import { SaveIcon, VOICE_NAMES, UploadIcon, MusicIcon, TrashIcon, FilePlusIcon, ExportIcon, PhotoIcon, SparklesIcon, CodeBracketIcon } from '../constants';
import { fileToBase64 } from '../utils/fileUtils';

interface ControlsPanelProps {
  activeTool: ToolType;
  selectedCharacters: Character[];
  setLoading: (isLoading: boolean, message: string) => void;
  setError: (error: string | null) => void;
  onGenerationComplete: (content: { type: 'image' | 'video' | 'audio' | 'json'; url: string; data?: any; characterId?: string; soundEffectUrl?: string }) => void;

  // Scene Builder Props
  scenePrompt: string;
  setScenePrompt: (prompt: string) => void;
  onSaveScene: (name: string) => void;
  currentSceneName?: string;
  sceneSoundEffect: SoundEffect | undefined;
  setSceneSoundEffect: (sound: SoundEffect | undefined) => void;
  soundLibrary: SoundEffect[];
  setSoundLibrary: (library: SoundEffect[]) => void;
  characterRotations: Record<string, number>;
  onResetScene: () => void;
  scenes: Scene[];
  onLoadScene: (scene: Scene) => void;
  onExportScene: () => void;
}

const SceneBuilder: React.FC<Omit<ControlsPanelProps, 'activeTool'>> = ({ 
  selectedCharacters, 
  setLoading, 
  setError, 
  onGenerationComplete,
  scenePrompt,
  setScenePrompt,
  onSaveScene,
  currentSceneName,
  sceneSoundEffect,
  setSceneSoundEffect,
  soundLibrary,
  setSoundLibrary,
  characterRotations,
  onResetScene,
  scenes,
  onLoadScene,
  onExportScene
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const [sceneName, setSceneName] = useState('');
  const [soundTab, setSoundTab] = useState<'SELECT' | 'UPLOAD'>('SELECT');
  const [sceneToLoad, setSceneToLoad] = useState('');

  const handleGenerate = useCallback(async () => {
    if (selectedCharacters.length === 0) {
      setError("Please select at least one character from the library.");
      return;
    }
    setLoading(true, "Building your scene...");
    setError(null);
    try {
      const imageUrl = await generateScene(
          selectedCharacters, 
          scenePrompt, 
          characterRotations, 
          (msg) => setLoading(true, msg) // Pass progress callback
      );
      // Wait slightly to ensure state propagation if needed, though usually automatic
      onGenerationComplete({ 
        type: 'image', 
        url: imageUrl, 
        soundEffectUrl: sceneSoundEffect?.url 
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to generate scene.");
    } finally {
      setLoading(false, "");
    }
  }, [selectedCharacters, scenePrompt, setLoading, setError, onGenerationComplete, sceneSoundEffect, characterRotations]);

  const initiateSave = () => {
    if (selectedCharacters.length === 0) {
        setError("Add characters to save a scene.");
        return;
    }
    setError(null);
    // Pre-fill the name if we are editing an existing scene
    setSceneName(currentSceneName || '');
    setIsSaving(true);
  }

  const confirmSave = () => {
      if (sceneName.trim()) {
          onSaveScene(sceneName);
          setIsSaving(false);
      }
  };

  const handleSoundUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          try {
              const base64 = await fileToBase64(file);
              const newSound: SoundEffect = {
                  id: crypto.randomUUID(),
                  name: file.name.replace(/\.[^/.]+$/, ""),
                  url: base64
              };
              setSoundLibrary([...soundLibrary, newSound]);
              setSceneSoundEffect(newSound);
          } catch (err) {
              console.error("Audio upload failed", err);
              setError("Failed to upload audio.");
          }
      }
  };

  const handleLoadSelect = (e: React.ChangeEvent<HTMLSelectElement>) => {
      const sceneId = e.target.value;
      setSceneToLoad(sceneId);
      const scene = scenes.find(s => s.id === sceneId);
      if (scene) {
          onLoadScene(scene);
      }
  };

  return (
    <div className="flex flex-col h-full">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-xl font-bold text-white">Scene Builder</h2>
        <div className="flex gap-2">
           <Button onClick={onResetScene} variant="secondary" className="px-2" title="New Scene">
              <FilePlusIcon className="w-4 h-4" />
           </Button>
           <div className="relative">
              <select 
                value={sceneToLoad} 
                onChange={handleLoadSelect}
                className="bg-gray-700 text-white text-xs rounded px-2 py-2 border border-gray-600 focus:outline-none focus:border-indigo-500 max-w-[100px]"
              >
                  <option value="" disabled>Load...</option>
                  {scenes.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
              </select>
           </div>
        </div>
      </div>

      <div className="flex-grow overflow-y-auto pr-2 space-y-6">
          {/* Prompt Section */}
          <div className="space-y-2">
            <label className="block text-sm font-medium text-gray-300">Scene Description</label>
            <textarea
              className="w-full h-32 p-3 bg-gray-800 border border-gray-700 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-white placeholder-gray-500 resize-none"
              placeholder="Describe the scene setting, lighting, and action..."
              value={scenePrompt}
              onChange={(e) => setScenePrompt(e.target.value)}
            />
          </div>

          {/* Sound Effect Section */}
          <div className="space-y-2 bg-gray-800/50 p-3 rounded-lg border border-gray-700">
             <div className="flex justify-between items-center mb-2">
                 <label className="text-sm font-medium text-gray-300 flex items-center gap-2">
                    <MusicIcon className="w-4 h-4 text-indigo-400" />
                    Sound Effect / Ambience
                 </label>
                 {sceneSoundEffect && (
                     <button 
                        onClick={() => setSceneSoundEffect(undefined)}
                        className="text-xs text-red-400 hover:text-red-300 flex items-center gap-1"
                     >
                         <TrashIcon className="w-3 h-3" /> Clear
                     </button>
                 )}
             </div>

             {/* Sound Tabs */}
             <div className="flex gap-2 mb-2">
                 <button 
                    onClick={() => setSoundTab('SELECT')}
                    className={`flex-1 text-xs py-1 rounded ${soundTab === 'SELECT' ? 'bg-indigo-600 text-white' : 'bg-gray-700 text-gray-400'}`}
                 >
                     Library
                 </button>
                 <button 
                    onClick={() => setSoundTab('UPLOAD')}
                    className={`flex-1 text-xs py-1 rounded ${soundTab === 'UPLOAD' ? 'bg-indigo-600 text-white' : 'bg-gray-700 text-gray-400'}`}
                 >
                     Upload
                 </button>
             </div>

             {soundTab === 'SELECT' ? (
                 <select 
                    value={sceneSoundEffect?.id || ''}
                    onChange={(e) => setSceneSoundEffect(soundLibrary.find(s => s.id === e.target.value))}
                    className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-sm text-white"
                 >
                     <option value="">None selected</option>
                     {soundLibrary.map(sound => (
                         <option key={sound.id} value={sound.id}>{sound.name}</option>
                     ))}
                 </select>
             ) : (
                 <div className="border-2 border-dashed border-gray-600 rounded p-4 text-center hover:bg-gray-700/50 transition-colors cursor-pointer relative">
                     <input 
                        type="file" 
                        accept="audio/*" 
                        onChange={handleSoundUpload}
                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                     />
                     <UploadIcon className="w-6 h-6 mx-auto text-gray-400 mb-1" />
                     <p className="text-xs text-gray-400">Click to upload audio</p>
                 </div>
             )}

             {sceneSoundEffect && (
                 <div className="text-xs text-indigo-300 mt-1 flex items-center gap-1">
                     <span>Selected: {sceneSoundEffect.name}</span>
                 </div>
             )}
          </div>
      </div>

      <div className="pt-4 mt-auto border-t border-gray-700 flex flex-col gap-3">
        <Button onClick={handleGenerate} className="w-full py-3 text-lg shadow-lg shadow-indigo-500/20">
          Generate Scene
        </Button>

        <div className="flex gap-2">
            {isSaving ? (
                <div className="flex-1 flex gap-2">
                    <input 
                        type="text" 
                        value={sceneName}
                        onChange={(e) => setSceneName(e.target.value)}
                        placeholder="Scene Name"
                        className="flex-1 bg-gray-800 border border-gray-600 rounded px-2 text-sm"
                        autoFocus
                    />
                    <Button onClick={confirmSave} className="px-3 py-1 text-sm">Save</Button>
                    <Button onClick={() => setIsSaving(false)} variant="secondary" className="px-3 py-1 text-sm">Cancel</Button>
                </div>
            ) : (
                <Button onClick={initiateSave} variant="secondary" className="flex-1" title="Save Scene">
                  <SaveIcon className="w-4 h-4 mr-2" /> Save Scene
                </Button>
            )}
            <Button onClick={onExportScene} variant="secondary" className="px-3" title="Export JSON">
                <ExportIcon className="w-5 h-5" />
            </Button>
        </div>
      </div>
    </div>
  );
};

const JSONProfilerPanel: React.FC<Pick<ControlsPanelProps, 'setLoading' | 'setError' | 'onGenerationComplete'>> = ({ setLoading, setError, onGenerationComplete }) => {
    const [imageFile, setImageFile] = useState<File | null>(null);
    const [previewUrl, setPreviewUrl] = useState<string>('');
    const [userPrompt, setUserPrompt] = useState('');

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            setImageFile(file);
            setPreviewUrl(URL.createObjectURL(file));
        }
    };

    const runAnalysis = async (customPrompt?: string) => {
        if (!imageFile) {
            setError("Please upload an image first.");
            return;
        }
        setLoading(true, "Analyzing image structure...");
        setError(null);
        try {
            const data = await generateJsonContextProfile(imageFile, customPrompt);
            // We'll treat the output as a downloadable/viewable JSON object
            const jsonString = JSON.stringify(data, null, 2);
            const blob = new Blob([jsonString], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            onGenerationComplete({ 
                type: 'json', 
                url: url,
                data: data 
            });
        } catch (err) {
            setError(err instanceof Error ? err.message : "JSON Profile extraction failed.");
        } finally {
            setLoading(false, "");
        }
    };

    return (
        <div className="flex flex-col h-full space-y-6">
            <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <CodeBracketIcon className="w-6 h-6 text-indigo-400" /> JSON Profiler
            </h2>
            <div className="flex-grow space-y-6 overflow-y-auto pr-2">
                <div className="border-2 border-dashed border-gray-600 rounded-lg p-6 text-center hover:border-indigo-500 transition-colors cursor-pointer relative h-48 flex items-center justify-center bg-gray-800/30">
                    <input
                        type="file"
                        accept="image/*"
                        onChange={handleFileChange}
                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                    />
                    {previewUrl ? (
                        <img src={previewUrl} alt="Preview" className="max-h-full max-w-full object-contain rounded" />
                    ) : (
                        <div className="flex flex-col items-center">
                            <UploadIcon className="w-8 h-8 text-gray-400 mb-2" />
                            <p className="text-gray-400">Upload Image for JSON Analysis</p>
                        </div>
                    )}
                </div>

                <div className="p-4 bg-gray-800/50 rounded-lg border border-gray-700">
                    <h3 className="text-sm font-semibold text-gray-300 mb-3">Analysis Mode</h3>

                    <div className="space-y-4">
                        <div className="flex flex-col gap-2">
                            <p className="text-xs text-gray-500">Mode 1: Full Automated Extraction</p>
                            <Button onClick={() => runAnalysis()} className="w-full bg-indigo-600 hover:bg-indigo-500 text-xs">
                                Extract Advanced JSON Profile
                            </Button>
                        </div>

                        <div className="border-t border-gray-700 pt-3">
                            <p className="text-xs text-gray-500 mb-2">Mode 2: Prompt-Based Analysis</p>
                            <textarea
                                className="w-full h-24 p-2 bg-gray-900 border border-gray-600 rounded-md focus:ring-1 focus:ring-indigo-500 text-xs text-white placeholder-gray-600"
                                placeholder='e.g., "Create a JSON profile focusing on color psychology and object relationships."'
                                value={userPrompt}
                                onChange={(e) => setUserPrompt(e.target.value)}
                            />
                            <Button 
                                onClick={() => runAnalysis(userPrompt)} 
                                variant="secondary" 
                                className="w-full mt-2 text-xs"
                                disabled={!userPrompt.trim()}
                            >
                                Run Custom Analysis
                            </Button>
                        </div>
                    </div>
                </div>
            </div>
            <div className="text-xs text-gray-500 italic">
                Profiles include style, objects, technical metadata, and semantic context.
            </div>
        </div>
    );
};

const ImageGeneratorPanel: React.FC<Pick<ControlsPanelProps, 'setLoading' | 'setError' | 'onGenerationComplete'>> = ({ setLoading, setError, onGenerationComplete }) => {
  const [input, setInput] = useState('');

  const handleGenerate = async () => {
    if (!input.trim()) return;
    setLoading(true, "Generating image...");
    setError(null);
    try {
      // Pass the progress callback to handle progression_text from JSON input
      const resultUrl = await generateImageFromInput(input, (msg) => setLoading(true, msg));
      onGenerationComplete({ type: 'image', url: resultUrl });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to generate image.");
    } finally {
      setLoading(false, "");
    }
  };

  return (
    <div className="flex flex-col h-full space-y-6">
      <h2 className="text-xl font-bold text-white flex items-center gap-2">
          <PhotoIcon className="w-6 h-6" /> Image Generator
      </h2>

      <div className="flex-grow space-y-4">
        <p className="text-gray-400 text-sm">
            Enter a text prompt or paste a JSON configuration object.
        </p>

        <div className="flex-grow">
          <label className="block text-sm font-medium text-gray-300 mb-2">Prompt / JSON Input</label>
          <textarea
            className="w-full h-64 p-3 bg-gray-800 border border-gray-700 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-white placeholder-gray-500 resize-none font-mono text-sm"
            placeholder={'e.g. "A magical forest"\n\nOR\n\n{\n  "prompt": "A magical forest",\n  "transparent_background": true\n}'}
            value={input}
            onChange={(e) => setInput(e.target.value)}
          />
        </div>
      </div>

      <Button onClick={handleGenerate} disabled={!input.trim()} className="w-full py-3">
        Generate Image
      </Button>
    </div>
  );
};

const ImageEditor: React.FC<Pick<ControlsPanelProps, 'setLoading' | 'setError' | 'onGenerationComplete'>> = ({ setLoading, setError, onGenerationComplete }) => {
