};

export const generateJsonContextProfile = async (imageFile: File, userPrompt?: string): Promise<any> => {
    const ai = getGenAI();
    const imagePart = await fileToGenerativePart(imageFile);

    let baseInstruction = "Extract an expanded, detailed Advanced JSON Context Profile for this image. Include hierarchical data for: object detection, scene description, style, artistic characteristics, semantic/emotional interpretation, color, lighting, composition, and perceived technical metadata.";

    if (userPrompt) {
        baseInstruction += ` ADJUST YOUR ANALYSIS FOCUS BASED ON THIS USER REQUEST: "${userPrompt}"`;
    }

    const response = await ai.models.generateContent({
        model: MODEL_NAMES.ANALYSIS,
        contents: { parts: [imagePart, { text: baseInstruction }] },
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    metadata: {
                        type: Type.OBJECT,
                        properties: {
                            perceived_resolution: { type: Type.STRING },
                            quality_score: { type: Type.NUMBER },
                            analysis_timestamp: { type: Type.STRING }
                        },
                        required: ["perceived_resolution"]
                    },
                    objects: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                label: { type: Type.STRING },
                                description: { type: Type.STRING },
                                coordinates: { type: Type.STRING },
                                confidence: { type: Type.NUMBER }
                            },
                            required: ["label", "description"]
                        }
                    },
                    scene: {
                        type: Type.OBJECT,
                        properties: {
                            setting: { type: Type.STRING },
                            description: { type: Type.STRING },
                            atmosphere: { type: Type.STRING }
                        },
                        required: ["setting", "description"]
                    },
                    style: {
                        type: Type.OBJECT,
                        properties: {
                            medium: { type: Type.STRING },
                            artistic_era: { type: Type.STRING },
                            technique: { type: Type.STRING }
                        },
                        required: ["medium"]
                    },
                    semantics: {
                        type: Type.OBJECT,
                        properties: {
                            emotions: { type: Type.ARRAY, items: { type: Type.STRING } },
                            themes: { type: Type.ARRAY, items: { type: Type.STRING } },
                            symbolism: { type: Type.STRING }
                        }
                    },
                    visual_analysis: {
                        type: Type.OBJECT,
                        properties: {
                            color_palette: { type: Type.ARRAY, items: { type: Type.STRING } },
                            lighting: { type: Type.STRING },
                            composition: { type: Type.STRING }
                        }
                    },
                    custom_insights: {
                        type: Type.ARRAY,
                        items: { type: Type.STRING },
                        description: "Additional relevant structured insights based on the prompt or content."
                    }
                },
                required: ["metadata", "objects", "scene", "style", "visual_analysis"]
            }
        }
    });

    const text = response.text;
    if (!text) throw new Error("Analysis failed: Empty response from AI.");
    return JSON.parse(text);
};

export const generateCharacterImage = async (prompt: string): Promise<string> => {
  const ai = getGenAI();
  const response = await ai.models.generateImages({
    model: MODEL_NAMES.IMAGE_GENERATION,
    prompt,
    config: {
      numberOfImages: 1,
      outputMimeType: 'image/jpeg',
      aspectRatio: '1:1',
    },
  });

  if (response.generatedImages && response.generatedImages.length > 0) {
    const base64ImageBytes = response.generatedImages[0].image.imageBytes;
    return `data:image/jpeg;base64,${base64ImageBytes}`;
  }
  throw new Error("Image generation failed.");
};

export const generateImageFromInput = async (input: string, onProgress?: (message: string) => void): Promise<string> => {
  const ai = getGenAI();
  let prompt = input;
  let outputMimeType = 'image/jpeg';

  try {
    const json = JSON.parse(input);
    if (json.prompt) {
      prompt = json.prompt;
      if (json.transparent_background) {
         prompt += ", transparent background";
         outputMimeType = 'image/png';
      }
      if (json.progression_text && onProgress) {
          onProgress(json.progression_text);
      }
    }
  } catch (e) {
    // Input is not JSON, treat as raw text prompt
  }

  const response = await ai.models.generateImages({
    model: MODEL_NAMES.IMAGE_GENERATION,
    prompt,
    config: {
      numberOfImages: 1,
      outputMimeType: outputMimeType,
      aspectRatio: '1:1',
    },
  });

  if (response.generatedImages && response.generatedImages.length > 0) {
    const base64ImageBytes = response.generatedImages[0].image.imageBytes;
    return `data:${outputMimeType};base64,${base64ImageBytes}`;
  }
  throw new Error("Image generation failed.");
};

const processCharacterImage = async (base64Str: string, rotation: number = 0, maxSize: number = 512): Promise<string> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = base64Str;
        img.onload = () => {
            const canvas = document.createElement('canvas');
            let width = img.width;
            let height = img.height;

            if (width > maxSize || height > maxSize) {
                const ratio = Math.min(maxSize / width, maxSize / height);
                width = width * ratio;
                height = height * ratio;
            }

            const rad = (rotation * Math.PI) / 180;
            const sin = Math.abs(Math.sin(rad));
            const cos = Math.abs(Math.cos(rad));

            canvas.width = width * cos + height * sin;
            canvas.height = width * sin + height * cos;

            const ctx = canvas.getContext('2d');
            if (!ctx) { resolve(base64Str); return; }

            ctx.imageSmoothingEnabled = true;
            ctx.imageSmoothingQuality = 'high';

            ctx.translate(canvas.width / 2, canvas.height / 2);
            ctx.rotate(rad);
            ctx.drawImage(img, -width / 2, -height / 2, width, height);

            resolve(canvas.toDataURL('image/png'));
        };
        img.onerror = () => resolve(base64Str);
    });
};

export const generateScene = async (characters: Character[], scenePrompt: string, rotations?: Record<string, number>, onProgress?: (message: string) => void): Promise<string> => {
    const ai = getGenAI();
    let finalPrompt = scenePrompt;
    let explicitTransparent = false;

    try {
        const json = JSON.parse(scenePrompt);
        if (json.prompt) {
            finalPrompt = json.prompt;
            if (json.transparent_background) {
                explicitTransparent = true;
            }
            if (json.progression_text && onProgress) {
                onProgress(json.progression_text);
            }
        }
    } catch (e) {
    }

    const parts: Part[] = [];

    for (const character of characters) {
        let imageUrl = character.imageUrl;
        imageUrl = await processCharacterImage(imageUrl, rotations?.[character.id] || 0, 512);
        const matches = imageUrl.match(/^data:(.+);base64,(.+)$/);
        if (matches) {
            const mimeType = matches[1];
            const base64Data = matches[2];
            parts.push({
                inlineData: {
                    data: base64Data,
                    mimeType: mimeType,
                },
            });
        }
    }

    let layeringInstruction = '';
    if (characters.length > 1) {
        const layerDescriptions = characters.map((char, index) => {
            if (index === 0) return `${char.name} is in the background`;
            if (index === characters.length - 1) return `${char.name} is in the foreground`;
            return `${char.name} is behind ${characters[index + 1].name} and in front of ${characters[index - 1].name}`;
        }).join('. ');
        layeringInstruction = `Pay close attention to the layering: ${layerDescriptions}. `;
    }

    let fullPrompt = `Create a new scene featuring the ${characters.length} character(s) from the provided image(s). ${layeringInstruction}Scene details: ${finalPrompt}. Maintain the characters' appearance and style as closely as possible.`;

    if (explicitTransparent) {
        fullPrompt += " The background should be transparent or solid white to easily isolate the subjects.";
    }

    parts.push({ text: fullPrompt });

    const response = await ai.models.generateContent({
        model: MODEL_NAMES.IMAGE_EDITING,
        contents: { parts },
        config: {
            responseModalities: [Modality.IMAGE],
        },
    });

    for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
    }

    throw new Error("Scene generation failed to produce an image.");
};

