export const generateCharacterSpeech = async (text: string, voiceName: string): Promise<string> => {
  const ai = getGenAI();
  const response = await ai.models.generateContent({
    model: MODEL_NAMES.TTS,
    contents: { parts: [{ text }] },
    config: {
      responseModalalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) {
    throw new Error("Failed to generate audio.");
  }

  const pcmData = base64ToUint8Array(base64Audio);
  const wavBlob = createWavBlob(pcmData);

  return URL.createObjectURL(wavBlob);
};


export const generateVideo = async (
    imageFile: File,
    prompt: string,
    aspectRatio: AspectRatio,
    onProgress: (message: string) => void
): Promise<string> => {
    onProgress("Initializing video generation...");
    const ai = getGenAI();

    let operation = await ai.models.generateVideos({
        model: MODEL_NAMES.VIDEO_GENERATION,
        prompt,
        image: {
            imageBytes: (await fileToBase64(imageFile)).split(',')[1],
            mimeType: imageFile.type,
        },
        config: {
            numberOfVideos: 1,
            resolution: '720p',
            aspectRatio: aspectRatio,
        }
    });

    const progressMessages = [
      "Summoning digital muses...",
      "Warming up the pixels...",
      "Choreographing the animation...",
      "Rendering the first frames...",
      "Almost there, adding the final sparkle...",
    ];
    let messageIndex = 0;

    while (!operation.done) {
        onProgress(progressMessages[messageIndex % progressMessages.length]);
        messageIndex++;
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
    }

    onProgress("Finalizing video...");
    const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
    if (!downloadLink) {
        throw new Error("Video generation did not return a valid link.");
    }

    const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
    const videoBlob = await response.blob();
    return URL.createObjectURL(videoBlob);
};

export const animateImage = async (
    imageFile: File,
    input: string,
    aspectRatio: AspectRatio,
    onProgress: (message: string) => void
): Promise<string> => {
    let prompt = input;

    try {
        const json = JSON.parse(input);
        if (json.prompt) {
            prompt = json.prompt;
            if (json.transparent_background) {
               prompt += ". Keep background solid or simple to easily isolate subjects.";
            }
            if (json.progression_text) {
                onProgress(json.progression_text);
            }
        }
    } catch (e) {
    }

    return generateVideo(imageFile, prompt, aspectRatio, onProgress);
};

import React, { useState, useCallback } from 'react';
import { AspectRatio, Character, ToolType, SoundEffect, Scene } from '../types';
import { Button } from './common/Button';
import { generateScene, editImage, generateVideo, generateCharacterSpeech, generateImageFromInput, animateImage, generateJsonContextProfile, generateCharacterFromJson, generateCharacterDirectly } from '../services/geminiService';
import { ApiKeySelector } from './ApiKeySelector';
import { SaveIcon, VOICE_NAMES, UploadIcon, MusicIcon, TrashIcon, FilePlusIcon, ExportIcon, PhotoIcon, SparklesIcon, CodeBracketIcon, AddUserIcon } from '../constants';
