interface ControlsPanelProps {
  activeTool: ToolType;
  selectedCharacters: Character[];
  setLoading: (isLoading: boolean, message: string) => void;
  setError: (error: string | null) => void;
  onGenerationComplete: (content: { type: 'image' | 'video' | 'audio' | 'json'; url: string; data?: any; characterId?: string; soundEffectUrl?: string }) => void;
  onSaveCharacter: (character: Character) => void;

  // Scene Builder Props
  scenePrompt: string;
  setScenePrompt: (prompt: string) => void;
  onSaveScene: (name: string) => void;
  currentSceneName?: string;
  sceneSoundEffect: SoundEffect | undefined;
  setSceneSoundEffect: (sound: SoundEffect | undefined) => void;
  soundLibrary: SoundEffect[];
  setSoundLibrary: (library: SoundEffect[]) => void;
  characterRotations: Record<string, number>;
  onResetScene: () => void;
  scenes: Scene[];
  onLoadScene: (scene: Scene) => void;
  onExportScene: () => void;
}

const SceneBuilder: React.FC<Omit<ControlsPanelProps, 'activeTool'>> = ({ 
  selectedCharacters, 
  setLoading, 
  setError, 
  onGenerationComplete,
  scenePrompt,
  setScenePrompt,
  onSaveScene,
  currentSceneName,
  sceneSoundEffect,
  setSceneSoundEffect,
  soundLibrary,
  setSoundLibrary,
  characterRotations,
  onResetScene,
  scenes,
  onLoadScene,
  onExportScene
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const [sceneName, setSceneName] = useState('');
  const [soundTab, setSoundTab] = useState<'SELECT' | 'UPLOAD'>('SELECT');
  const [sceneToLoad, setSceneToLoad] = useState('');

  const handleGenerate = useCallback(async () => {
    if (selectedCharacters.length === 0) {
      setError("Please select at least one character from the library.");
      return;
    }
    setLoading(true, "Building your scene...");
    setError(null);
    try {
      const imageUrl = await generateScene(
          selectedCharacters, 
          scenePrompt, 
          characterRotations, 
          (msg) => setLoading(true, msg)
      );
      onGenerationComplete({ 
        type: 'image', 
        url: imageUrl, 
        soundEffectUrl: sceneSoundEffect?.url 
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to generate scene.");
    } finally {
      setLoading(false, "");
    }
  }, [selectedCharacters, scenePrompt, setLoading, setError, onGenerationComplete, sceneSoundEffect, characterRotations]);

  const initiateSave = () => {
    if (selectedCharacters.length === 0) {
        setError("Add characters to save a scene.");
        return;
    }
    setError(null);
    setSceneName(currentSceneName || '');
    setIsSaving(true);
  }

  const confirmSave = () => {
      if (sceneName.trim()) {
          onSaveScene(sceneName);
          setIsSaving(false);
      }
  };

  const handleSoundUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          try {
              const base64 = await fileToBase64(file);
              const newSound: SoundEffect = {
                  id: crypto.randomUUID(),
                  name: file.name.replace(/\.[^/.]+$/, ""),
                  url: base64
              };
              setSoundLibrary([...soundLibrary, newSound]);
              setSceneSoundEffect(newSound);
          } catch (err) {
              console.error("Audio upload failed", err);
              setError("Failed to upload audio.");
          }
      }
  };

  const handleLoadSelect = (e: React.ChangeEvent<HTMLSelectElement>) => {
      const sceneId = e.target.value;
      setSceneToLoad(sceneId);
      const scene = scenes.find(s => s.id === sceneId);
      if (scene) {
          onLoadScene(scene);
      }
  };

  return (
    <div className="flex flex-col h-full">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-xl font-bold text-white">Scene Builder</h2>
        <div className="flex gap-2">
           <Button onClick={onResetScene} variant="secondary" className="px-2" title="New Scene">
              <FilePlusIcon className="w-4 h-4" />
           </Button>
           <div className="relative">
              <select 
                value={sceneToLoad} 
                onChange={handleLoadSelect}
                className="bg-gray-700 text-white text-xs rounded px-2 py-2 border border-gray-600 focus:outline-none focus:border-indigo-500 max-w-[100px]"
              >
                  <option value="" disabled>Load...</option>
                  {scenes.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
              </select>
           </div>
        </div>
      </div>

      <div className="flex-grow overflow-y-auto pr-2 space-y-6">
          <div className="space-y-2">
            <label className="block text-sm font-medium text-gray-300">Scene Description</label>
            <textarea
              className="w-full h-32 p-3 bg-gray-800 border border-gray-700 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-white placeholder-gray-500 resize-none"
              placeholder="Describe the scene setting, lighting, and action..."
              value={scenePrompt}
              onChange={(e) => setScenePrompt(e.target.value)}
            />
          </div>

          <div className="space-y-2 bg-gray-800/50 p-3 rounded-lg border border-gray-700">
             <div className="flex justify-between items-center mb-2">
                 <label className="text-sm font-medium text-gray-300 flex items-center gap-2">
                    <MusicIcon className="w-4 h-4 text-indigo-400" />
                    Sound Effect / Ambience
                 </label>
                 {sceneSoundEffect && (
                     <button 
                        onClick={() => setSceneSoundEffect(undefined)}
                        className="text-xs text-red-400 hover:text-red-300 flex items-center gap-1"
                     >
                         <TrashIcon className="w-3 h-3" /> Clear
                     </button>
                 )}
             </div>

             <div className="flex gap-2 mb-2">
                 <button 
                    onClick={() => setSoundTab('SELECT')}
                    className={`flex-1 text-xs py-1 rounded ${soundTab === 'SELECT' ? 'bg-indigo-600 text-white' : 'bg-gray-700 text-gray-400'}`}
                 >
                     Library
                 </button>
                 <button 
                    onClick={() => setSoundTab('UPLOAD')}
                    className={`flex-1 text-xs py-1 rounded ${soundTab === 'UPLOAD' ? 'bg-indigo-600 text-white' : 'bg-gray-700 text-gray-400'}`}
                 >
                     Upload
                 </button>
             </div>

             {soundTab === 'SELECT' ? (
                 <select 
                    value={sceneSoundEffect?.id || ''}
                    onChange={(e) => setSceneSoundEffect(soundLibrary.find(s => s.id === e.target.value))}
                    className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-sm text-white"
                 >
                     <option value="">None selected</option>
                     {soundLibrary.map(sound => (
                         <option key={sound.id} value={sound.id}>{sound.name}</option>
                     ))}
                 </select>
             ) : (
                 <div className="border-2 border-dashed border-gray-600 rounded p-4 text-center hover:bg-gray-700/50 transition-colors cursor-pointer relative">
                     <input 
                        type="file" 
                        accept="audio/*" 
                        onChange={handleSoundUpload}
                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                     />
                     <UploadIcon className="w-6 h-6 mx-auto text-gray-400 mb-1" />
                     <p className="text-xs text-gray-400">Click to upload audio</p>
                 </div>
             )}

             {sceneSoundEffect && (
                 <div className="text-xs text-indigo-300 mt-1 flex items-center gap-1">
                     <span>Selected: {sceneSoundEffect.name}</span>
                 </div>
             )}
          </div>
      </div>

      <div className="pt-4 mt-auto border-t border-gray-700 flex flex-col gap-3">
        <Button onClick={handleGenerate} className="w-full py-3 text-lg shadow-lg shadow-indigo-500/20">
          Generate Scene
        </Button>

        <div className="flex gap-2">
            {isSaving ? (
                <div className="flex-1 flex gap-2">
                    <input 
                        type="text" 
                        value={sceneName}
                        onChange={(e) => setSceneName(e.target.value)}
                        placeholder="Scene Name"
                        className="flex-1 bg-gray-800 border border-gray-600 rounded px-2 text-sm"
                        autoFocus
                    />
                    <Button onClick={confirmSave} className="px-3 py-1 text-sm">Save</Button>
                    <Button onClick={() => setIsSaving(false)} variant="secondary" className="px-3 py-1 text-sm">Cancel</Button>
                </div>
            ) : (
                <Button onClick={initiateSave} variant="secondary" className="flex-1" title="Save Scene">
                  <SaveIcon className="w-4 h-4 mr-2" /> Save Scene
                </Button>
            )}
            <Button onClick={onExportScene} variant="secondary" className="px-3" title="Export JSON">
                <ExportIcon className="w-5 h-5" />
            </Button>
        </div>
      </div>
    </div>
  );
};

const JSONProfilerPanel: React.FC<Pick<ControlsPanelProps, 'setLoading' | 'setError' | 'onGenerationComplete' | 'onSaveCharacter'>> = ({ setLoading, setError, onGenerationComplete, onSaveCharacter }) => {
    const [imageFile, setImageFile] = useState<File | null>(null);
    const [previewUrl, setPreviewUrl] = useState<string>('');
    const [userPrompt, setUserPrompt] = useState('');
    const [lastJson, setLastJson] = useState<any | null>(null);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            setImageFile(file);
            setPreviewUrl(URL.createObjectURL(file));
            setLastJson(null);
        }
    };

    const runAnalysis = async (customPrompt?: string) => {
        if (!imageFile) {
            setError("Please upload an image first.");
            return;
        }
        setLoading(true, "Analyzing image structure...");
        setError(null);
        try {
            const data = await generateJsonContextProfile(imageFile, customPrompt);
            setLastJson(data);
            const jsonString = JSON.stringify(data, null, 2);
            const blob = new Blob([jsonString], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            onGenerationComplete({ 
                type: 'json', 
                url: url,
                data: data 
            });
        } catch (err) {
            setError(err instanceof Error ? err.message : "JSON Profile extraction failed.");
        } finally {
            setLoading(false, "");
        }
    };

    const handleCreateCharacterFromJson = async () => {
        if (!lastJson) return;
        setLoading(true, "Creating character from JSON profile...");
        setError(null);
        try {
            const { url, prompt } = await generateCharacterFromJson(lastJson);
            const newChar: Character = {
                id: crypto.randomUUID(),
                name: `JSON-Based ${lastJson.objects?.[0]?.label || 'Character'}`,
                imageUrl: url,
                prompt: prompt
            };
            onSaveCharacter(newChar);
            onGenerationComplete({ type: 'image', url: url });
        } catch (err) {
            setError(err instanceof Error ? err.message : "Failed to create character from JSON.");
        } finally {
            setLoading(false, "");
        }
    };

    const handleDirectCharacterCreation = async () => {
        if (!imageFile) return;
        setLoading(true, "Directly creating character from image...");
        setError(null);
        try {
            const { url, prompt } = await generateCharacterDirectly(imageFile);
            const newChar: Character = {
                id: crypto.randomUUID(),
                name: `Direct Image Character`,
                imageUrl: url,
                prompt: prompt
            };
            onSaveCharacter(newChar);
            onGenerationComplete({ type: 'image', url: url });
        } catch (err) {
            setError(err instanceof Error ? err.message : "Failed to directly create character.");
        } finally {
            setLoading(false, "");
        }
    };

    return (
        <div className="flex flex-col h-full space-y-4">
            <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <CodeBracketIcon className="w-6 h-6 text-indigo-400" /> JSON Profiler
            </h2>
            <div className="flex-grow space-y-4 overflow-y-auto pr-2">
                <div className="border-2 border-dashed border-gray-600 rounded-lg p-6 text-center hover:border-indigo-500 transition-colors cursor-pointer relative h-40 flex items-center justify-center bg-gray-800/30">
                    <input
                        type="file"
                        accept="image/*"
                        onChange={handleFileChange}
                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                    />
                    {previewUrl ? (
                        <img src={previewUrl} alt="Preview" className="max-h-full max-w-full object-contain rounded" />
                    ) : (
                        <div className="flex flex-col items-center">
                            <UploadIcon className="w-8 h-8 text-gray-400 mb-2" />
                            <p className="text-gray-400 text-xs">Upload Image</p>
                        </div>
                    )}
                </div>

                <div className="space-y-3">
                    <div className="flex gap-2">
                         <Button 
                            onClick={handleDirectCharacterCreation} 
                            disabled={!imageFile}
                            className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-xs py-2"
                        >
                            <AddUserIcon className="w-4 h-4" /> Direct Character
                        </Button>
                    </div>

                    <div className="p-3 bg-gray-800/50 rounded-lg border border-gray-700 space-y-3">
                        <div className="space-y-2">
                             <Button onClick={() => runAnalysis()} disabled={!imageFile} className="w-full bg-indigo-600 hover:bg-indigo-500 text-xs">
                                Extract JSON Profile
                            </Button>

                            <Button 
                                onClick={handleCreateCharacterFromJson} 
                                disabled={!lastJson}
                                variant="secondary"
                                className={`w-full text-xs ${lastJson ? 'border-indigo-500 text-indigo-300' : ''}`}
                            >
                                <AddUserIcon className="w-4 h-4" /> Create Character (from Profile)
                            </Button>
                        </div>

                        <div className="border-t border-gray-700 pt-3">
                            <p className="text-[10px] uppercase font-bold text-gray-500 mb-2">Prompt-Based Extraction</p>
                            <textarea
                                className="w-full h-16 p-2 bg-gray-900 border border-gray-600 rounded-md focus:ring-1 focus:ring-indigo-500 text-xs text-white placeholder-gray-600"
                                placeholder='Focus e.g. "Color psychology..."'
                                value={userPrompt}
                                onChange={(e) => setUserPrompt(e.target.value)}
                            />
                            <Button 
                                onClick={() => runAnalysis(userPrompt)} 
                                variant="secondary" 
                                className="w-full mt-2 text-xs py-1"
                                disabled={!userPrompt.trim() || !imageFile}
