import { GoogleGenAI, Modality, Part, Type } from "@google/genai";
import { MODEL_NAMES } from '../constants';
import { fileToGenerativePart, fileToBase64 } from '../utils/fileUtils';
import { base64ToUint8Array, createWavBlob } from '../utils/audioUtils';
import { AspectRatio, Character } from '../types';

const getGenAI = () => {
  if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
}

export const generateCharacterDescription = async (imageFile: File): Promise<string> => {
  const ai = getGenAI();
  const imagePart = await fileToGenerativePart(imageFile);
  const textPart = { text: "Describe the character in this image in detail for a character design sheet. Focus on visual traits like hair, eyes, clothing, style, and key features. The description will be used to generate new images of this character." };

  const response = await ai.models.generateContent({
    model: MODEL_NAMES.DESCRIPTION_GENERATION,
    contents: { parts: [imagePart, textPart] },
  });

  return response.text || '';
};

export const generateCharacterFromJson = async (jsonProfile: any): Promise<{ url: string; prompt: string }> => {
  const ai = getGenAI();

  const response = await ai.models.generateContent({
    model: MODEL_NAMES.ANALYSIS,
    contents: `Based on this Advanced JSON Context Profile, write a detailed physical description for a character design sheet. Focus on facial structure, expression, hair, specific clothing details, textures, logos, body proportions, and visual style. The goal is to generate a new character image that perfectly matches this profile. JSON: ${JSON.stringify(jsonProfile)}`,
  });

  const prompt = response.text || "A character based on structured visual metadata.";
  const url = await generateCharacterImage(prompt);

  return { url, prompt };
};

export const generateCharacterDirectly = async (imageFile: File): Promise<{ url: string; prompt: string; json?: any }> => {
  // First get description
  const description = await generateCharacterDescription(imageFile);
  // Also try to get a quick JSON profile for future editing
  let jsonProfile = null;
  try {
      jsonProfile = await generateJsonContextProfile(imageFile, "Extract character-centric metadata for future editing.");
  } catch (e) {
      console.warn("Could not extract JSON profile during direct creation", e);
  }

  const url = await generateCharacterImage(description);
  return { url, prompt: description, json: jsonProfile };
};

export const refineCharacter = async (character: Character, updatedJson: any, changeInstructions: string): Promise<string> => {
    const ai = getGenAI();

    // Extract base64 from current image
    const matches = character.imageUrl.match(/^data:(.+);base64,(.+)$/);
    if (!matches) throw new Error("Invalid character image URL");

    const mimeType = matches[1];
    const base64Data = matches[2];

    const prompt = `Refine this character based on the following updates. 
    New Context Profile (JSON): ${JSON.stringify(updatedJson)}
    Specific Change Instructions: ${changeInstructions}
    Maintain the identity of the character while applying these modifications precisely.`;

    const response = await ai.models.generateContent({
        model: MODEL_NAMES.IMAGE_EDITING,
        contents: {
            parts: [
                { inlineData: { data: base64Data, mimeType } },
                { text: prompt }
            ]
        },
        config: {
            responseModalities: [Modality.IMAGE],
        },
    });

    for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
    }
    throw new Error("Character refinement failed.");
};

export const generateJsonContextProfile = async (imageFile: File, userPrompt?: string): Promise<any> => {
    const ai = getGenAI();
    const imagePart = await fileToGenerativePart(imageFile);

    let baseInstruction = "Extract an expanded, detailed Advanced JSON Context Profile for this image. Include hierarchical data for: object detection, scene description, style, artistic characteristics, semantic/emotional interpretation, color, lighting, composition, and perceived technical metadata.";

    if (userPrompt) {
        baseInstruction += ` ADJUST YOUR ANALYSIS FOCUS BASED ON THIS USER REQUEST: "${userPrompt}"`;
    }

    const response = await ai.models.generateContent({
        model: MODEL_NAMES.ANALYSIS,
        contents: { parts: [imagePart, { text: baseInstruction }] },
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    metadata: {
                        type: Type.OBJECT,
                        properties: {
                            perceived_resolution: { type: Type.STRING },
                            quality_score: { type: Type.NUMBER },
                            analysis_timestamp: { type: Type.STRING }
                        },
                        required: ["perceived_resolution"]
                    },
                    objects: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                label: { type: Type.STRING },
                                description: { type: Type.STRING },
                                coordinates: { type: Type.STRING },
                                confidence: { type: Type.NUMBER }
                            },
                            required: ["label", "description"]
                        }
                    },
                    scene: {
                        type: Type.OBJECT,
                        properties: {
                            setting: { type: Type.STRING },
                            description: { type: Type.STRING },
                            atmosphere: { type: Type.STRING }
                        },
                        required: ["setting", "description"]
                    },
                    style: {
                        type: Type.OBJECT,
                        properties: {
                            medium: { type: Type.STRING },
                            artistic_era: { type: Type.STRING },
                            technique: { type: Type.STRING }
                        },
                        required: ["medium"]
                    },
                    semantics: {
                        type: Type.OBJECT,
                        properties: {
                            emotions: { type: Type.ARRAY, items: { type: Type.STRING } },
                            themes: { type: Type.ARRAY, items: { type: Type.STRING } },
                            symbolism: { type: Type.STRING }
                        }
                    },
                    visual_analysis: {
                        type: Type.OBJECT,
                        properties: {
                            color_palette: { type: Type.ARRAY, items: { type: Type.STRING } },
                            lighting: { type: Type.STRING },
                            composition: { type: Type.STRING }
                        }
                    },
                    custom_insights: {
                        type: Type.ARRAY,
                        items: { type: Type.STRING },
                        description: "Additional relevant structured insights based on the prompt or content."
                    }
                },
                required: ["metadata", "objects", "scene", "style", "visual_analysis"]
            }
        }
    });

    const text = response.text;
    if (!text) throw new Error("Analysis failed: Empty response from AI.");
    return JSON.parse(text);
};

