export const refineCharacter = async (character: Character, updatedJson: any, changeInstructions: string): Promise<string> => {
    const ai = getGenAI();

    const matches = character.imageUrl.match(/^data:(.+);base64,(.+)$/);
    if (!matches) throw new Error("Invalid character image URL");

    const mimeType = matches[1];
    const base64Data = matches[2];

    const prompt = `Refine this character based on the following updates. 
    New Context Profile (JSON): ${JSON.stringify(updatedJson)}
    Specific Change Instructions: ${changeInstructions}
    Maintain the identity of the character while applying these modifications precisely. Result must be on a white background.`;

    const response = await ai.models.generateContent({
        model: MODEL_NAMES.IMAGE_EDITING,
        contents: {
            parts: [
                { inlineData: { data: base64Data, mimeType } },
                { text: prompt }
            ]
        },
    });

    for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
    }
    throw new Error("Character refinement failed.");
};

export const generateJsonContextProfile = async (imageFile: File, userPrompt?: string): Promise<any> => {
    const ai = getGenAI();
    const imagePart = await fileToGenerativePart(imageFile);

    let baseInstruction = "Extract an expanded, detailed Advanced JSON Context Profile for this image. Include hierarchical data for: object detection, scene description, style, artistic characteristics, semantic/emotional interpretation, color, lighting, composition, and perceived technical metadata.";

    if (userPrompt) {
        baseInstruction += ` ADJUST YOUR ANALYSIS FOCUS BASED ON THIS USER REQUEST: "${userPrompt}"`;
    }

    const response = await ai.models.generateContent({
        model: MODEL_NAMES.ANALYSIS,
        contents: { parts: [imagePart, { text: baseInstruction }] },
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    metadata: {
                        type: Type.OBJECT,
                        properties: {
                            perceived_resolution: { type: Type.STRING },
                            quality_score: { type: Type.NUMBER },
                            analysis_timestamp: { type: Type.STRING }
                        },
                        required: ["perceived_resolution"]
                    },
                    objects: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                label: { type: Type.STRING },
                                description: { type: Type.STRING },
                                coordinates: { type: Type.STRING },
                                confidence: { type: Type.NUMBER }
                            },
                            required: ["label", "description"]
                        }
                    },
                    scene: {
                        type: Type.OBJECT,
                        properties: {
                            setting: { type: Type.STRING },
                            description: { type: Type.STRING },
                            atmosphere: { type: Type.STRING }
                        },
                        required: ["setting", "description"]
                    },
                    style: {
                        type: Type.OBJECT,
                        properties: {
                            medium: { type: Type.STRING },
                            artistic_era: { type: Type.STRING },
                            technique: { type: Type.STRING }
                        },
                        required: ["medium"]
                    },
                    semantics: {
                        type: Type.OBJECT,
                        properties: {
                            emotions: { type: Type.ARRAY, items: { type: Type.STRING } },
                            themes: { type: Type.ARRAY, items: { type: Type.STRING } },
                            symbolism: { type: Type.STRING }
                        }
                    },
                    visual_analysis: {
                        type: Type.OBJECT,
                        properties: {
                            color_palette: { type: Type.ARRAY, items: { type: Type.STRING } },
                            lighting: { type: Type.STRING },
                            composition: { type: Type.STRING }
                        }
                    },
                    custom_insights: {
                        type: Type.ARRAY,
                        items: { type: Type.STRING },
                        description: "Additional relevant structured insights based on the prompt or content."
                    }
                },
                required: ["metadata", "objects", "scene", "style"]
            },
        },
    });

    const jsonStr = response.text?.trim() || "{}";
    return JSON.parse(jsonStr);
};

