        <div>
          <label className="block text-sm font-medium text-gray-300 mb-2">Voice Style</label>
          <div className="grid grid-cols-2 gap-2">
            {VOICE_NAMES.map(voice => (
              <button
                key={voice}
                onClick={() => setSelectedVoice(voice)}
