import React, { useState, useCallback, useEffect, useRef } from 'react';
import { Character, ToolType, GeneratedContent, Scene, SoundEffect } from './types';
import { Header } from './components/Header';
import { Sidebar } from './components/Sidebar';
import { Canvas } from './components/Canvas';
import { ControlsPanel } from './components/ControlsPanel';
import { CharacterCreatorModal } from './components/CharacterCreatorModal';
import { downloadJson } from './utils/fileUtils';

function App() {
  const [characters, setCharacters] = useState<Character[]>([]);
  const [scenes, setScenes] = useState<Scene[]>([]);
  const [soundLibrary, setSoundLibrary] = useState<SoundEffect[]>([]);

  const [activeTool, setActiveTool] = useState<ToolType>('SCENE_BUILDER');
  const [selectedCharacterIds, setSelectedCharacterIds] = useState<string[]>([]);
  const [scenePrompt, setScenePrompt] = useState('Two characters having a picnic in a sunny park.');
  const [sceneSoundEffect, setSceneSoundEffect] = useState<SoundEffect | undefined>(undefined);

  const [currentSceneId, setCurrentSceneId] = useState<string | null>(null);

  const [characterRotations, setCharacterRotations] = useState<Record<string, number>>({});
  const [characterPositions, setCharacterPositions] = useState<Record<string, { x: number; y: number }>>({});

  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [generatedContent, setGeneratedContent] = useState<GeneratedContent | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [isCreatorModalOpen, setIsCreatorModalOpen] = useState(false);

  const scenePromptRef = useRef(scenePrompt);
  const selectedCharacterIdsRef = useRef(selectedCharacterIds);
  const characterRotationsRef = useRef(characterRotations);
  const characterPositionsRef = useRef(characterPositions);
  const sceneSoundEffectRef = useRef(sceneSoundEffect);

  useEffect(() => {
    scenePromptRef.current = scenePrompt;
  }, [scenePrompt]);

  useEffect(() => {
    selectedCharacterIdsRef.current = selectedCharacterIds;
  }, [selectedCharacterIds]);

  useEffect(() => {
    characterRotationsRef.current = characterRotations;
  }, [characterRotations]);

  useEffect(() => {
    characterPositionsRef.current = characterPositions;
  }, [characterPositions]);

  useEffect(() => {
    sceneSoundEffectRef.current = sceneSoundEffect;
  }, [sceneSoundEffect]);


  useEffect(() => {
    try {
      const savedChars = localStorage.getItem('css_characters');
      if (savedChars) {
        setCharacters(JSON.parse(savedChars));
      }
      const savedScenes = localStorage.getItem('css_scenes');
      if (savedScenes) {
        setScenes(JSON.parse(savedScenes));
      }
      const savedSounds = localStorage.getItem('css_sound_library');
      if (savedSounds) {
        setSoundLibrary(JSON.parse(savedSounds));
      }

      const autosavedData = localStorage.getItem('css_autosave');
      if (autosavedData) {
        const parsed = JSON.parse(autosavedData);
        if (parsed.prompt) setScenePrompt(parsed.prompt);
        if (parsed.characterIds) setSelectedCharacterIds(parsed.characterIds);
        if (parsed.rotations) setCharacterRotations(parsed.rotations);
        if (parsed.positions) setCharacterPositions(parsed.positions);
        if (parsed.soundEffect) setSceneSoundEffect(parsed.soundEffect);
      }
    } catch (e) {
      console.error("Failed to load from local storage", e);
    }
  }, []);

  useEffect(() => {
    const interval = setInterval(() => {
      const dataToSave = {
        prompt: scenePromptRef.current,
        characterIds: selectedCharacterIdsRef.current,
        rotations: characterRotationsRef.current,
        positions: characterPositionsRef.current,
        soundEffect: sceneSoundEffectRef.current,
        timestamp: Date.now()
      };
      localStorage.setItem('css_autosave', JSON.stringify(dataToSave));
    }, 60000);

    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    localStorage.setItem('css_characters', JSON.stringify(characters));
  }, [characters]);

  useEffect(() => {
    localStorage.setItem('css_scenes', JSON.stringify(scenes));
  }, [scenes]);

  useEffect(() => {
    localStorage.setItem('css_sound_library', JSON.stringify(soundLibrary));
  }, [soundLibrary]);


  const handleSetLoading = useCallback((loading: boolean, message: string) => {
    setIsLoading(loading);
    setLoadingMessage(message);
  }, []);

  const handleGenerationComplete = useCallback((content: GeneratedContent) => {
    setGeneratedContent(content);
    setError(null);
  }, []);

  const handleCharacterSelect = (id: string) => {
    setSelectedCharacterIds(prev =>
      prev.includes(id) 
        ? prev.filter(charId => charId !== id) 
        : [...prev, id]
    );
  };

  const handleCharacterReorder = useCallback((reorderedCharacters: Character[]) => {
    const newIds = reorderedCharacters.map(c => c.id);
    setSelectedCharacterIds(newIds);
  }, []);

  const handleSaveCharacter = (character: Character) => {
    setCharacters(prev => [...prev, character]);
    setIsCreatorModalOpen(false);
  };

  const handleUpdateCharacter = (updatedChar: Character) => {
    setCharacters(prev => prev.map(c => c.id === updatedChar.id ? updatedChar : c));
  };

  const handleImportCharacter = (character: Character) => {
    if (!characters.some(c => c.id === character.id)) {
        setCharacters(prev => [...prev, character]);
    } else {
        setCharacters(prev => prev.map(c => c.id === character.id ? character : c));
    }
  };

  const handleImportLibrary = (newCharacters: Character[]) => {
     setCharacters(prev => {
         const combined = [...prev];
         newCharacters.forEach(newChar => {
             const existingIndex = combined.findIndex(c => c.id === newChar.id);
             if (existingIndex >= 0) {
                 combined[existingIndex] = newChar;
             } else {
                 combined.push(newChar);
             }
         });
         return combined;
     });
  };

  const handleDeleteCharacter = (id: string) => {
    setCharacters(prev => prev.filter(c => c.id !== id));
    setSelectedCharacterIds(prev => prev.filter(cid => cid !== id));
  };

  const handleSaveScene = (name: string) => {
    const existingScene = scenes.find(s => s.id === currentSceneId);

    if (existingScene && existingScene.name === name) {
        const updatedScene: Scene = {
            ...existingScene,
            characterIds: selectedCharacterIds,
            prompt: scenePrompt,
            soundEffect: sceneSoundEffect,
            rotations: characterRotations,
            positions: characterPositions,
            generatedContent: generatedContent || undefined,
        };
        setScenes(prev => prev.map(s => s.id === currentSceneId ? updatedScene : s));
    } else {
        const newScene: Scene = {
            id: crypto.randomUUID(),
            name,
            characterIds: selectedCharacterIds,
            prompt: scenePrompt,
            createdAt: Date.now(),
            soundEffect: sceneSoundEffect,
            rotations: characterRotations,
            positions: characterPositions,
            generatedContent: generatedContent || undefined,
        };
        setScenes(prev => [newScene, ...prev]);
        setCurrentSceneId(newScene.id);
    }
  };

  const handleLoadScene = (scene: Scene) => {
    setSelectedCharacterIds(scene.characterIds);
    setScenePrompt(scene.prompt);
    setSceneSoundEffect(scene.soundEffect);
    setCharacterRotations(scene.rotations || {});
    setCharacterPositions(scene.positions || {});
    setGeneratedContent(scene.generatedContent || null);
    setCurrentSceneId(scene.id);
    setActiveTool('SCENE_BUILDER');
  };

  const handleImportScene = (scene: Scene) => {
    if (!scenes.some(s => s.id === scene.id)) {
        setScenes(prev => [scene, ...prev]);
    } else {
        setScenes(prev => prev.map(s => s.id === scene.id ? scene : s));
    }
  };

  const handleExportScene = () => {
    const exportName = currentSceneName || "Untitled Scene";
    const sceneData: Scene = {
      id: currentSceneId || crypto.randomUUID(),
      name: exportName,
      characterIds: selectedCharacterIds,
      prompt: scenePrompt,
      createdAt: Date.now(),
      soundEffect: sceneSoundEffect,
      rotations: characterRotations,
      positions: characterPositions,
      generatedContent: generatedContent || undefined
    };

    downloadJson(sceneData, `scene-${exportName.replace(/\s+/g, '_')}.json`);
  };

  const handleDeleteScene = (id: string) => {
    setScenes(prev => prev.filter(s => s.id !== id));
    if (currentSceneId === id) {
        setCurrentSceneId(null);
    }
  };

  const handleResetScene = () => {
    setSelectedCharacterIds([]);
    setScenePrompt('Two characters having a picnic in a sunny park.');
    setSceneSoundEffect(undefined);
    setCharacterRotations({});
    setCharacterPositions({});
    setCurrentSceneId(null);
    setGeneratedContent(null);
    setError(null);
  };

  const selectedCharacters = selectedCharacterIds
    .map(id => characters.find(c => c.id === id))
    .filter((c): c is Character => c !== undefined);

  const currentSceneName = scenes.find(s => s.id === currentSceneId)?.name;

  return (
    <div className="h-screen w-screen flex flex-col bg-gray-900">
      <Header activeTool={activeTool} setActiveTool={setActiveTool} />
      <div className="flex flex-grow overflow-hidden">
        <Sidebar
          characters={characters}
          selectedCharacterIds={selectedCharacterIds}
          onCharacterSelect={handleCharacterSelect}
          onAddCharacterClick={() => setIsCreatorModalOpen(true)}
          onImportCharacter={handleImportCharacter}
          onImportLibrary={handleImportLibrary}
          onDeleteCharacter={handleDeleteCharacter}
          scenes={scenes}
          onSceneSelect={handleLoadScene}
          onImportScene={handleImportScene}
          onSceneDelete={handleDeleteScene}
        />
        <Canvas
          isLoading={isLoading}
          loadingMessage={loadingMessage}
          generatedContent={generatedContent}
          error={error}
          selectedCharacters={selectedCharacters}
          onCharacterReorder={handleCharacterReorder}
          characterRotations={characterRotations}
          onRotationChange={(id, rot) => setCharacterRotations(prev => ({ ...prev, [id]: rot }))}
          characterPositions={characterPositions}
          onPositionChange={(id, pos) => setCharacterPositions(prev => ({ ...prev, [id]: pos }))}
        />
        <ControlsPanel
          activeTool={activeTool}
          characters={characters}
          selectedCharacters={selectedCharacters}
          setLoading={handleSetLoading}
          setError={setError}
          onGenerationComplete={handleGenerationComplete}
          onSaveCharacter={handleSaveCharacter}
          onUpdateCharacter={handleUpdateCharacter}
          scenePrompt={scenePrompt}
          setScenePrompt={setScenePrompt}
          onSaveScene={handleSaveScene}
          currentSceneName={currentSceneName}
          sceneSoundEffect={sceneSoundEffect}
          setSceneSoundEffect={setSceneSoundEffect}
          soundLibrary={soundLibrary}
          setSoundLibrary={setSoundLibrary}
          characterRotations={characterRotations}
          onResetScene={handleResetScene}
          scenes={scenes}
          onLoadScene={handleLoadScene}
          onExportScene={handleExportScene}
        />
      </div>
      {isCreatorModalOpen && (
        <CharacterCreatorModal 
          onClose={() => setIsCreatorModalOpen(false)}
          onSave={handleSaveCharacter}
        />
      )}
    </div>
  );
}

export default App;

import { GoogleGenAI, Modality, Part, Type } from "@google/genai";
import { MODEL_NAMES } from '../constants';
import { fileToGenerativePart, fileToBase64 } from '../utils/fileUtils';
import { base64ToUint8Array, createWavBlob } from '../utils/audioUtils';
import { AspectRatio, Character } from '../types';

const getGenAI = () => {
  if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
}

export const generateRandomName = async (style?: string): Promise<string> => {
  const ai = getGenAI();
  const prompt = `Generate a single, cool, and fitting name for a character with this style: ${style || 'general'}. Return ONLY the name, no extra text.`;

  const response = await ai.models.generateContent({
    model: MODEL_NAMES.ANALYSIS,
    contents: prompt,
  });

  return response.text?.trim() || "Unnamed Character";
};

export const generateCharacterImage = async (prompt: string): Promise<string> => {
  const ai = getGenAI();
  const response = await ai.models.generateContent({
    model: MODEL_NAMES.IMAGE_EDITING,
    contents: { parts: [{ text: `${prompt} The character should be isolated on a plain white background, full body shot, high quality character design.` }] },
    config: {
      imageConfig: { aspectRatio: "1:1" },
      responseModalities: [Modality.IMAGE],
    }
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
  }
  throw new Error("Failed to generate character image.");
};

export const generateCharacterDescription = async (imageFile: File): Promise<string> => {
  const ai = getGenAI();
  const imagePart = await fileToGenerativePart(imageFile);
  const textPart = { text: "Describe the character in this image in detail for a character design sheet. Focus on visual traits like hair, eyes, clothing, style, and key features. The description will be used to generate new images of this character." };

  const response = await ai.models.generateContent({
    model: MODEL_NAMES.DESCRIPTION_GENERATION,
    contents: { parts: [imagePart, textPart] },
  });

  return response.text || '';
};

export const generateCharacterFromJson = async (jsonProfile: any): Promise<{ url: string; prompt: string }> => {
  const ai = getGenAI();

  const response = await ai.models.generateContent({
    model: MODEL_NAMES.ANALYSIS,
    contents: `Based on this Advanced JSON Context Profile, write a detailed physical description for a character design sheet. Focus on facial structure, expression, hair, specific clothing details, textures, logos, body proportions, and visual style. The goal is to generate a new character image that perfectly matches this profile. JSON: ${JSON.stringify(jsonProfile)}`,
  });

  const prompt = response.text || "A character based on structured visual metadata.";
  const url = await generateCharacterImage(prompt);

  return { url, prompt };
};

export const generateCharacterDirectly = async (imageFile: File): Promise<{ url: string; prompt: string; json?: any }> => {
  const description = await generateCharacterDescription(imageFile);

  let jsonProfile = null;
  try {
      jsonProfile = await generateJsonContextProfile(imageFile, "Quick extraction for character record.");
  } catch (e) {
      console.warn("Could not extract JSON profile during direct creation", e);
  }

  const url = await generateCharacterImage(description);
  return { url, prompt: description, json: jsonProfile };
};

export const refineCharacter = async (character: Character, updatedJson: any, changeInstructions: string): Promise<string> => {
    const ai = getGenAI();

    const matches = character.imageUrl.match(/^data:(.+);base64,(.+)$/);
    if (!matches) throw new Error("Invalid character image URL");

    const mimeType = matches[1];
    const base64Data = matches[2];

    const prompt = `Refine this character based on the following updates. 
    New Context Profile (JSON): ${JSON.stringify(updatedJson)}
    Specific Change Instructions: ${changeInstructions}
    Maintain the identity of the character while applying these modifications precisely. Result must be on a white background.`;

    const response = await ai.models.generateContent({
        model: MODEL_NAMES.IMAGE_EDITING,
        contents: {
            parts: [
                { inlineData: { data: base64Data, mimeType } },
                { text: prompt }
            ]
        },
        config: {
          responseModalities: [Modality.IMAGE],
        }
    });

    for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
            return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
    }
    throw new Error("Character refinement failed.");
};

export const generateJsonContextProfile = async (imageFile: File, userPrompt?: string): Promise<any> => {
    const ai = getGenAI();
    const imagePart = await fileToGenerativePart(imageFile);

    let baseInstruction = "Extract an expanded, detailed Advanced JSON Context Profile for this image. Include hierarchical data for: object detection, scene description, style, artistic characteristics, semantic/emotional interpretation, color, lighting, composition, and perceived technical metadata.";

    if (userPrompt) {
        baseInstruction += ` ADJUST YOUR ANALYSIS FOCUS BASED ON THIS USER REQUEST: "${userPrompt}"`;
    }

    const response = await ai.models.generateContent({
        model: MODEL_NAMES.ANALYSIS,
        contents: { parts: [imagePart, { text: baseInstruction }] },
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    metadata: {
                        type: Type.OBJECT,
                        properties: {
                            perceived_resolution: { type: Type.STRING },
                            quality_score: { type: Type.NUMBER },
                            analysis_timestamp: { type: Type.STRING }
                        },
                        required: ["perceived_resolution"]
                    },
                    objects: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                label: { type: Type.STRING },
                                description: { type: Type.STRING },
                                coordinates: { type: Type.STRING },
                                confidence: { type: Type.NUMBER }
                            },
                            required: ["label", "description"]
                        }
                    },
                    scene: {
                        type: Type.OBJECT,
                        properties: {
                            setting: { type: Type.STRING },
                            description: { type: Type.STRING },
                            atmosphere: { type: Type.STRING }
                        },
                        required: ["setting", "description"]
                    },
                    style: {
                        type: Type.OBJECT,
                        properties: {
                            medium: { type: Type.STRING },
                            artistic_era: { type: Type.STRING },
                            technique: { type: Type.STRING }
                        },
                        required: ["medium"]
                    },
                    semantics: {
                        type: Type.OBJECT,
                        properties: {
                            emotions: { type: Type.ARRAY, items: { type: Type.STRING } },
                            themes: { type: Type.ARRAY, items: { type: Type.STRING } },
                            symbolism: { type: Type.STRING }
                        }
                    },
                    visual_analysis: {
                        type: Type.OBJECT,
                        properties: {
                            color_palette: { type: Type.ARRAY, items: { type: Type.STRING } },
                            lighting: { type: Type.STRING },
                            composition: { type: Type.STRING }
                        }
                    },
                    custom_insights: {
                        type: Type.ARRAY,
                        items: { type: Type.STRING },
                        description: "Additional relevant structured insights based on the prompt or content."
                    }
                },
                required: ["metadata", "objects", "scene", "style"]
            },
        },
    });

    const jsonStr = response.text?.trim() || "{}";
    return JSON.parse(jsonStr);
};

export const generateScene = async (
  characters: Character[],
  prompt: string,
  rotations: Record<string, number>,
  onProgress: (msg: string) => void
): Promise<string> => {
  const ai = getGenAI();
  onProgress("Compositing characters into scene...");

  const parts: Part[] = [];
  for (const char of characters) {
    const matches = char.imageUrl.match(/^data:(.+);base64,(.+)$/);
    if (matches) {
       parts.push({
         inlineData: { data: matches[2], mimeType: matches[1] }
       });
    }
  }

  parts.push({ text: `Create a cinematic scene based on these characters. Use the following scene description: ${prompt}. Place characters naturally in the environment based on their design.` });

  const response = await ai.models.generateContent({
    model: MODEL_NAMES.IMAGE_EDITING,
    contents: { parts },
    config: {
      responseModalities: [Modality.IMAGE],
    }
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
  }
  throw new Error("Failed to generate scene.");
};

