export const generateVideo = async (
  imageFile: File, 
  prompt: string, 
  aspectRatio: AspectRatio,
  onProgress: (msg: string) => void
): Promise<string> => {
  const ai = getGenAI();
  const imageBase64 = await fileToBase64(imageFile);
  const data = imageBase64.split(',')[1];
  const mimeType = imageFile.type;

  onProgress("Starting video generation... (This may take a few minutes)");

  let operation = await ai.models.generateVideos({
    model: MODEL_NAMES.VIDEO_GENERATION,
    prompt: prompt,
    image: {
      imageBytes: data,
      mimeType: mimeType,
    },
    config: {
      numberOfVideos: 1,
      resolution: '720p',
      aspectRatio: aspectRatio
    }
  });

  onProgress("Video is being processed...");
  while (!operation.done) {
    await new Promise(resolve => setTimeout(resolve, 10000));
    operation = await ai.operations.getVideosOperation({ operation: operation });
    onProgress("Still processing... almost there...");
  }

  const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
  if (!downloadLink) throw new Error("Video generation failed.");

  const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
  const blob = await response.blob();
  return URL.createObjectURL(blob);
};

export const generateCharacterSpeech = async (text: string, voiceName: string): Promise<string> => {
  const ai = getGenAI();
  const response = await ai.models.generateContent({
    model: MODEL_NAMES.TTS,
    contents: [{ parts: [{ text }] }],
    config: {
      responseModalities: [Modality.AUDIO],
      speechConfig: {
        voiceConfig: {
          prebuiltVoiceConfig: { voiceName },
        },
      },
    },
  });

  const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64Audio) throw new Error("Failed to generate speech audio.");

  const uint8Array = base64ToUint8Array(base64Audio);
  const blob = createWavBlob(uint8Array);
  return URL.createObjectURL(blob);
};

export const generateImageFromInput = async (input: string, onProgress: (msg: string) => void): Promise<string> => {
    const ai = getGenAI();
    onProgress("Generating image...");

    let prompt = input;
    let aspectRatio: any = "1:1";
    try {
        const json = JSON.parse(input);
        if (json.prompt) prompt = json.prompt;
        if (json.aspectRatio) aspectRatio = json.aspectRatio;
    } catch (e) {
    }

    // Using Imagen for text-to-image generation as it's optimized for high quality from text
    const response = await ai.models.generateImages({
      model: MODEL_NAMES.IMAGE_GENERATION,
      prompt,
      config: {
        numberOfImages: 1,
        aspectRatio,
        outputMimeType: 'image/jpeg',
      },
    });

    if (response.generatedImages && response.generatedImages.length > 0) {
      const base64ImageBytes = response.generatedImages[0].image.imageBytes;
      return `data:image/jpeg;base64,${base64ImageBytes}`;
    }
    throw new Error("Failed to generate image.");
};

export const animateImage = async (
    imageFile: File,
    input: string,
    aspectRatio: AspectRatio,
    onProgress: (msg: string) => void
): Promise<string> => {
    return generateVideo(imageFile, input, aspectRatio, onProgress);
};

