const ImageEditor: React.FC<Pick<ControlsPanelProps, 'setLoading' | 'setError' | 'onGenerationComplete'>> = ({ setLoading, setError, onGenerationComplete }) => {
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [previewUrl, setPreviewUrl] = useState<string>('');
  const [prompt, setPrompt] = useState('');
  const [lastResultUrl, setLastResultUrl] = useState<string | null>(null);
  const [exportFormat, setExportFormat] = useState<'png' | 'jpeg'>('png');
  const [exportQuality, setExportQuality] = useState<'low' | 'medium' | 'high'>('high');

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setImageFile(file);
      setPreviewUrl(URL.createObjectURL(file));
      setLastResultUrl(null);
    }
  };

  const handleGenerate = async (stylePrompt?: string) => {
    if (!imageFile) return;
    const finalPrompt = stylePrompt || prompt;
    if (!finalPrompt) return;

    setLoading(true, stylePrompt ? "Applying style transformation..." : "Editing image...");
    setError(null);
    try {
      const resultUrl = await editImage(imageFile, finalPrompt);
      setLastResultUrl(resultUrl);
      onGenerationComplete({ type: 'image', url: resultUrl });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to edit image.");
    } finally {
      setLoading(false, "");
    }
  };

  const handleDownload = async () => {
      if (!lastResultUrl) return;

      const img = new Image();
      img.src = lastResultUrl;
      await new Promise(r => img.onload = r);

      const canvas = document.createElement('canvas');
      canvas.width = img.naturalWidth;
      canvas.height = img.naturalHeight;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      if (exportFormat === 'jpeg') {
          ctx.fillStyle = 'white';
          ctx.fillRect(0, 0, canvas.width, canvas.height);
      }
      ctx.drawImage(img, 0, 0);

      let quality = 1.0;
      if (exportQuality === 'low') quality = 0.5;
      if (exportQuality === 'medium') quality = 0.8;

      const dataUrl = canvas.toDataURL(`image/${exportFormat}`, quality);
      const a = document.createElement('a');
      a.href = dataUrl;
      a.download = `transformed-studio-${Date.now()}.${exportFormat}`;
      a.click();
  };

  return (
    <div className="flex flex-col h-full space-y-4">
      <h2 className="text-xl font-bold text-white flex items-center gap-2">
          <EditMagicIcon className="w-6 h-6" /> Image Editor
      </h2>

      <div className="flex-grow space-y-4 overflow-y-auto pr-2 custom-scrollbar">
        <div className="border-2 border-dashed border-gray-600 rounded-lg p-4 text-center hover:border-indigo-500 transition-colors cursor-pointer relative h-32 flex items-center justify-center bg-gray-800/30">
          <input
            type="file"
            accept="image/*"
            onChange={handleFileChange}
            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
          />
          {previewUrl ? (
            <img src={previewUrl} alt="Preview" className="max-h-full max-w-full object-contain rounded" />
          ) : (
             <div className="flex flex-col items-center">
                <UploadIcon className="w-6 h-6 text-gray-400 mb-1" />
                <p className="text-gray-400 text-xs">Upload Image</p>
             </div>
          )}
        </div>

        {/* Style Transformation Section */}
        <div className="space-y-2">
            <h3 className="text-xs font-bold uppercase text-gray-500 flex items-center gap-2">
                <SparklesIcon className="w-3 h-3" /> Style Transformation
            </h3>
            <div className="grid grid-cols-2 gap-2">
                {STYLE_PRESETS.map((style) => (
                    <button
                        key={style.id}
                        onClick={() => handleGenerate(style.prompt)}
                        disabled={!imageFile}
                        className="p-2 bg-gray-800 border border-gray-700 rounded text-[10px] text-left hover:bg-indigo-600 hover:border-indigo-500 transition-all disabled:opacity-50 disabled:cursor-not-allowed group"
                    >
                        <span className="text-indigo-400 group-hover:text-white font-bold block mb-1">{style.label.split(' ')[0]}</span>
                        <span className="text-gray-400 group-hover:text-white leading-tight line-clamp-2">{style.label}</span>
                    </button>
                ))}
            </div>
        </div>

        <div className="border-t border-gray-700 pt-3">
          <label className="block text-xs font-medium text-gray-400 mb-1">Manual Instructions</label>
          <textarea
            className="w-full h-20 p-2 bg-gray-900 border border-gray-700 rounded focus:ring-1 focus:ring-indigo-500 text-xs text-white placeholder-gray-600 resize-none"
            placeholder="e.g. Change the background..."
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
          />
          <Button onClick={() => handleGenerate()} disabled={!imageFile || !prompt} className="w-full mt-2 text-xs py-1.5">
            Apply Manual Edit
          </Button>
        </div>

        {/* Export Section */}
        {lastResultUrl && (
            <div className="bg-gray-800/80 p-3 rounded-lg border border-indigo-500/30 space-y-3 animate-in fade-in slide-in-from-bottom-2">
                <h3 className="text-xs font-bold uppercase text-indigo-400 flex items-center gap-2">
                    <DownloadIcon className="w-3 h-3" /> Export Options
                </h3>

                <div>
                    <p className="text-[10px] text-gray-500 mb-1">Format</p>
                    <div className="flex gap-2">
                        {(['png', 'jpeg'] as const).map(f => (
                            <button
                                key={f}
                                onClick={() => setExportFormat(f)}
                                className={`flex-1 py-1 rounded text-[10px] border ${exportFormat === f ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-gray-900 border-gray-700 text-gray-400'}`}
                            >
                                {f.toUpperCase()}
                            </button>
                        ))}
                    </div>
                </div>

                <div>
                    <p className="text-[10px] text-gray-500 mb-1">Quality</p>
                    <div className="flex gap-1">
                        {(['low', 'medium', 'high'] as const).map(q => (
                            <button
                                key={q}
                                onClick={() => setExportQuality(q)}
                                className={`flex-1 py-1 rounded text-[10px] border ${exportQuality === q ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-gray-900 border-gray-700 text-gray-400'}`}
                            >
                                {q.charAt(0).toUpperCase() + q.slice(1)}
                            </button>
                        ))}
                    </div>
                </div>

                <Button onClick={handleDownload} className="w-full bg-emerald-600 hover:bg-emerald-500 text-xs py-2">
                    <DownloadIcon className="w-4 h-4" /> Download Result
                </Button>
            </div>
        )}
      </div>
    </div>
  );
};

