const ImageEditor: React.FC<Pick<ControlsPanelProps, 'setLoading' | 'setError' | 'onGenerationComplete' | 'editorState' | 'setEditorState'>> = ({ setLoading, setError, onGenerationComplete, editorState, setEditorState }) => {
  const [prompt, setPrompt] = useState('');
  const [exportFormat, setExportFormat] = useState<string>(STYLE_ENGINE.defaultOutput.formats[0]);
  const [exportQualityId, setExportQualityId] = useState<string>(STYLE_ENGINE.defaultOutput.qualityLevels[2].id);

  const mapParametersToPrompt = useCallback((params: any): string => {
    let styleBlock = '';
    if (params.contrast > 1.3) styleBlock += 'extremely high contrast and dramatic tonal range, ';
    else if (params.contrast > 1.1) styleBlock += 'high contrast, ';
    if (params.saturation > 1.3) styleBlock += 'vibrant highly saturated colors, ';
    else if (params.saturation < 1.0) styleBlock += 'muted desaturated color palette, ';
    if (params.monochrome) styleBlock += 'monochromatic black and white aesthetic, ';
    if (params.grain > 0.3) styleBlock += 'rough heavy film grain texture, ';
    else if (params.grain > 0) styleBlock += 'fine film grain, ';
    if (params.glitchEffect > 0) styleBlock += `digital glitch artifacts, RGB separation intensity ${params.glitchEffect}, `;
    if (params.chromaticAberration) styleBlock += 'noticeable chromatic aberration, ';
    if (params.bloom > 0) styleBlock += 'ethereal bloom and volumetric glow, ';
    if (params.microTexture > 1.0) styleBlock += 'enhanced micro-surface textures and ultra-sharp details, ';
    if (params.lightingMood) styleBlock += `${params.lightingMood}, `;
    if (params.shutterEffect) styleBlock += `${params.shutterEffect}, `;
    if (params.colorGrade) styleBlock += `cinematic ${params.colorGrade} color grade, `;
    if (params.focusMode) styleBlock += `${params.focusMode}, `;
    if (params.description) styleBlock += `${params.description}, `;

    const basePrompt = "Use the uploaded image as the immutable base. Preserve original proportions, anatomy, clothing, and composition perfectly.";
    const safetyBlock = "STRICT: Do not distort faces or bodies. No unintended style mixing. Maintain identical object placement.";
    if (params.skinToneProtection) styleBlock += "ensure natural and realistic skin tones are preserved, ";
    return `${basePrompt} ${styleBlock.trim()} ${safetyBlock}`;
  }, []);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const base64 = await fileToBase64(file);
      // Step 1: Upload - Preserve original as immutable, create working copy
      setEditorState({
        originalImage: base64,
        workingImage: base64,
        selectedStyleId: null,
        lastGenerationId: crypto.randomUUID(),
      });
      setError(null);
    }
  };

  const handleGenerate = async (style?: { id: string, parameters: any }) => {
    if (!editorState.originalImage) return;

    // Step 2: Style Selection or Manual Processing
    const finalPrompt = style ? mapParametersToPrompt(style.parameters) : prompt;
    if (!finalPrompt) return;

    setLoading(true, style ? "Applying style transformation..." : "Editing image...");
    setError(null);

    try {
      // Create a File-like object from base64 to send to service
      const response = await fetch(editorState.originalImage);
      const blob = await response.blob();
      const file = new File([blob], "original.png", { type: "image/png" });

      const resultUrl = await editImage(file, finalPrompt);

      // Reactive Update: Explicit render trigger
      setEditorState(prev => ({
        ...prev,
        workingImage: resultUrl,
        selectedStyleId: style?.id || null,
        lastGenerationId: crypto.randomUUID(), // Force Canvas re-render
      }));

      onGenerationComplete({ type: 'image', url: resultUrl });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to edit image.");
    } finally {
      setLoading(false, "");
    }
  };

  const handleDownload = async () => {
      if (!editorState.workingImage) return;
      const qualitySetting = STYLE_ENGINE.defaultOutput.qualityLevels.find(q => q.id === exportQualityId);
      if (!qualitySetting) return;
      const img = new Image();
      img.src = editorState.workingImage;
      await new Promise(r => img.onload = r);
      const canvas = document.createElement('canvas');
      canvas.width = img.naturalWidth;
      canvas.height = img.naturalHeight;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      if (exportFormat === 'JPG') { ctx.fillStyle = 'white'; ctx.fillRect(0, 0, canvas.width, canvas.height); }
      ctx.drawImage(img, 0, 0);
      const mimeType = exportFormat === 'JPG' ? 'image/jpeg' : 'image/png';
      const quality = exportFormat === 'JPG' ? qualitySetting.jpgQuality : qualitySetting.pngCompression;
      const dataUrl = canvas.toDataURL(mimeType, quality);
      const a = document.createElement('a');
      a.href = dataUrl;
      a.download = `style-engine-${exportQualityId}-${Date.now()}.${exportFormat.toLowerCase()}`;
      a.click();
  };

  return (
    <div className="flex flex-col h-full space-y-4">
      <h2 className="text-xl font-bold text-white flex items-center gap-2"><EditMagicIcon className="w-6 h-6" /> Image Editor</h2>
      <div className="flex-grow space-y-4 overflow-y-auto pr-2 custom-scrollbar">
        <div className="border-2 border-dashed border-gray-600 rounded-lg p-4 text-center hover:border-indigo-500 transition-colors cursor-pointer relative h-32 flex items-center justify-center bg-gray-800/30">
          <input type="file" accept="image/*" onChange={handleFileChange} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" />
          {editorState.originalImage ? (
            <img src={editorState.originalImage} alt="Base Layer" className="max-h-full max-w-full object-contain rounded opacity-50 grayscale" />
          ) : (
             <div className="flex flex-col items-center"><UploadIcon className="w-6 h-6 text-gray-400 mb-1" /><p className="text-gray-400 text-xs">Upload Original Image</p></div>
          )}
          {editorState.originalImage && <div className="absolute inset-0 flex items-center justify-center font-bold text-[10px] uppercase text-indigo-400 pointer-events-none">Immutable Base</div>}
        </div>

        <div className="space-y-2">
            <h3 className="text-xs font-bold uppercase text-gray-500 flex items-center gap-2"><SparklesIcon className="w-3 h-3" /> Style Transformation</h3>
            <div className="grid grid-cols-2 gap-2">
                {STYLE_ENGINE.styles.map((style) => (
                    <button
                        key={style.id}
                        onClick={() => handleGenerate(style)}
                        disabled={!editorState.originalImage}
                        className={`p-2 bg-gray-800 border rounded text-[10px] text-left transition-all disabled:opacity-50 disabled:cursor-not-allowed group ${editorState.selectedStyleId === style.id ? 'border-indigo-500 bg-indigo-900/30' : 'border-gray-700 hover:bg-indigo-600 hover:border-indigo-500'}`}
                    >
                        <span className={`font-bold block mb-1 ${editorState.selectedStyleId === style.id ? 'text-white' : 'text-indigo-400 group-hover:text-white'}`}>{style.label.split(' ')[0]}</span>
                        <span className={`leading-tight line-clamp-2 ${editorState.selectedStyleId === style.id ? 'text-white/80' : 'text-gray-400 group-hover:text-white'}`}>{style.label}</span>
                    </button>
                ))}
            </div>
        </div>

        <div className="border-t border-gray-700 pt-3">
          <label className="block text-xs font-medium text-gray-400 mb-1">Manual Processing Override</label>
          <textarea className="w-full h-20 p-2 bg-gray-900 border border-gray-700 rounded focus:ring-1 focus:ring-indigo-500 text-xs text-white placeholder-gray-600 resize-none" placeholder="e.g. Change specific elements..." value={prompt} onChange={(e) => setPrompt(e.target.value)} />
          <Button onClick={() => handleGenerate()} disabled={!editorState.originalImage || !prompt} className="w-full mt-2 text-xs py-1.5">Apply Manual Processing</Button>
        </div>

        {editorState.workingImage && (
            <div className="bg-gray-800/80 p-3 rounded-lg border border-indigo-500/30 space-y-3 animate-in fade-in slide-in-from-bottom-2">
                <h3 className="text-xs font-bold uppercase text-indigo-400 flex items-center gap-2"><DownloadIcon className="w-3 h-3" /> Export Workflow</h3>
                <div>
                    <p className="text-[10px] text-gray-500 mb-1">Select Format</p>
                    <div className="flex gap-2">
                        {STYLE_ENGINE.defaultOutput.formats.map(f => (
                            <button key={f} onClick={() => setExportFormat(f)} className={`flex-1 py-1 rounded text-[10px] border ${exportFormat === f ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-gray-900 border-gray-700 text-gray-400'}`}>{f}</button>
                        ))}
                    </div>
                </div>
                <div>
                    <p className="text-[10px] text-gray-500 mb-1">Select Quality</p>
                    <div className="flex flex-col gap-1">
                        {STYLE_ENGINE.defaultOutput.qualityLevels.map(q => (
                            <button key={q.id} onClick={() => setExportQualityId(q.id)} className={`w-full py-1.5 px-3 rounded text-left flex justify-between items-center text-[10px] border transition-colors ${exportQualityId === q.id ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-gray-900 border-gray-700 text-gray-400'}`}>
                                <span className="font-bold">{q.label}</span><span className="opacity-60 italic">{q.description}</span>
                            </button>
                        ))}
                    </div>
                </div>
                <Button onClick={handleDownload} className="w-full bg-emerald-600 hover:bg-emerald-500 text-xs py-2 shadow-lg shadow-emerald-500/10"><DownloadIcon className="w-4 h-4" /> Download Result</Button>
            </div>
        )}
      </div>
    </div>
  );
};

