      {activeTool === 'CHARACTER_EDITOR' && <CharacterEditorPanel characters={rest.characters} selectedCharacters={rest.selectedCharacters} setLoading={rest.setLoading} setError={rest.setError} onGenerationComplete={rest.onGenerationComplete} onSaveCharacter={rest.onSaveCharacter} onUpdateCharacter={rest.onUpdateCharacter} />}
      {activeTool === 'IMAGE_GENERATOR' && <ImageGeneratorPanel setLoading={rest.setLoading} setError={rest.setError} onGenerationComplete={rest.onGenerationComplete} />}
      {activeTool === 'ANIMATE_PICTURE' && <AnimatePicturePanel setLoading={rest.setLoading} setError={rest.setError} onGenerationComplete={rest.onGenerationComplete} />}
      {activeTool === 'IMAGE_EDITOR' && <ImageEditor setLoading={rest.setLoading} setError={rest.setError} onGenerationComplete={rest.onGenerationComplete} editorState={rest.editorState} setEditorState={rest.setEditorState} />}
      {activeTool === 'VIDEO_GENERATOR' && <VideoGenerator setLoading={rest.setLoading} setError={rest.setError} onGenerationComplete={rest.onGenerationComplete} />}
      {activeTool === 'CHARACTER_VOICE' && <CharacterVoicePanel selectedCharacters={rest.selectedCharacters} setLoading={rest.setLoading} setError={rest.setError} onGenerationComplete={rest.onGenerationComplete} />}
    </aside>
  );
};

