import { GoogleGenAI, Modality, Part, Type } from "@google/genai";
import { MODEL_NAMES, CHARACTER_STYLES } from '../constants';
import { fileToGenerativePart, fileToBase64 } from '../utils/fileUtils';
import { base64ToUint8Array, createWavBlob } from '../utils/audioUtils';
import { AspectRatio, Character } from '../types';

const getGenAI = () => {
  if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
}

export interface CharacterGenerationResult {
  image: string; // base64 data URL
  appliedStyle: string;
  metadata: {
    styleDescription: string;
    generationNotes: string;
  };
}

export const generateRandomName = async (style?: string): Promise<string> => {
  const ai = getGenAI();
  const prompt = `Generate a single, cool, and fitting name for a character with this style: ${style || 'general'}. Return ONLY the name, no extra text.`;

  const response = await ai.models.generateContent({
    model: MODEL_NAMES.ANALYSIS,
    contents: prompt,
  });

  return response.text?.trim() || "Unnamed Character";
};

export const generateCharacterWithStyle = async (
  characterName: string,
  characterDescription: string,
  characterStyle?: string
): Promise<CharacterGenerationResult> => {
  const ai = getGenAI();

  // Find style definition
  const styleObj = CHARACTER_STYLES.find(s => s.name === characterStyle);
  const appliedStyle = styleObj ? styleObj.name : 'Default';
  const styleDescription = styleObj ? styleObj.description : 'Standard studio character design aesthetic.';

  const generationNotes = characterStyle && !styleObj 
    ? `Warning: Invalid style '${characterStyle}' provided. Falling back to default style.` 
    : characterStyle 
      ? `Applying '${appliedStyle}' style strictly to character design.` 
      : "Using default studio style.";

  const stylePrompt = styleObj 
    ? `Style: ${appliedStyle}. Definition: ${styleDescription}. Follow this style strictly for colors, textures, line quality, and atmosphere.` 
    : "Style: High quality modern character design sheet aesthetic, isolated on white.";

  const fullPrompt = `Character Name: ${characterName}. 
Description: ${characterDescription}.
${stylePrompt}
The character should be isolated on a plain white background, full body shot, maintain anatomical consistency with the selected style.`;

  const response = await ai.models.generateContent({
    model: MODEL_NAMES.IMAGE_EDITING,
    contents: { parts: [{ text: fullPrompt }] },
    config: {
      imageConfig: { aspectRatio: "1:1" },
      responseModalities: [Modality.IMAGE],
    }
  });

  let generatedImage = '';
  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      generatedImage = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      break;
    }
  }

  if (!generatedImage) throw new Error("Failed to generate character image.");

  return {
    image: generatedImage,
    appliedStyle,
    metadata: {
      styleDescription,
      generationNotes
    }
  };
};

