import { GoogleGenAI, Modality, Part, Type } from "@google/genai";
import { MODEL_NAMES, CHARACTER_STYLES } from '../constants';
import { fileToGenerativePart, fileToBase64 } from '../utils/fileUtils';
import { base64ToUint8Array, createWavBlob } from '../utils/audioUtils';
import { AspectRatio, Character } from '../types';

const getGenAI = () => {
  if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
}

/**
 * Core AI Image Transformation Pipeline
 * Ensures stylistic changes without altering geometry or content.
 */
export const transformImageWithAI = async (
  imageFile: File,
  userPrompt: string,
  jsonContext?: string
): Promise<string> => {
  const ai = getGenAI();
  const imagePart = await fileToGenerativePart(imageFile);

  // Constructing a prompt that enforces non-destructive editing
  const systemConstraints = `
    TASK: Visual Style Transformation.
    STRICT RULES:
    1. DO NOT add new objects or people.
    2. DO NOT remove existing objects or people.
    3. PRESERVE original geometry, perspective, and proportions perfectly.
    4. ONLY modify colors, lighting, textures, and rendering style.
  `;

  const contextInstruction = jsonContext 
    ? `PRIMARY STYLE SOURCE (JSON Profile): ${jsonContext}. Use this for color palette, lighting, and texture guidance.`
    : "";

  const finalPrompt = `
    ${systemConstraints}
    ${contextInstruction}
    USER STYLE INSTRUCTION: ${userPrompt}
    Render the result with high professional fidelity.
  `;

  const response = await ai.models.generateContent({
    model: MODEL_NAMES.IMAGE_EDITING,
    contents: { parts: [imagePart, { text: finalPrompt }] },
    config: {
      responseModalities: [Modality.IMAGE],
    }
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
  }
  throw new Error("AI Transformation failed to return an image.");
};

/**
 * Dedicated Snow Landscape Preset
 * Converts scene to winter without changing structure or adding particles.
 */
export const applySnowLandscapePreset = async (imageFile: File): Promise<string> => {
  const ai = getGenAI();
  const imagePart = await fileToGenerativePart(imageFile);

  const snowPrompt = `
    TASK: Transform this scene into a realistic snow landscape.
    CONSTRAINTS:
    - PRESERVE original composition, geometry, and perspective.
    - APPLY settled snow to all roofs, ground, ledges, and horizontal surfaces.
    - MAINTAIN realistic material response and shadows.
    - NO falling snow particles. NO fog. NO blur.
    - Atmospheric lighting: Cold, crisp winter daylight.
    Result must look like a high-quality photograph taken after heavy snowfall has settled.
  `;

  const response = await ai.models.generateContent({
    model: MODEL_NAMES.IMAGE_EDITING,
    contents: { parts: [imagePart, { text: snowPrompt }] },
    config: {
      responseModalities: [Modality.IMAGE],
    }
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
  }
  throw new Error("Snow preset transformation failed.");
};

export const generateRandomName = async (style?: string): Promise<string> => {
  const ai = getGenAI();
  const prompt = `Generate a single, cool, and fitting name for a character with this style: ${style || 'general'}. Return ONLY the name, no extra text.`;
  const response = await ai.models.generateContent({
    model: MODEL_NAMES.ANALYSIS,
    contents: prompt,
  });
  return response.text?.trim() || "Unnamed Character";
};

export const generateCharacterWithStyle = async (
  characterName: string,
  characterDescription: string,
  characterStyle?: string
): Promise<any> => {
  const ai = getGenAI();
  const styleObj = CHARACTER_STYLES.find(s => s.name === characterStyle);
  const appliedStyle = styleObj ? styleObj.name : 'Default';
  const styleDescription = styleObj ? styleObj.description : 'Standard studio character design aesthetic.';

  const stylePrompt = styleObj 
    ? `Style: ${appliedStyle}. Definition: ${styleDescription}. Follow this style strictly.` 
    : "Style: High quality modern character design sheet aesthetic, isolated on white.";

  const fullPrompt = `Character Name: ${characterName}. Description: ${characterDescription}. ${stylePrompt} Isolated on white background, full body shot.`;

  const response = await ai.models.generateContent({
    model: MODEL_NAMES.IMAGE_EDITING,
    contents: { parts: [{ text: fullPrompt }] },
    config: {
      imageConfig: { aspectRatio: "1:1" },
      responseModalities: [Modality.IMAGE],
    }
  });

  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) {
      return {
        image: `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`,
        appliedStyle,
        metadata: { styleDescription, generationNotes: "Style applied via instruction block." }
      };
    }
  }
  throw new Error("Failed to generate character image.");
};

export const generateCharacterDescription = async (imageFile: File): Promise<string> => {
  const ai = getGenAI();
  const imagePart = await fileToGenerativePart(imageFile);
  const response = await ai.models.generateContent({
    model: MODEL_NAMES.DESCRIPTION_GENERATION,
    contents: { parts: [imagePart, { text: "Describe the character in this image in detail." }] },
  });
  return response.text || '';
};

export const generateCharacterFromJson = async (jsonProfile: any): Promise<{ url: string; prompt: string }> => {
  const ai = getGenAI();
  const response = await ai.models.generateContent({
    model: MODEL_NAMES.ANALYSIS,
    contents: `Write a detailed physical description based on this JSON profile: ${JSON.stringify(jsonProfile)}`,
  });
  const prompt = response.text || "A character based on metadata.";
  const result = await generateCharacterWithStyle("New Character", prompt);
  return { url: result.image, prompt };
};

export const generateCharacterDirectly = async (imageFile: File): Promise<{ url: string; prompt: string; json?: any }> => {
  const description = await generateCharacterDescription(imageFile);
  const jsonProfile = await generateJsonContextProfile(imageFile);
  const result = await generateCharacterWithStyle("Direct Character", description);
  return { url: result.image, prompt: description, json: jsonProfile };
};

export const refineCharacter = async (character: Character, updatedJson: any, changeInstructions: string): Promise<string> => {
    const ai = getGenAI();
    const matches = character.imageUrl.match(/^data:(.+);base64,(.+)$/);
    if (!matches) throw new Error("Invalid character image URL");
    const prompt = `Refine character: ${changeInstructions}. Context: ${JSON.stringify(updatedJson)}. Preserve identity, white background.`;
    const response = await ai.models.generateContent({
        model: MODEL_NAMES.IMAGE_EDITING,
        contents: { parts: [{ inlineData: { data: matches[2], mimeType: matches[1] } }, { text: prompt }] },
        config: { responseModalities: [Modality.IMAGE] }
    });
    for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
    throw new Error("Refinement failed.");
};

export const generateJsonContextProfile = async (imageFile: File, userPrompt?: string): Promise<any> => {
    const ai = getGenAI();
    const imagePart = await fileToGenerativePart(imageFile);
    const response = await ai.models.generateContent({
        model: MODEL_NAMES.ANALYSIS,
        contents: { parts: [imagePart, { text: "Extract Advanced JSON Context Profile." }] },
        config: {
            responseMimeType: "application/json",
            responseSchema: {
                type: Type.OBJECT,
                properties: {
                    metadata: { type: Type.OBJECT, properties: { resolution: { type: Type.STRING } } },
                    objects: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { label: { type: Type.STRING } } } },
                    scene: { type: Type.OBJECT, properties: { setting: { type: Type.STRING } } },
                    style: { type: Type.OBJECT, properties: { medium: { type: Type.STRING } } }
                }
            },
        },
    });
    return JSON.parse(response.text || "{}");
};

export const generateScene = async (characters: Character[], prompt: string, rotations: Record<string, number>, onProgress: (msg: string) => void): Promise<string> => {
  const ai = getGenAI();
  const parts: Part[] = characters.map(c => {
    const m = c.imageUrl.match(/^data:(.+);base64,(.+)$/);
    return m ? { inlineData: { data: m[2], mimeType: m[1] } } : null;
  }).filter((p): p is Part => p !== null);
  parts.push({ text: `Cinematic scene: ${prompt}` });
  const response = await ai.models.generateContent({ model: MODEL_NAMES.IMAGE_EDITING, contents: { parts }, config: { responseModalities: [Modality.IMAGE] } });
  for (const part of response.candidates[0].content.parts) {
    if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
  }
  throw new Error("Scene failed.");
};

export const generateVideo = async (imageFile: File, prompt: string, aspectRatio: AspectRatio, onProgress: (msg: string) => void): Promise<string> => {
  const ai = getGenAI();
  const base64 = await fileToBase64(imageFile);
  const data = base64.split(',')[1];
  let operation = await ai.models.generateVideos({ model: MODEL_NAMES.VIDEO_GENERATION, prompt, image: { imageBytes: data, mimeType: imageFile.type }, config: { numberOfVideos: 1, resolution: '720p', aspectRatio } });
  while (!operation.done) {
    await new Promise(r => setTimeout(r, 10000));
    operation = await ai.operations.getVideosOperation({ operation });
  }
  const link = operation.response?.generatedVideos?.[0]?.video?.uri;
  const res = await fetch(`${link}&key=${process.env.API_KEY}`);
  return URL.createObjectURL(await res.blob());
};

export const generateCharacterSpeech = async (text: string, voiceName: string): Promise<string> => {
  const ai = getGenAI();
  const response = await ai.models.generateContent({ model: MODEL_NAMES.TTS, contents: [{ parts: [{ text }] }], config: { responseModalities: [Modality.AUDIO], speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName } } } } });
  const base64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64) throw new Error("Audio failed.");
  return URL.createObjectURL(createWavBlob(base64ToUint8Array(base64)));
};

export const generateImageFromInput = async (input: string, onProgress: (msg: string) => void): Promise<string> => {
    const ai = getGenAI();
    const response = await ai.models.generateImages({ model: MODEL_NAMES.IMAGE_GENERATION, prompt: input, config: { numberOfImages: 1, aspectRatio: "1:1", outputMimeType: 'image/jpeg' } });
    if (response.generatedImages?.[0]) return `data:image/jpeg;base64,${response.generatedImages[0].image.imageBytes}`;
    throw new Error("Image failed.");
};

export const animateImage = async (imageFile: File, input: string, aspectRatio: AspectRatio, onProgress: (msg: string) => void): Promise<string> => {
    return generateVideo(imageFile, input, aspectRatio, onProgress);
};

import React, { useState, useCallback, useEffect } from 'react';
import { AspectRatio, Character, ToolType, SoundEffect, Scene, EditorState } from '../types';
import { Button } from './common/Button';
import { 
  generateScene, 
  generateVideo, 
  generateCharacterSpeech, 
  generateImageFromInput, 
  animateImage, 
  generateJsonContextProfile, 
  generateCharacterFromJson, 
  generateCharacterDirectly, 
  refineCharacter, 
  generateRandomName,
  transformImageWithAI,
  applySnowLandscapePreset
} from '../services/geminiService';
import { ApiKeySelector } from './ApiKeySelector';
import { 
  SaveIcon, 
  VOICE_NAMES, 
  UploadIcon, 
  MusicIcon, 
  TrashIcon, 
  FilePlusIcon, 
  ExportIcon, 
  PhotoIcon, 
  SparklesIcon, 
  CodeBracketIcon, 
  AddUserIcon, 
  SparklesIcon as EditMagicIcon, 
  STYLE_ENGINE, 
  DownloadIcon 
} from '../constants';
import { fileToBase64 } from '../utils/fileUtils';

interface ControlsPanelProps {
  activeTool: ToolType;
  selectedCharacters: Character[];
  characters: Character[];
  setLoading: (isLoading: boolean, message: string) => void;
  setError: (error: string | null) => void;
  onGenerationComplete: (content: { type: 'image' | 'video' | 'audio' | 'json'; url: string; data?: any; characterId?: string; soundEffectUrl?: string }) => void;
  onSaveCharacter: (character: Character) => void;
  onUpdateCharacter: (character: Character) => void;

  // Editor State Props
  editorState: EditorState;
  setEditorState: React.Dispatch<React.SetStateAction<EditorState>>;

  // Scene Builder Props
  scenePrompt: string;
  setScenePrompt: (prompt: string) => void;
  onSaveScene: (name: string) => void;
  currentSceneName?: string;
  sceneSoundEffect: SoundEffect | undefined;
  setSceneSoundEffect: (sound: SoundEffect | undefined) => void;
  soundLibrary: SoundEffect[];
  setSoundLibrary: (library: SoundEffect[]) => void;
  characterRotations: Record<string, number>;
  onResetScene: () => void;
  scenes: Scene[];
  onLoadScene: (scene: Scene) => void;
  onExportScene: () => void;
}

const SceneBuilder: React.FC<Omit<ControlsPanelProps, 'activeTool'>> = ({ 
  selectedCharacters, 
  setLoading, 
  setError, 
  onGenerationComplete,
  scenePrompt,
  setScenePrompt,
  onSaveScene,
  currentSceneName,
  sceneSoundEffect,
  setSceneSoundEffect,
  soundLibrary,
  setSoundLibrary,
  characterRotations,
  onResetScene,
  scenes,
  onLoadScene,
  onExportScene
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const [sceneName, setSceneName] = useState('');
  const [soundTab, setSoundTab] = useState<'SELECT' | 'UPLOAD'>('SELECT');
  const [sceneToLoad, setSceneToLoad] = useState('');

  const handleGenerate = useCallback(async () => {
    if (selectedCharacters.length === 0) {
      setError("Please select at least one character from the library.");
      return;
    }
    setLoading(true, "Building your scene...");
    setError(null);
    try {
      const imageUrl = await generateScene(
          selectedCharacters, 
          scenePrompt, 
          characterRotations, 
          (msg) => setLoading(true, msg)
      );
      onGenerationComplete({ 
        type: 'image', 
        url: imageUrl, 
        soundEffectUrl: sceneSoundEffect?.url 
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to generate scene.");
    } finally {
      setLoading(false, "");
    }
  }, [selectedCharacters, scenePrompt, setLoading, setError, onGenerationComplete, sceneSoundEffect, characterRotations]);

  const initiateSave = () => {
    if (selectedCharacters.length === 0) {
        setError("Add characters to save a scene.");
        return;
    }
    setError(null);
    setSceneName(currentSceneName || '');
    setIsSaving(true);
  }

  const confirmSave = () => {
      if (sceneName.trim()) {
          onSaveScene(sceneName);
          setIsSaving(false);
      }
  };

  const handleSoundUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          try {
              const base64 = await fileToBase64(file);
              const newSound: SoundEffect = {
                  id: crypto.randomUUID(),
                  name: file.name.replace(/\.[^/.]+$/, ""),
                  url: base64
              };
              setSoundLibrary([...soundLibrary, newSound]);
              setSceneSoundEffect(newSound);
          } catch (err) {
              console.error("Audio upload failed", err);
              setError("Failed to upload audio.");
          }
      }
  };

  const handleLoadSelect = (e: React.ChangeEvent<HTMLSelectElement>) => {
      const sceneId = e.target.value;
      setSceneToLoad(sceneId);
      const scene = scenes.find(s => s.id === sceneId);
      if (scene) {
          onLoadScene(scene);
      }
  };

  return (
    <div className="flex flex-col h-full">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-xl font-bold text-white">Scene Builder</h2>
        <div className="flex gap-2">
           <Button onClick={onResetScene} variant="secondary" className="px-2" title="New Scene">
              <FilePlusIcon className="w-4 h-4" />
           </Button>
           <div className="relative">
              <select 
                value={sceneToLoad} 
                onChange={handleLoadSelect}
                className="bg-gray-700 text-white text-xs rounded px-2 py-2 border border-gray-600 focus:outline-none focus:border-indigo-500 max-w-[100px]"
              >
                  <option value="" disabled>Load...</option>
                  {scenes.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
              </select>
