        <div><label className="block text-sm font-medium text-gray-300 mb-2">Motion Prompt</label><textarea className="w-full h-32 p-3 bg-gray-800 border border-gray-700 rounded-md focus:ring-2 focus:ring-indigo-500 text-white placeholder-gray-500 resize-none font-mono text-xs" placeholder={'Describe movement...'} value={input} onChange={(e) => setInput(e.target.value)} /></div>
        <div><label className="block text-sm font-medium text-gray-300 mb-2">Aspect Ratio</label><div className="flex gap-4"><button onClick={() => setAspectRatio('16:9')} className={`flex-1 py-2 px-2 text-xs rounded-md border ${aspectRatio === '16:9' ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-gray-800 border-gray-600 text-gray-300 hover:bg-gray-700'}`}>16:9</button><button onClick={() => setAspectRatio('9:16')} className={`flex-1 py-2 px-2 text-xs rounded-md border ${aspectRatio === '9:16' ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-gray-800 border-gray-600 text-gray-300 hover:bg-gray-700'}`}>9:16</button></div></div>
      </div>
      <Button onClick={handleGenerate} disabled={!imageFile || !input} className="w-full py-3">Animate</Button>
    </div>
  );
};

