const ImageEditor: React.FC<Pick<ControlsPanelProps, 'setLoading' | 'setError' | 'onGenerationComplete' | 'editorState' | 'setEditorState'>> = ({ setLoading, setError, onGenerationComplete, editorState, setEditorState }) => {
  const [prompt, setPrompt] = useState('');
  const [jsonContext, setJsonContext] = useState('');
  const [exportFormat, setExportFormat] = useState<string>(STYLE_ENGINE.defaultOutput.formats[0]);
  const [exportQualityId, setExportQualityId] = useState<string>(STYLE_ENGINE.defaultOutput.qualityLevels[2].id);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const base64 = await fileToBase64(file);
      setEditorState({
        originalImage: base64,
        workingImage: base64,
        selectedStyleId: null,
        lastGenerationId: crypto.randomUUID(),
      });
      setError(null);
    }
  };

  const handleApplyPrompt = async () => {
    if (!editorState.originalImage || !prompt.trim()) return;
    setLoading(true, "Processing image modifications...");
    setError(null);
    try {
      const response = await fetch(editorState.originalImage);
      const blob = await response.blob();
      const file = new File([blob], "original.png", { type: "image/png" });

      const resultUrl = await transformImageWithAI(
        file, 
        prompt, 
        jsonContext,
        (msg) => setLoading(true, msg)
      );

      setEditorState(prev => ({
        ...prev,
        workingImage: resultUrl,
        lastGenerationId: crypto.randomUUID(),
      }));
      onGenerationComplete({ type: 'image', url: resultUrl });
    } catch (err: any) {
      setError(err.message || "AI Modification failed.");
    } finally {
      setLoading(false, "");
    }
  };

  const handleMakeSnow = async () => {
    if (!editorState.originalImage) return;
    setLoading(true, "Initiating snow landscape transformation...");
    setError(null);
    try {
      const response = await fetch(editorState.originalImage);
      const blob = await response.blob();
      const file = new File([blob], "original.png", { type: "image/png" });

      const resultUrl = await applySnowLandscapePreset(
        file,
        (msg) => setLoading(true, msg)
      );

      setEditorState(prev => ({
        ...prev,
        workingImage: resultUrl,
        lastGenerationId: crypto.randomUUID(),
      }));
      onGenerationComplete({ type: 'image', url: resultUrl });
    } catch (err: any) {
      setError(err.message || "Snow preset failed. The server might be busy, please try again.");
    } finally {
      setLoading(false, "");
    }
  };

  const handleDownload = async () => {
      if (!editorState.workingImage) return;
      const qualitySetting = STYLE_ENGINE.defaultOutput.qualityLevels.find(q => q.id === exportQualityId);
      if (!qualitySetting) return;
      const img = new Image();
      img.src = editorState.workingImage;
      await new Promise(r => img.onload = r);
      const canvas = document.createElement('canvas');
      canvas.width = img.naturalWidth;
      canvas.height = img.naturalHeight;
      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      if (exportFormat === 'JPG') { ctx.fillStyle = 'white'; ctx.fillRect(0, 0, canvas.width, canvas.height); }
      ctx.drawImage(img, 0, 0);
      const mimeType = exportFormat === 'JPG' ? 'image/jpeg' : 'image/png';
      const quality = exportFormat === 'JPG' ? qualitySetting.jpgQuality : qualitySetting.pngCompression;
      const dataUrl = canvas.toDataURL(mimeType, quality);
      const a = document.createElement('a');
      a.href = dataUrl;
      a.download = `style-engine-${exportQualityId}-${Date.now()}.${exportFormat.toLowerCase()}`;
      a.click();
  };

  return (
    <div className="flex flex-col h-full space-y-4">
      <h2 className="text-xl font-bold text-white flex items-center gap-2"><EditMagicIcon className="w-6 h-6" /> Image Editor</h2>
      <div className="flex-grow space-y-4 overflow-y-auto pr-2 custom-scrollbar">
        <div className="border-2 border-dashed border-gray-600 rounded-lg p-4 text-center hover:border-indigo-500 transition-colors cursor-pointer relative h-32 flex items-center justify-center bg-gray-800/30">
          <input type="file" accept="image/*" onChange={handleFileChange} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" />
          {editorState.originalImage ? (
            <img src={editorState.originalImage} alt="Base Layer" className="max-h-full max-w-full object-contain rounded opacity-50 grayscale" />
          ) : (
             <div className="flex flex-col items-center"><UploadIcon className="w-6 h-6 text-gray-400 mb-1" /><p className="text-gray-400 text-xs">Upload Image to Edit</p></div>
          )}
        </div>

        <div className="space-y-4">
            <div>
              <label className="block text-xs font-bold uppercase text-gray-500 mb-1 tracking-wider">Advanced Context Overrides (JSON)</label>
              <textarea 
                className="w-full h-24 p-2 bg-gray-900 border border-gray-700 rounded focus:ring-1 focus:ring-indigo-500 text-[10px] text-indigo-400 font-mono resize-none"
                placeholder='Optionally paste a JSON profile to force specific attributes...'
                value={jsonContext}
                onChange={(e) => setJsonContext(e.target.value)}
              />
            </div>

            <div>
              <label className="block text-xs font-bold uppercase text-gray-500 mb-1 tracking-wider">Natural Language Instructions</label>
              <textarea 
                className="w-full h-28 p-2 bg-gray-800 border border-gray-700 rounded focus:ring-1 focus:ring-indigo-500 text-xs text-white placeholder-gray-500 resize-none"
                placeholder='e.g., "Remove the car in the background and change the hair to silver blue. Make the scene a neon cyberpunk landscape."'
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
              />
              <p className="text-[10px] text-gray-500 mt-1 italic">Describe additions, removals, style, or environmental changes.</p>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <Button onClick={handleApplyPrompt} disabled={!editorState.originalImage || !prompt.trim()} className="bg-indigo-600 text-xs py-3">
                Apply Edit
              </Button>
              <Button onClick={handleMakeSnow} disabled={!editorState.originalImage} variant="secondary" className="border border-indigo-500/30 text-xs py-3">
                Make Snow Landscape
              </Button>
            </div>
        </div>

        {editorState.workingImage && (
            <div className="bg-gray-800/80 p-3 rounded-lg border border-indigo-500/30 space-y-3 animate-in fade-in slide-in-from-bottom-2">
                <h3 className="text-xs font-bold uppercase text-indigo-400 flex items-center gap-2"><DownloadIcon className="w-3 h-3" /> Export Result</h3>
                <div className="flex gap-2">
                    {STYLE_ENGINE.defaultOutput.formats.map(f => (
                        <button key={f} onClick={() => setExportFormat(f)} className={`flex-1 py-1 rounded text-[10px] border ${exportFormat === f ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-gray-900 border-gray-700 text-gray-400'}`}>{f}</button>
                    ))}
                </div>
                <div className="flex flex-col gap-1">
                    {STYLE_ENGINE.defaultOutput.qualityLevels.map(q => (
                        <button key={q.id} onClick={() => setExportQualityId(q.id)} className={`w-full py-1.5 px-3 rounded text-left flex justify-between items-center text-[10px] border transition-colors ${exportQualityId === q.id ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-gray-900 border-gray-700 text-gray-400'}`}>
                            <span className="font-bold">{q.label}</span><span className="opacity-60 italic">{q.description}</span>
                        </button>
                    ))}
                </div>
                <Button onClick={handleDownload} className="w-full bg-emerald-600 hover:bg-emerald-500 text-xs py-2"><DownloadIcon className="w-4 h-4" /> Download Image</Button>
            </div>
        )}
      </div>
    </div>
  );
};

