import { Part } from "@google/genai";

export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = (error) => reject(error);
  });
};

/**
 * Generates a very small thumbnail (e.g. 128px) for lazy-loading placeholders.
 */
export const generateThumbnail = (base64: string, size = 128): Promise<string> => {
  return new Promise((resolve) => {
    const img = new Image();
    img.src = base64;
    img.onload = () => {
      const canvas = document.createElement('canvas');
      const scale = Math.min(size / img.width, size / img.height);
      canvas.width = img.width * scale;
      canvas.height = img.height * scale;
      const ctx = canvas.getContext('2d');
      ctx?.drawImage(img, 0, 0, canvas.width, canvas.height);
      resolve(canvas.toDataURL('image/jpeg', 0.6));
    };
    img.onerror = () => resolve(base64);
  });
};

/**
 * Compresses a base64 image string to save storage space.
 * Target: Max 1024px dimension for canvas fidelity.
 */
export const compressImageBase64 = (base64: string, maxWidth = 1024, maxWeight = 0.75): Promise<string> => {
  return new Promise((resolve) => {
    const img = new Image();
    img.src = base64;
    img.onload = () => {
      const canvas = document.createElement('canvas');
      let width = img.width;
      let height = img.height;

      if (width > height) {
        if (width > maxWidth) {
          height *= maxWidth / width;
          width = maxWidth;
        }
      } else {
        if (height > maxWidth) {
          width *= maxWidth / height;
          height = maxWidth;
        }
      }

      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      ctx?.drawImage(img, 0, 0, width, height);
      resolve(canvas.toDataURL('image/jpeg', maxWeight));
    };
    img.onerror = () => resolve(base64); // Fallback to original
  });
};

export const fileToGenerativePart = async (file: File): Promise<Part> => {
    const base64EncodedData = await fileToBase64(file);
    const base64Data = base64EncodedData.split(',')[1];

    return {
      inlineData: {
        data: base64Data,
        mimeType: file.type,
      },
    };
};

export const downloadJson = (data: any, filename: string) => {
  const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

export const readJsonFile = (file: File): Promise<any> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const json = JSON.parse(e.target?.result as string);
        resolve(json);
      } catch (err) {
        reject(err);
      }
    };
    reader.onerror = (error) => reject(error);
    reader.readAsText(file);
  });
};

import React, { useState, useCallback, useEffect, useRef, useMemo } from 'react';
import { Character, ToolType, GeneratedContent, Scene, SoundEffect, EditorState } from './types';
import { Header } from './components/Header';
import { Sidebar } from './components/Sidebar';
import { Canvas } from './components/Canvas';
import { ControlsPanel } from './components/ControlsPanel';
import { CharacterCreatorModal } from './components/CharacterCreatorModal';
import { downloadJson } from './utils/fileUtils';

const MAX_CHARACTERS = 12;

function App() {
  const [characters, setCharacters] = useState<Character[]>([]);
  const [scenes, setScenes] = useState<Scene[]>([]);
  const [soundLibrary, setSoundLibrary] = useState<SoundEffect[]>([]);

  const [activeTool, setActiveTool] = useState<ToolType>('SCENE_BUILDER');
  const [selectedCharacterIds, setSelectedCharacterIds] = useState<string[]>([]);
  const [scenePrompt, setScenePrompt] = useState('Characters having a gathering in a vibrant studio setting.');
  const [sceneSoundEffect, setSceneSoundEffect] = useState<SoundEffect | undefined>(undefined);

  const [currentSceneId, setCurrentSceneId] = useState<string | null>(null);

  const [characterRotations, setCharacterRotations] = useState<Record<string, number>>({});
  const [characterPositions, setCharacterPositions] = useState<Record<string, { x: number; y: number }>>({});

  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [generatedContent, setGeneratedContent] = useState<GeneratedContent | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [editorState, setEditorState] = useState<EditorState>({
    originalImage: null,
    workingImage: null,
    selectedStyleId: null,
    lastGenerationId: null,
  });

  const [isCreatorModalOpen, setIsCreatorModalOpen] = useState(false);

  const scenePromptRef = useRef(scenePrompt);
  const selectedCharacterIdsRef = useRef(selectedCharacterIds);
  const characterRotationsRef = useRef(characterRotations);
  const characterPositionsRef = useRef(characterPositions);
  const sceneSoundEffectRef = useRef(sceneSoundEffect);

  useEffect(() => {
    scenePromptRef.current = scenePrompt;
    selectedCharacterIdsRef.current = selectedCharacterIds;
    characterRotationsRef.current = characterRotations;
    characterPositionsRef.current = characterPositions;
    sceneSoundEffectRef.current = sceneSoundEffect;
  }, [scenePrompt, selectedCharacterIds, characterRotations, characterPositions, sceneSoundEffect]);

  /**
   * AUTOMATIC STORAGE CLEANUP SYSTEM
   * Aggressively removes stale scene results and caches to maintain 12-character stability.
   */
  const performCleanup = useCallback(() => {
    setScenes(prev => {
      // Sort by date and prune results from scenes older than the top 2
      const sorted = [...prev].sort((a, b) => b.createdAt - a.createdAt);
      return sorted.map((scene, idx) => {
        if (idx > 1 && scene.generatedContent) {
           // We keep the scene but strip the heavy base64 image
           const { generatedContent, ...rest } = scene;
           return rest as Scene;
        }
        return scene;
      });
    });
    // Wipe autosave occasionally to prevent overhead
    localStorage.removeItem('css_autosave');
  }, []);

  /**
   * Proactive Quota Check and Silent Recovery
   */
  const safeSave = useCallback((key: string, value: any) => {
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch (e) {
      if (e instanceof DOMException && (e.code === 22 || e.name === 'QuotaExceededError')) {
        console.warn("Storage quota hit. Running emergency cleanup.");
        performCleanup();
        try {
          localStorage.setItem(key, JSON.stringify(value));
        } catch (retryError) {
          // If still failing, drop oldest scenes entirely
          setScenes(prev => prev.slice(0, 5));
          setError("Storage pressure. Old scenes were archived to allow new saves.");
        }
      }
    }
  }, [performCleanup]);

  // Initial Load with data migration
  useEffect(() => {
    try {
      const savedChars = localStorage.getItem('css_characters');
      if (savedChars) {
          const parsed = JSON.parse(savedChars).slice(0, MAX_CHARACTERS);
          setCharacters(parsed);
      }

      const savedScenes = localStorage.getItem('css_scenes');
      if (savedScenes) setScenes(JSON.parse(savedScenes));

      const savedSounds = localStorage.getItem('css_sound_library');
      if (savedSounds) setSoundLibrary(JSON.parse(savedSounds));

      const autosavedData = localStorage.getItem('css_autosave');
      if (autosavedData) {
        const parsed = JSON.parse(autosavedData);
        if (parsed.prompt) setScenePrompt(parsed.prompt);
        if (parsed.characterIds) setSelectedCharacterIds(parsed.characterIds);
        if (parsed.rotations) setCharacterRotations(parsed.rotations);
        if (parsed.positions) setCharacterPositions(parsed.positions);
        if (parsed.soundEffect) setSceneSoundEffect(parsed.soundEffect);
      }
    } catch (e) {
      console.error("Initial load failed", e);
    }
  }, []);

  // Proactive save cycles
  useEffect(() => {
    if (characters.length > 0) safeSave('css_characters', characters);
  }, [characters, safeSave]);

  useEffect(() => {
    if (scenes.length > 0) safeSave('css_scenes', scenes);
  }, [scenes, safeSave]);

  const handleSetLoading = useCallback((loading: boolean, message: string) => {
    setIsLoading(loading);
    setLoadingMessage(message);
  }, []);

  const handleGenerationComplete = useCallback((content: GeneratedContent) => {
    setGeneratedContent(content);
    if (activeTool === 'IMAGE_EDITOR' && content.type === 'image') {
      setEditorState(prev => ({
        ...prev,
        workingImage: content.url,
        lastGenerationId: crypto.randomUUID(),
      }));
    }
    setError(null);
    performCleanup();
  }, [activeTool, performCleanup]);

  const handleCharacterSelect = (id: string) => {
    setSelectedCharacterIds(prev =>
      prev.includes(id) 
        ? prev.filter(charId => charId !== id) 
        : [...prev, id]
    );
  };

  const handleCharacterReorder = useCallback((reorderedCharacters: Character[]) => {
    const newIds = reorderedCharacters.map(c => c.id);
    setSelectedCharacterIds(newIds);
  }, []);

  const handleSaveCharacter = (character: Character) => {
    if (characters.length >= MAX_CHARACTERS) {
      setError(`Max limit of ${MAX_CHARACTERS} characters reached.`);
      return;
    }
    setCharacters(prev => [...prev, character]);
    setIsCreatorModalOpen(false);
  };

  const handleUpdateCharacter = (updatedChar: Character) => {
    setCharacters(prev => prev.map(c => c.id === updatedChar.id ? updatedChar : c));
  };

  const handleImportCharacter = (character: Character) => {
    if (characters.length >= MAX_CHARACTERS) {
        setError(`Limit reached: Maximum ${MAX_CHARACTERS} characters.`);
        return;
    }
    setCharacters(prev => {
        if (!prev.some(c => c.id === character.id)) return [...prev, character];
        return prev.map(c => c.id === character.id ? character : c);
    });
  };

  const handleImportLibrary = (newCharacters: Character[]) => {
     setCharacters(prev => {
         const combined = [...prev];
         newCharacters.forEach(newChar => {
             if (combined.length < MAX_CHARACTERS) {
                 const existingIndex = combined.findIndex(c => c.id === newChar.id);
                 if (existingIndex >= 0) combined[existingIndex] = newChar;
                 else combined.push(newChar);
             }
         });
         return combined;
     });
  };

  const handleDeleteCharacter = (id: string) => {
    setCharacters(prev => prev.filter(c => c.id !== id));
    setSelectedCharacterIds(prev => prev.filter(cid => cid !== id));
  };

  const handleSaveScene = (name: string) => {
    const sceneData = {
        characterIds: selectedCharacterIds,
        prompt: scenePrompt,
        soundEffect: sceneSoundEffect,
        rotations: characterRotations,
        positions: characterPositions,
        generatedContent: generatedContent || undefined,
    };

    const existingIndex = scenes.findIndex(s => s.id === currentSceneId || s.name === name);

    if (existingIndex > -1) {
        const updated = [...scenes];
        updated[existingIndex] = { ...scenes[existingIndex], ...sceneData, name };
        setScenes(updated);
    } else {
        const newScene: Scene = {
            id: crypto.randomUUID(),
            name,
            ...sceneData,
            createdAt: Date.now(),
        };
        setScenes(prev => [newScene, ...prev]);
        setCurrentSceneId(newScene.id);
    }
    performCleanup();
  };

  const handleLoadScene = (scene: Scene) => {
    setSelectedCharacterIds(scene.characterIds || []);
    setScenePrompt(scene.prompt || '');
    setSceneSoundEffect(scene.soundEffect);
    setCharacterRotations(scene.rotations || {});
    setCharacterPositions(scene.positions || {});
    setGeneratedContent(scene.generatedContent || null);
    setCurrentSceneId(scene.id);
    setActiveTool('SCENE_BUILDER');
  };

  const handleImportScene = (scene: Scene) => {
    setScenes(prev => {
        if (!prev.some(s => s.id === scene.id)) return [scene, ...prev];
        return prev.map(s => s.id === scene.id ? scene : s);
    });
  };

  const handleExportScene = () => {
    const exportName = currentSceneName || "Untitled Scene";
    const sceneData: Scene = {
      id: currentSceneId || crypto.randomUUID(),
      name: exportName,
      characterIds: selectedCharacterIds,
      prompt: scenePrompt,
      createdAt: Date.now(),
      soundEffect: sceneSoundEffect,
      rotations: characterRotations,
      positions: characterPositions,
      generatedContent: generatedContent || undefined
    };
    downloadJson(sceneData, `scene-${exportName.replace(/\s+/g, '_')}.json`);
  };

  const handleDeleteScene = (id: string) => {
    setScenes(prev => prev.filter(s => s.id !== id));
    if (currentSceneId === id) setCurrentSceneId(null);
  };

  const handleResetScene = () => {
    setSelectedCharacterIds([]);
    setScenePrompt('Characters having a gathering in a vibrant studio setting.');
    setSceneSoundEffect(undefined);
    setCharacterRotations({});
    setCharacterPositions({});
    setCurrentSceneId(null);
    setGeneratedContent(null);
    setError(null);
  };

  // LAZY LOADING MEMORY OPTIMIZATION
  // We compute selected characters and ensure only they occupy the primary render pipeline
  const selectedCharacters = useMemo(() => {
      return selectedCharacterIds
        .map(id => characters.find(c => c.id === id))
        .filter((c): c is Character => c !== undefined && c !== null);
  }, [selectedCharacterIds, characters]);

  const currentSceneName = scenes.find(s => s.id === currentSceneId)?.name;

  return (
    <div className="h-screen w-screen flex flex-col bg-gray-900 overflow-hidden">
      <Header activeTool={activeTool} setActiveTool={setActiveTool} />
      <div className="flex flex-grow overflow-x-auto overflow-y-hidden custom-scrollbar">
        <Sidebar
          characters={characters}
          selectedCharacterIds={selectedCharacterIds}
          onCharacterSelect={handleCharacterSelect}
          onAddCharacterClick={() => {
              if (characters.length < MAX_CHARACTERS) setIsCreatorModalOpen(true);
              else setError(`Limit reached: Maximum ${MAX_CHARACTERS} characters.`);
          }}
          onImportCharacter={handleImportCharacter}
          onImportLibrary={handleImportLibrary}
          onDeleteCharacter={handleDeleteCharacter}
          scenes={scenes}
          onSceneSelect={handleLoadScene}
          onImportScene={handleImportScene}
          onSceneDelete={handleDeleteScene}
          maxCapacity={MAX_CHARACTERS}
        />
        <Canvas
          isLoading={isLoading}
          loadingMessage={loadingMessage}
          generatedContent={generatedContent}
          activeTool={activeTool}
          editorState={editorState}
          error={error}
          selectedCharacters={selectedCharacters}
          onCharacterReorder={handleCharacterReorder}
          characterRotations={characterRotations}
          onRotationChange={(id, rot) => setCharacterRotations(prev => ({ ...prev, [id]: rot }))}
          characterPositions={characterPositions}
          onPositionChange={(id, pos) => setCharacterPositions(prev => ({ ...prev, [id]: pos }))}
        />
        <ControlsPanel
          activeTool={activeTool}
          characters={characters}
          selectedCharacters={selectedCharacters}
          setLoading={handleSetLoading}
          setError={setError}
          onGenerationComplete={handleGenerationComplete}
          onSaveCharacter={handleSaveCharacter}
          onUpdateCharacter={handleUpdateCharacter}
          editorState={editorState}
          setEditorState={setEditorState}
          scenePrompt={scenePrompt}
          setScenePrompt={setScenePrompt}
          onSaveScene={handleSaveScene}
          currentSceneName={currentSceneName}
          sceneSoundEffect={sceneSoundEffect}
          setSceneSoundEffect={setSceneSoundEffect}
          soundLibrary={soundLibrary}
          setSoundLibrary={setSoundLibrary}
          characterRotations={characterRotations}
          onResetScene={handleResetScene}
          scenes={scenes}
          onLoadScene={handleLoadScene}
          onExportScene={handleExportScene}
        />
      </div>
      {isCreatorModalOpen && (
        <CharacterCreatorModal 
          onClose={() => setIsCreatorModalOpen(false)}
          onSave={handleSaveCharacter}
        />
      )}
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { Character, Scene } from '../types';
import { Button } from './common/Button';
import { AddUserIcon, CollectionIcon, SceneIcon, TrashIcon, ImportIcon, ExportIcon } from '../constants';
import { downloadJson, readJsonFile } from '../utils/fileUtils';

interface SidebarProps {
  characters: Character[];
  selectedCharacterIds: string[];
  onCharacterSelect: (id: string) => void;
  onAddCharacterClick: () => void;
  onImportCharacter: (character: Character) => void;
  onImportLibrary: (characters: Character[]) => void;
  onDeleteCharacter: (id: string) => void;
  scenes: Scene[];
  onSceneSelect: (scene: Scene) => void;
  onImportScene: (scene: Scene) => void;
  onSceneDelete: (id: string) => void;
  maxCapacity?: number;
}

const CharacterCard: React.FC<{
  character: Character;
  isSelected: boolean;
  onSelect: () => void;
  onDelete: () => void;
}> = ({ character, isSelected, onSelect, onDelete }) => {
  const handleExport = (e: React.MouseEvent) => {
    e.stopPropagation();
    downloadJson(character, `character-${character.name.replace(/\s+/g, '_')}.json`);
  };

  if (!character) return null;

  // Use thumbnail for the library list to save memory
  const previewUrl = character.thumbnailUrl || character.imageUrl;

  return (
    <div
      onClick={onSelect}
      className={`relative rounded-lg overflow-hidden cursor-pointer border-2 transition-all group ${
        isSelected ? 'border-indigo-500 scale-105 shadow-lg shadow-indigo-500/20' : 'border-transparent hover:border-indigo-600/50'
      }`}
    >
      <img src={previewUrl} alt={character.name} className="w-full h-auto aspect-square object-cover bg-gray-900" loading="lazy" />
      <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black to-transparent p-2">
        <p className="text-white font-semibold text-[10px] truncate pr-6">{character.name}</p>
      </div>
      <div className="absolute top-1 right-1 flex flex-col gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
        <button
          onClick={handleExport}
          className="bg-gray-900/80 p-1 rounded-full text-gray-300 hover:text-white"
          title="Export Character"
        >
          <ExportIcon className="w-3 h-3" />
        </button>
        <button
          onClick={(e) => { e.stopPropagation(); onDelete(); }}
          className="bg-gray-900/80 p-1 rounded-full text-gray-300 hover:text-red-400"
          title="Delete Character"
        >
          <TrashIcon className="w-3 h-3" />
        </button>
      </div>
    </div>
  );
};

const SceneCard: React.FC<{
  scene: Scene;
  onSelect: () => void;
  onDelete: () => void;
}> = ({ scene, onSelect, onDelete }) => {
  const handleExport = (e: React.MouseEvent) => {
    e.stopPropagation();
    downloadJson(scene, `scene-${scene.name.replace(/\s+/g, '_')}.json`);
  };

  return (
    <div className="bg-gray-700/50 rounded-lg p-3 border border-gray-600 hover:bg-gray-700 transition-colors group relative">
      <div onClick={onSelect} className="cursor-pointer">
        <h4 className="font-semibold text-white text-sm mb-1 pr-6 truncate">{scene.name}</h4>
        <p className="text-[10px] text-gray-400 line-clamp-2 italic">"{scene.prompt}"</p>
        <div className="mt-2 flex items-center gap-2 text-[10px] text-gray-500">
           <span className="bg-gray-800 px-1.5 py-0.5 rounded">{scene.characterIds?.length || 0} chars</span>
           <span>{new Date(scene.createdAt).toLocaleDateString()}</span>
        </div>
      </div>
      <div className="absolute top-2 right-2 flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
         <button 
            onClick={handleExport}
            className="p-1 text-gray-500 hover:text-white"
            title="Export Scene"
         >
            <ExportIcon className="w-4 h-4" />
         </button>
         <button 
            onClick={(e) => { e.stopPropagation(); onDelete(); }}
            className="p-1 text-gray-500 hover:text-red-400"
            title="Delete Scene"
         >
            <TrashIcon className="w-4 h-4" />
         </button>
      </div>
    </div>
  );
};

export const Sidebar: React.FC<SidebarProps> = ({ 
  characters, 
  selectedCharacterIds, 
  onCharacterSelect, 
  onAddCharacterClick,
  onImportCharacter,
  onImportLibrary,
  onDeleteCharacter,
  scenes,
  onSceneSelect,
  onImportScene,
  onSceneDelete,
  maxCapacity = 12
}) => {
  const [activeTab, setActiveTab] = useState<'CHARACTERS' | 'SCENES'>('CHARACTERS');

  const handleImportClick = (type: 'character' | 'scene') => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'application/json';
    input.onchange = async (e) => {
      const file = (e.target as HTMLInputElement).files?.[0];
      if (file) {
        try {
          const data = await readJsonFile(file);
          if (type === 'character') {
             if (Array.isArray(data)) {
                 onImportLibrary(data);
             } else if (data.id && data.name && data.imageUrl) {
                 onImportCharacter(data);
             } else {
                alert("Invalid character file.");
             }
          } else {
             if (data.id && data.name && Array.isArray(data.characterIds)) {
                onImportScene(data);
             } else {
                alert("Invalid scene file.");
             }
          }
        } catch (err) {
          console.error("Import failed", err);
          alert("Failed to read file.");
        }
      }
    };
    input.click();
  };

  const handleExportLibrary = () => {
      if (characters.length === 0) return;
      downloadJson(characters, 'character_library.json');
  };

  const atCapacity = characters.length >= maxCapacity;

  return (
    <aside className="w-64 flex-shrink-0 bg-gray-800/50 flex flex-col border-r border-gray-700">
      <div className="flex border-b border-gray-700">
        <button
          onClick={() => setActiveTab('CHARACTERS')}
          className={`flex-1 py-3 text-sm font-medium flex items-center justify-center gap-2 transition-colors ${
            activeTab === 'CHARACTERS' ? 'bg-gray-800 text-white border-b-2 border-indigo-500' : 'text-gray-400 hover:text-gray-200'
          }`}
        >
          <CollectionIcon className="w-4 h-4" />
          Library
        </button>
        <button
          onClick={() => setActiveTab('SCENES')}
          className={`flex-1 py-3 text-sm font-medium flex items-center justify-center gap-2 transition-colors ${
            activeTab === 'SCENES' ? 'bg-gray-800 text-white border-b-2 border-indigo-500' : 'text-gray-400 hover:text-gray-200'
          }`}
        >
          <SceneIcon className="w-4 h-4" />
          Scenes
        </button>
      </div>

      <div className="flex-grow overflow-y-auto p-4 custom-scrollbar">
        {activeTab === 'CHARACTERS' ? (
          <>
            <div className="flex flex-col gap-3 mb-4">
              <div className="flex justify-between items-center px-1">
                 <span className="text-[10px] uppercase font-bold text-gray-500 tracking-widest">Capacity</span>
                 <span className={`text-[10px] font-bold ${atCapacity ? 'text-orange-400' : 'text-indigo-400'}`}>
                    {characters.length} / {maxCapacity}
                 </span>
              </div>
              <div className="flex gap-2">
                <Button 
                    onClick={onAddCharacterClick} 
                    disabled={atCapacity}
                    className={`flex-1 text-xs px-2 ${atCapacity ? 'opacity-50' : 'bg-indigo-600 shadow-lg shadow-indigo-500/10'}`}
                >
                  <AddUserIcon className="w-4 h-4" /> New
                </Button>
                <div className="flex gap-1">
                  <Button onClick={() => handleImportClick('character')} disabled={atCapacity} variant="secondary" className="px-2" title="Import Character">
                      <ImportIcon className="w-4 h-4" />
                  </Button>
                  <Button onClick={handleExportLibrary} variant="secondary" className="px-2" title="Export Library" disabled={characters.length === 0}>
                      <ExportIcon className="w-4 h-4" />
                  </Button>
                </div>
              </div>
            </div>
            {characters.length === 0 ? (
              <div className="text-center text-gray-500 mt-12 py-8 border-2 border-dashed border-gray-700 rounded-xl">
                <p className="text-xs font-medium">Library is empty</p>
                <p className="text-[10px] mt-1">Create or import characters</p>
              </div>
            ) : (
              <div className="grid grid-cols-2 gap-3 pb-8">
                {characters.map(char => (
                  <CharacterCard
                    key={char.id}
                    character={char}
                    isSelected={selectedCharacterIds.includes(char.id)}
                    onSelect={() => onCharacterSelect(char.id)}
                    onDelete={() => onDeleteCharacter(char.id)}
                  />
                ))}
              </div>
            )}
          </>
        ) : (
          <>
             <Button onClick={() => handleImportClick('scene')} variant="secondary" className="w-full mb-4 text-xs">
               <ImportIcon className="w-4 h-4" /> Import Scene
             </Button>
             {scenes.length === 0 ? (
               <div className="text-center text-gray-500 mt-12 py-8 border-2 border-dashed border-gray-700 rounded-xl">
                 <p className="text-xs font-medium">No saved scenes</p>
                 <p className="text-[10px] mt-1">Compose and save to list</p>
               </div>
             ) : (
               <div className="flex flex-col gap-3 pb-8">
                 {scenes.map(scene => (
                   <SceneCard 
                     key={scene.id} 
                     scene={scene} 
                     onSelect={() => onSceneSelect(scene)}
                     onDelete={() => onSceneDelete(scene.id)}
                   />
                 ))}
               </div>
             )}
          </>
        )}
      </div>
    </aside>
  );
};

import React, { useState, useCallback } from 'react';
import { Character } from '../types';
import { generateCharacterDescription, generateCharacterWithStyle } from '../services/geminiService';
import { Button } from './common/Button';
import { Loader } from './common/Loader';
import { CloseIcon, CHARACTER_STYLES, SparklesIcon, AddUserIcon } from '../constants';
import { fileToBase64, compressImageBase64, generateThumbnail } from '../utils/fileUtils';

interface CharacterCreatorModalProps {
  onClose: () => void;
  onSave: (character: Character) => void;
}

type Step = 'UPLOAD' | 'DESCRIBE' | 'GENERATE' | 'SAVE';

export const CharacterCreatorModal: React.FC<CharacterCreatorModalProps> = ({ onClose, onSave }) => {
  const [step, setStep] = useState<Step>('UPLOAD');
  const [imageBase64, setImageBase64] = useState<string>('');
  const [description, setDescription] = useState('');
  const [characterPrompt, setCharacterPrompt] = useState('');
  const [characterStyle, setCharacterStyle] = useState<string>('Default');
  const [generatedImage, setGeneratedImage] = useState<string>('');
  const [characterName, setCharacterName] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [appliedStyleMetadata, setAppliedStyleMetadata] = useState<any>(null);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setIsLoading(true);
      try {
          const b64 = await fileToBase64(file);
          const compressed = await compressImageBase64(b64);
          setImageBase64(compressed);
          setStep('DESCRIBE');
          const desc = await generateCharacterDescription(file);
          setDescription(desc);
          setCharacterPrompt(desc);
      } catch (err) {
          setError('Failed to process image concept.');
      } finally {
          setIsLoading(false);
      }
    }
  };

  const handleGenerate = async () => {
    if (!characterName) {
      setError("Please enter a character name first.");
      return;
    }
    setIsLoading(true);
    setError(null);
    try {
      const result = await generateCharacterWithStyle(
        characterName,
        characterPrompt,
        characterStyle === 'Default' ? undefined : characterStyle
      );
      // Compress the final AI result before saving to library
      const compressedResult = await compressImageBase64(result.image);
      setGeneratedImage(compressedResult);
      setAppliedStyleMetadata(result);
      setStep('SAVE');
    } catch (err) {
      setError('Failed to generate character image. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (characterName && generatedImage) {
      setIsLoading(true);
      try {
        const thumb = await generateThumbnail(generatedImage);
        const newCharacter: Character = {
          id: crypto.randomUUID(),
          name: characterName,
          imageUrl: generatedImage,
          thumbnailUrl: thumb,
          prompt: characterPrompt,
          jsonProfile: appliedStyleMetadata ? appliedStyleMetadata.metadata : undefined,
        };
        onSave(newCharacter);
      } catch (e) {
        console.error("Save processing failed", e);
      } finally {
        setIsLoading(false);
      }
    }
  };

  const renderContent = () => {
    if (isLoading) {
      return <div className="h-64 flex items-center justify-center"><Loader message="AI is sculpting your character..." /></div>;
    }

    switch (step) {
      case 'UPLOAD':
        return (
          <div className="text-center p-8 border-2 border-dashed border-gray-600 rounded-lg">
            <h3 className="text-lg font-semibold mb-2 text-indigo-300">Start with a Concept</h3>
            <p className="text-gray-400 mb-4 text-sm">Upload a concept sketch, reference photo, or character to inspire the new creation.</p>
            <input type="file" id="char-upload" className="hidden" accept="image/*" onChange={handleFileChange} />
            <Button onClick={() => document.getElementById('char-upload')?.click()} className="bg-indigo-600 hover:bg-indigo-500 shadow-lg shadow-indigo-500/20">
              Select Concept Image
            </Button>
