const LayerManager: React.FC<{ 
  characters: Character[]; 
  onReorder: (reordered: Character[]) => void;
}> = ({ characters, onReorder }) => {
    const [draggedItemId, setDraggedItemId] = useState<string | null>(null);

    const handleDragStart = (e: React.DragEvent<HTMLDivElement>, id: string) => {
        setDraggedItemId(id);
        e.dataTransfer.effectAllowed = 'move';
    };

    const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
    };

    const handleDrop = (e: React.DragEvent<HTMLDivElement>, targetId: string) => {
        e.preventDefault();
        if (!draggedItemId || draggedItemId === targetId) return;

        // Clone and ensure we filter any undefined items
        const currentCharacters = [...characters].reverse().filter(c => !!c);
        const draggedIndex = currentCharacters.findIndex(c => c.id === draggedItemId);
        const targetIndex = currentCharacters.findIndex(c => c.id === targetId);

        if (draggedIndex === -1 || targetIndex === -1) return;

        const reordered = [...currentCharacters];
        const [draggedItem] = reordered.splice(draggedIndex, 1);
        reordered.splice(targetIndex, 0, draggedItem);

        onReorder(reordered.reverse());
        setDraggedItemId(null);
    };

    const handleDragEnd = () => setDraggedItemId(null);

    if (characters.length <= 1) return null;

    return (
        <div className="absolute bottom-4 right-4 bg-gray-800/90 backdrop-blur-md border border-gray-600 rounded-lg p-3 shadow-2xl z-40 w-52 ring-1 ring-white/10">
            <h4 className="text-[10px] font-bold uppercase text-gray-400 mb-2 tracking-widest flex justify-between items-center">
                Layers <span>{characters.length} total</span>
            </h4>
            <div className="space-y-1.5 max-h-64 overflow-y-auto custom-scrollbar pr-1">
                {[...characters].reverse().map(char => (
                    char && (
                        <div
                            key={char.id}
                            draggable
                            onDragStart={(e) => handleDragStart(e, char.id)}
                            onDragOver={handleDragOver}
                            onDrop={(e) => handleDrop(e, char.id)}
                            onDragEnd={handleDragEnd}
                            className={`flex items-center gap-2 p-1.5 rounded-md cursor-grab active:cursor-grabbing transition-all border ${draggedItemId === char.id ? 'opacity-30 bg-indigo-500 border-indigo-400' : 'bg-gray-700/50 hover:bg-gray-600/50 border-transparent hover:border-gray-500/30'}`}
                        >
                            <img src={char.thumbnailUrl || char.imageUrl} alt={char.name} className="w-8 h-8 rounded-sm object-cover bg-gray-900 border border-gray-600/30" />
                            <span className="text-[11px] font-semibold text-white truncate flex-1">{char.name}</span>
                        </div>
                    )
                ))}
            </div>
             <p className="text-[9px] text-gray-500 mt-2 text-center uppercase tracking-tighter">Drag items to change depth</p>
        </div>
    );
};

interface ImageDownloadModalProps {
  imageUrl: string;
  onClose: () => void;
}

const ImageDownloadModal: React.FC<ImageDownloadModalProps> = ({ imageUrl, onClose }) => {
  const [format, setFormat] = useState<'png' | 'jpg'>('png');
  const [resolution, setResolution] = useState<1 | 2 | 4>(1);
  const [isProcessing, setIsProcessing] = useState(false);

  const handleDownload = async () => {
    setIsProcessing(true);
    try {
        const img = new Image();
        img.src = imageUrl;
        await new Promise((resolve, reject) => {
            img.onload = resolve;
            img.onerror = reject;
        });

        const canvas = document.createElement('canvas');
        canvas.width = img.naturalWidth * resolution;
        canvas.height = img.naturalHeight * resolution;
        const ctx = canvas.getContext('2d');
        if (!ctx) throw new Error('Could not get canvas context');

        if (format === 'jpg') {
            ctx.fillStyle = '#FFFFFF';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
        }
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

        const mimeType = format === 'jpg' ? 'image/jpeg' : 'image/png';
        const quality = format === 'jpg' ? 0.95 : undefined;
        const dataUrl = canvas.toDataURL(mimeType, quality);

        const a = document.createElement('a');
        a.href = dataUrl;
        const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
        a.download = `studio-export-${resolution}x-${timestamp}.${format}`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        onClose();
    } catch (e) {
        console.error("Export failed", e);
    } finally {
        setIsProcessing(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-[100] p-4">
        <div className="bg-gray-900 border border-gray-700 rounded-xl p-6 max-w-sm w-full relative shadow-2xl ring-1 ring-white/10">
            <button onClick={onClose} className="absolute top-4 right-4 text-gray-500 hover:text-white transition-colors">
                <CloseIcon className="w-5 h-5" />
            </button>
