import React, { useState, useEffect, useRef } from 'react';
import { GeneratedContent, Character, EditorState, ToolType } from '../types';
import { Loader } from './common/Loader';
// Added SparklesIcon to the imports
import { SceneIcon, MicrophoneIcon, DownloadIcon, CloseIcon, SpeakerIcon, SpeakerXMarkIcon, CodeBracketIcon, SparklesIcon } from '../constants';
import { Button } from './common/Button';

interface CanvasProps {
  isLoading: boolean;
  loadingMessage: string;
  generatedContent: GeneratedContent | null;
  activeTool: ToolType;
  editorState: EditorState;
  error: string | null;
  selectedCharacters: Character[];
  onCharacterReorder: (reorderedCharacters: Character[]) => void;
  characterRotations: Record<string, number>;
  onRotationChange: (id: string, rotation: number) => void;
  characterPositions: Record<string, { x: number, y: number }>;
  onPositionChange: (id: string, position: { x: number, y: number }) => void;
}

const RotateLeftIcon = (props: React.SVGProps<SVGSVGElement>) => (
  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" {...props}>
    <path strokeLinecap="round" strokeLinejoin="round" d="M9 15 3 9m0 0 6-6M3 9h12a6 6 0 0 1 0 12h-3" />
  </svg>
);

const RotateRightIcon = (props: React.SVGProps<SVGSVGElement>) => (
  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" {...props}>
    <path strokeLinecap="round" strokeLinejoin="round" d="m15 15 6-6m0 0-6-6m6 6H9a6 6 0 0 0 0 12h3" />
  </svg>
);

const LayerManager: React.FC<{ 
  characters: Character[]; 
  onReorder: (reordered: Character[]) => void;
}> = ({ characters, onReorder }) => {
    const [draggedItemId, setDraggedItemId] = useState<string | null>(null);

    const handleDragStart = (e: React.DragEvent<HTMLDivElement>, id: string) => {
        setDraggedItemId(id);
        e.dataTransfer.effectAllowed = 'move';
    };

    const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
        e.preventDefault();
    };

    const handleDrop = (e: React.DragEvent<HTMLDivElement>, targetId: string) => {
        e.preventDefault();
        if (!draggedItemId || draggedItemId === targetId) return;

        // Clone and ensure we filter any undefined items
        const currentCharacters = [...characters].reverse().filter(c => !!c);
        const draggedIndex = currentCharacters.findIndex(c => c.id === draggedItemId);
        const targetIndex = currentCharacters.findIndex(c => c.id === targetId);

        if (draggedIndex === -1 || targetIndex === -1) return;

        const reordered = [...currentCharacters];
        const [draggedItem] = reordered.splice(draggedIndex, 1);
        reordered.splice(targetIndex, 0, draggedItem);

        onReorder(reordered.reverse());
        setDraggedItemId(null);
    };

    const handleDragEnd = () => setDraggedItemId(null);

    if (characters.length <= 1) return null;

    return (
        <div className="absolute bottom-4 right-4 bg-gray-800/90 backdrop-blur-md border border-gray-600 rounded-lg p-3 shadow-2xl z-40 w-52 ring-1 ring-white/10">
            <h4 className="text-[10px] font-bold uppercase text-gray-400 mb-2 tracking-widest flex justify-between items-center">
                Layers <span>{characters.length} total</span>
            </h4>
            <div className="space-y-1.5 max-h-64 overflow-y-auto custom-scrollbar pr-1">
                {[...characters].reverse().map(char => (
                    char && (
                        <div
                            key={char.id}
                            draggable
                            onDragStart={(e) => handleDragStart(e, char.id)}
                            onDragOver={handleDragOver}
                            onDrop={(e) => handleDrop(e, char.id)}
                            onDragEnd={handleDragEnd}
                            className={`flex items-center gap-2 p-1.5 rounded-md cursor-grab active:cursor-grabbing transition-all border ${draggedItemId === char.id ? 'opacity-30 bg-indigo-500 border-indigo-400' : 'bg-gray-700/50 hover:bg-gray-600/50 border-transparent hover:border-gray-500/30'}`}
                        >
                            <img src={char.thumbnailUrl || char.imageUrl} alt={char.name} className="w-8 h-8 rounded-sm object-cover bg-gray-900 border border-gray-600/30" />
                            <span className="text-[11px] font-semibold text-white truncate flex-1">{char.name}</span>
                        </div>
                    )
                ))}
            </div>
             <p className="text-[9px] text-gray-500 mt-2 text-center uppercase tracking-tighter">Drag items to change depth</p>
        </div>
    );
};

interface ImageDownloadModalProps {
  imageUrl: string;
  onClose: () => void;
}

const ImageDownloadModal: React.FC<ImageDownloadModalProps> = ({ imageUrl, onClose }) => {
  const [format, setFormat] = useState<'png' | 'jpg'>('png');
  const [resolution, setResolution] = useState<1 | 2 | 4>(1);
  const [isProcessing, setIsProcessing] = useState(false);

  const handleDownload = async () => {
    setIsProcessing(true);
    try {
        const img = new Image();
        img.src = imageUrl;
        await new Promise((resolve, reject) => {
            img.onload = resolve;
            img.onerror = reject;
        });

        const canvas = document.createElement('canvas');
        canvas.width = img.naturalWidth * resolution;
        canvas.height = img.naturalHeight * resolution;
        const ctx = canvas.getContext('2d');
        if (!ctx) throw new Error('Could not get canvas context');

        if (format === 'jpg') {
            ctx.fillStyle = '#FFFFFF';
            ctx.fillRect(0, 0, canvas.width, canvas.height);
        }
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

        const mimeType = format === 'jpg' ? 'image/jpeg' : 'image/png';
        const quality = format === 'jpg' ? 0.95 : undefined;
        const dataUrl = canvas.toDataURL(mimeType, quality);

        const a = document.createElement('a');
        a.href = dataUrl;
        const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
        a.download = `studio-export-${resolution}x-${timestamp}.${format}`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        onClose();
    } catch (e) {
        console.error("Export failed", e);
    } finally {
        setIsProcessing(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center z-[100] p-4">
        <div className="bg-gray-900 border border-gray-700 rounded-xl p-6 max-w-sm w-full relative shadow-2xl ring-1 ring-white/10">
            <button onClick={onClose} className="absolute top-4 right-4 text-gray-500 hover:text-white transition-colors">
                <CloseIcon className="w-5 h-5" />
            </button>
            <h3 className="text-lg font-bold text-white mb-6">Export Configuration</h3>
            <div className="space-y-6">
                <div>
                    <label className="block text-[10px] uppercase font-bold text-gray-500 mb-2 tracking-widest">Format</label>
                    <div className="flex gap-2 bg-black/40 p-1 rounded-lg">
                        {['png', 'jpg'].map(f => (
                            <button
                                key={f}
                                onClick={() => setFormat(f as 'png' | 'jpg')}
                                className={`flex-1 py-2 text-xs font-bold rounded-md transition-all ${format === f ? 'bg-indigo-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}
                            >
                                {f.toUpperCase()}
                            </button>
                        ))}
                    </div>
                </div>
                <div>
                    <label className="block text-[10px] uppercase font-bold text-gray-500 mb-2 tracking-widest">Resolution Scale</label>
                    <div className="flex gap-2 bg-black/40 p-1 rounded-lg">
                        {[1, 2, 4].map(r => (
                            <button
                                key={r}
                                onClick={() => setResolution(r as 1 | 2 | 4)}
                                className={`flex-1 py-2 text-xs font-bold rounded-md transition-all ${resolution === r ? 'bg-indigo-600 text-white shadow-lg' : 'text-gray-400 hover:text-white'}`}
                            >
                                {r}x
                            </button>
                        ))}
                    </div>
                </div>
                <Button onClick={handleDownload} className="w-full py-3 bg-indigo-600 mt-2" disabled={isProcessing}>
                    {isProcessing ? <Loader /> : 'Download Project'}
                </Button>
            </div>
        </div>
    </div>
  );
};

const AudioPlayer: React.FC<{ url: string }> = ({ url }) => {
    const audioRef = useRef<HTMLAudioElement>(null);
    const [isMuted, setIsMuted] = useState(false);
    useEffect(() => {
        if (audioRef.current) {
            audioRef.current.play().catch(e => console.log("Autoplay blocked", e));
        }
    }, [url]);
    const toggleMute = () => {
        if (audioRef.current) {
            audioRef.current.muted = !isMuted;
            setIsMuted(!isMuted);
        }
    };
    return (
        <div className="absolute top-4 left-4 z-50">
            <audio ref={audioRef} src={url} loop autoPlay muted={isMuted} />
            <button 
                onClick={toggleMute}
                className="bg-gray-900/90 hover:bg-indigo-600 text-white p-3 rounded-full shadow-2xl transition-all border border-gray-700/50 backdrop-blur-md"
                title={isMuted ? "Unmute Ambience" : "Mute Ambience"}
            >
                {isMuted ? <SpeakerXMarkIcon className="w-5 h-5" /> : <SpeakerIcon className="w-5 h-5" />}
            </button>
        </div>
    );
};

const TransformableCharacter: React.FC<{
    character: Character;
    rotation: number;
    position: { x: number, y: number };
    onRotationChange: (rot: number) => void;
    onPositionChange: (pos: { x: number, y: number }) => void;
    isSelected: boolean;
    onSelect: () => void;
    containerRef: React.RefObject<HTMLDivElement>;
}> = ({ character, rotation, position, onRotationChange, onPositionChange, isSelected, onSelect }) => {
    const [isDragging, setIsDragging] = useState(false);
    const [isRotating, setIsRotating] = useState(false);
    const startPosRef = useRef({ x: 0, y: 0 });
    const startRotationRef = useRef(0);
    const centerRef = useRef({ x: 0, y: 0 });
    const elementRef = useRef<HTMLDivElement>(null);

    const handleMouseDown = (e: React.MouseEvent) => {
        if (e.button !== 0) return;
        e.stopPropagation();
        onSelect();
        setIsDragging(true);
        startPosRef.current = { x: e.clientX - position.x, y: e.clientY - position.y };
    };

    const handleRotateMouseDown = (e: React.MouseEvent) => {
        e.stopPropagation();
        e.preventDefault();
        setIsRotating(true);
        if (elementRef.current) {
             const rect = elementRef.current.getBoundingClientRect();
             const centerX = rect.left + rect.width / 2;
             const centerY = rect.top + rect.height / 2;
             centerRef.current = { x: centerX, y: centerY };
             const currentAngle = Math.atan2(e.clientY - centerY, e.clientX - centerX) * (180 / Math.PI);
             startRotationRef.current = currentAngle - rotation;
        }
    };

    const handleRotateStep = (e: React.MouseEvent, degrees: number) => {
        e.stopPropagation();
        onRotationChange(rotation + degrees);
    };

    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            if (isDragging) {
                const newX = e.clientX - startPosRef.current.x;
                const newY = e.clientY - startPosRef.current.y;
                onPositionChange({ x: newX, y: newY });
            } else if (isRotating) {
                const { x: centerX, y: centerY } = centerRef.current;
                const angle = Math.atan2(e.clientY - centerY, e.clientX - centerX) * (180 / Math.PI);
                let newRotation = angle - startRotationRef.current;
                if (e.shiftKey) newRotation = Math.round(newRotation / 15) * 15;
                onRotationChange(newRotation);
            }
        };
        const handleMouseUp = () => {
            setIsDragging(false);
            setIsRotating(false);
        };
        if (isDragging || isRotating) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
        }
        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [isDragging, isRotating, onPositionChange, onRotationChange]);

    if (!character) return null;

    return (
        <div
            ref={elementRef}
            style={{
                transform: `translate(${position.x}px, ${position.y}px) rotate(${rotation}deg)`,
                position: 'absolute',
                top: 0,
                left: 0,
                cursor: isDragging ? 'grabbing' : 'grab',
                zIndex: isSelected ? 50 : undefined
            }}
            onMouseDown={handleMouseDown}
            className={`select-none transition-shadow ${isSelected ? 'z-50' : ''}`}
        >
            <div className={`relative ${isSelected ? 'ring-4 ring-indigo-500 rounded-lg shadow-2xl' : ''}`}>
                <img src={character.imageUrl} alt={character.name} className="w-48 h-auto object-contain pointer-events-none drop-shadow-lg" draggable={false} />
                {isSelected && (
                    <>
                        <div className="absolute -top-10 left-1/2 transform -translate-x-1/2 w-8 h-8 bg-white rounded-full shadow-2xl cursor-crosshair flex items-center justify-center border-2 border-indigo-600 hover:bg-indigo-50" onMouseDown={handleRotateMouseDown} title="Drag to rotate">
                            <div className="w-1.5 h-1.5 bg-indigo-600 rounded-full animate-pulse"></div>
                            <div className="absolute h-5 w-0.5 bg-indigo-500 top-full left-1/2 transform -translate-x-1/2"></div>
                        </div>
                        <div className="absolute -bottom-10 left-1/2 transform -translate-x-1/2 flex gap-3 p-1.5 bg-gray-900/95 backdrop-blur-md rounded-full border border-gray-600 shadow-2xl">
                            <button onClick={(e) => handleRotateStep(e, -15)} className="bg-gray-800 text-white p-2 rounded-full hover:bg-indigo-600 transition-colors" title="-15°"><RotateLeftIcon className="w-4 h-4" /></button>
                            <button onClick={(e) => handleRotateStep(e, 15)} className="bg-gray-800 text-white p-2 rounded-full hover:bg-indigo-600 transition-colors" title="+15°"><RotateRightIcon className="w-4 h-4" /></button>
                        </div>
                    </>
                )}
            </div>
        </div>
    );
};

export const Canvas: React.FC<CanvasProps> = ({ 
    isLoading, 
    loadingMessage, 
    generatedContent, 
    activeTool,
    editorState,
    error, 
    selectedCharacters, 
    onCharacterReorder,
    characterRotations,
    onRotationChange,
    characterPositions,
    onPositionChange
}) => {
  const [showDownloadModal, setShowDownloadModal] = useState(false);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setShowDownloadModal(false);
  }, [generatedContent, editorState.workingImage]);

  useEffect(() => {
    if (containerRef.current) {
        const { width, height } = containerRef.current.getBoundingClientRect();
        selectedCharacters.forEach((char, index) => {
            if (char && !characterPositions[char.id]) {
                const offset = index * 20; // Spread them out initially
                onPositionChange(char.id, { x: width / 2 - 100 + offset, y: height / 2 - 100 + offset });
            }
        });
    }
  }, [selectedCharacters.length]);

  const downloadMedia = (url: string, type: string) => {
      const a = document.createElement('a');
      a.href = url;
      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
      a.download = `project-${type}-${timestamp}.${type === 'audio' ? 'wav' : type === 'video' ? 'mp4' : 'json'}`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
  };

  const renderContent = () => {
    if (isLoading) return <Loader message={loadingMessage} />;

    if (error) {
      return (
        <div className="text-center text-red-400 bg-red-900/20 p-8 rounded-2xl border border-red-900/50 backdrop-blur-xl">
          <div className="bg-red-900/50 w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-4">
             <CloseIcon className="w-6 h-6" />
          </div>
          <h3 className="font-bold text-lg mb-2">System Interruption</h3>
          <p className="text-sm opacity-80">{error}</p>
          <Button variant="secondary" onClick={() => window.location.reload()} className="mt-6 text-xs px-6">Reset Workspace</Button>
        </div>
      );
    }

    if (activeTool === 'IMAGE_EDITOR' && editorState.workingImage) {
        return (
          <div className="relative group max-w-full max-h-full flex flex-col items-center animate-in fade-in zoom-in-95 duration-500">
            <img src={editorState.workingImage} alt="Workspace" className="max-w-full max-h-full object-contain rounded-2xl shadow-[0_32px_64px_-16px_rgba(0,0,0,0.5)] border border-white/5" />
            <div className="absolute top-4 left-4 bg-indigo-600/90 backdrop-blur-md px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-widest shadow-xl ring-1 ring-white/20">Working Canvas</div>
            <button onClick={() => setShowDownloadModal(true)} className="absolute top-4 right-4 bg-gray-900/90 hover:bg-indigo-600 text-white p-3 rounded-full opacity-0 group-hover:opacity-100 transition-all shadow-2xl backdrop-blur-md"><DownloadIcon className="w-6 h-6" /></button>
          </div>
        );
    }

    if (generatedContent) {
      const { type, url } = generatedContent;
      if (type === 'image') {
        return (
          <div className="relative group max-w-full max-h-full flex flex-col items-center animate-in fade-in zoom-in-95 duration-500">
            {generatedContent.soundEffectUrl && <AudioPlayer url={generatedContent.soundEffectUrl} />}
            <img src={url} alt="Result" className="max-w-full max-h-full object-contain rounded-2xl shadow-2xl" />
            <button onClick={() => setShowDownloadModal(true)} className="absolute top-4 right-4 bg-gray-900/90 hover:bg-indigo-600 text-white p-3 rounded-full opacity-0 group-hover:opacity-100 transition-all shadow-2xl"><DownloadIcon className="w-6 h-6" /></button>
          </div>
        );
      }
      if (type === 'video') {
        return (
          <div className="relative group max-w-full max-h-full flex flex-col items-center animate-in fade-in duration-500">
             <video src={url} controls autoPlay loop className="max-w-full max-h-full object-contain rounded-2xl shadow-2xl" />
             <button onClick={() => downloadMedia(url, 'video')} className="absolute top-4 right-4 bg-gray-900/90 hover:bg-indigo-600 text-white p-3 rounded-full opacity-0 group-hover:opacity-100 transition-all shadow-2xl z-10"><DownloadIcon className="w-6 h-6" /></button>
          </div>
        );
      }
      if (type === 'audio') {
          const char = selectedCharacters.find(c => c.id === generatedContent.characterId) || selectedCharacters[0];
          return (
              <div className="flex flex-col items-center gap-8 bg-gray-800/40 p-12 rounded-3xl border border-white/5 backdrop-blur-3xl max-w-lg w-full relative shadow-2xl animate-in slide-in-from-bottom-8 duration-700">
                  <div className="relative w-56 h-56 rounded-3xl overflow-hidden border-2 border-indigo-500/30 shadow-2xl">
                      {char ? <img src={char.imageUrl} alt={char.name} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-gray-700 flex items-center justify-center"><MicrophoneIcon className="w-16 h-16 text-gray-700" /></div>}
                      <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent"></div>
                      <div className="absolute bottom-4 left-0 right-0 text-center px-4"><h3 className="text-xl font-bold text-white truncate">{char?.name || 'Vocal Identity'}</h3></div>
                  </div>
                  <div className="w-full flex items-center gap-3">
                    <audio src={url} controls autoPlay className="w-full accent-indigo-500 rounded-lg" />
                    <button onClick={() => downloadMedia(url, 'audio')} className="bg-indigo-600 hover:bg-indigo-500 text-white p-3 rounded-2xl transition-all shadow-lg" title="Export Audio"><DownloadIcon className="w-5 h-5" /></button>
                  </div>
              </div>
          )
      }
      if (type === 'json') {
          return (
              <div className="flex flex-col w-full h-full max-w-4xl bg-gray-800/40 p-8 rounded-3xl border border-white/5 backdrop-blur-3xl relative shadow-2xl animate-in fade-in duration-500">
                  <div className="flex justify-between items-center mb-6">
                      <div className="flex items-center gap-3"><CodeBracketIcon className="w-8 h-8 text-indigo-400" /><h3 className="text-2xl font-bold text-white">Advanced Profile</h3></div>
                      <div className="flex gap-3">
                        <Button onClick={() => { navigator.clipboard.writeText(JSON.stringify(generatedContent.data, null, 2)); alert("Profile copied!"); }} variant="secondary" className="text-xs px-4">Copy</Button>
                        <Button onClick={() => downloadMedia(url, 'json')} className="text-xs px-4">Download</Button>
                      </div>
                  </div>
                  <div className="flex-grow overflow-auto bg-black/40 rounded-2xl border border-white/5 p-6 font-mono text-sm text-indigo-300 leading-relaxed custom-scrollbar"><pre>{JSON.stringify(generatedContent.data, null, 2)}</pre></div>
              </div>
          )
      }
    }

    if (selectedCharacters.length > 0) {
        return (
            <div ref={containerRef} className="w-full h-full relative overflow-hidden bg-black/20 rounded-3xl border-2 border-dashed border-gray-700/50 backdrop-blur-sm shadow-inner" onClick={() => setSelectedId(null)}>
                <div className="absolute inset-0 pointer-events-none opacity-20 bg-[radial-gradient(#4f46e5_1px,transparent_1px)] [background-size:40px_40px]"></div>
                <div className="absolute top-6 left-6 text-gray-500 pointer-events-none z-0"><p className="text-[10px] uppercase font-bold tracking-widest text-gray-400 mb-1">Scene Orchestration</p><p className="text-xs opacity-60">Arrange up to 8 characters on stage.</p></div>
                {selectedCharacters.map((char, index) => (
                    char && <TransformableCharacter key={`${char.id}-${index}`} character={char} rotation={characterRotations[char.id] || 0} position={characterPositions[char.id] || {x: 0, y: 0}} onRotationChange={(rot) => onRotationChange(char.id, rot)} onPositionChange={(pos) => onPositionChange(char.id, pos)} isSelected={selectedId === char.id} onSelect={() => setSelectedId(char.id)} containerRef={containerRef} />
                ))}
            </div>
        )
    }

    return (
      <div className="text-center text-gray-600 flex flex-col items-center gap-6 animate-in fade-in duration-1000">
        <div className="relative">
            <SceneIcon className="w-32 h-32 text-gray-800" />
            <div className="absolute -top-2 -right-2 w-8 h-8 bg-indigo-600 rounded-full flex items-center justify-center animate-bounce shadow-lg">
                <SparklesIcon className="w-5 h-5 text-white" />
            </div>
        </div>
        <div className="space-y-2">
            <h2 className="text-3xl font-black text-gray-400 tracking-tighter uppercase">Creative Void</h2>
            <p className="text-sm max-w-xs mx-auto opacity-60">Add up to 8 characters to your library and orchestrate your first scene.</p>
        </div>
      </div>
    );
  };

  return (
    <main className="relative flex-grow min-w-0 p-8 flex items-center justify-center bg-gray-900/90 overflow-hidden">
      <div className="w-full h-full flex items-center justify-center">
        {renderContent()}
      </div>
      <LayerManager characters={selectedCharacters} onReorder={handleCharacterReorder} />
      {showDownloadModal && (activeTool === 'IMAGE_EDITOR' ? editorState.workingImage : generatedContent?.type === 'image') && (
        <ImageDownloadModal imageUrl={activeTool === 'IMAGE_EDITOR' ? (editorState.workingImage || '') : (generatedContent?.url || '')} onClose={() => setShowDownloadModal(false)} />
      )}
    </main>
  );
};

