const TransformableCharacter: React.FC<{
    character: Character;
    rotation: number;
    position: { x: number, y: number };
    onRotationChange: (rot: number) => void;
    onPositionChange: (pos: { x: number, y: number }) => void;
    isSelected: boolean;
    onSelect: () => void;
    containerRef: React.RefObject<HTMLDivElement>;
}> = ({ character, rotation, position, onRotationChange, onPositionChange, isSelected, onSelect }) => {
    const [isDragging, setIsDragging] = useState(false);
    const [isRotating, setIsRotating] = useState(false);
    const startPosRef = useRef({ x: 0, y: 0 });
    const startRotationRef = useRef(0);
    const centerRef = useRef({ x: 0, y: 0 });
    const elementRef = useRef<HTMLDivElement>(null);

    const handleMouseDown = (e: React.MouseEvent) => {
        if (e.button !== 0) return;
        e.stopPropagation();
        onSelect();
        setIsDragging(true);
        startPosRef.current = { x: e.clientX - position.x, y: e.clientY - position.y };
    };

    const handleRotateMouseDown = (e: React.MouseEvent) => {
        e.stopPropagation();
        e.preventDefault();
        setIsRotating(true);
        if (elementRef.current) {
             const rect = elementRef.current.getBoundingClientRect();
             const centerX = rect.left + rect.width / 2;
             const centerY = rect.top + rect.height / 2;
             centerRef.current = { x: centerX, y: centerY };
             const currentAngle = Math.atan2(e.clientY - centerY, e.clientX - centerX) * (180 / Math.PI);
             startRotationRef.current = currentAngle - rotation;
        }
    };

    const handleRotateStep = (e: React.MouseEvent, degrees: number) => {
        e.stopPropagation();
        onRotationChange(rotation + degrees);
    };

    useEffect(() => {
        const handleMouseMove = (e: MouseEvent) => {
            if (isDragging) {
                const newX = e.clientX - startPosRef.current.x;
                const newY = e.clientY - startPosRef.current.y;
                onPositionChange({ x: newX, y: newY });
            } else if (isRotating) {
                const { x: centerX, y: centerY } = centerRef.current;
                const angle = Math.atan2(e.clientY - centerY, e.clientX - centerX) * (180 / Math.PI);
                let newRotation = angle - startRotationRef.current;
                if (e.shiftKey) newRotation = Math.round(newRotation / 15) * 15;
                onRotationChange(newRotation);
            }
        };
        const handleMouseUp = () => {
            setIsDragging(false);
            setIsRotating(false);
        };
        if (isDragging || isRotating) {
            window.addEventListener('mousemove', handleMouseMove);
            window.addEventListener('mouseup', handleMouseUp);
        }
        return () => {
            window.removeEventListener('mousemove', handleMouseMove);
            window.removeEventListener('mouseup', handleMouseUp);
        };
    }, [isDragging, isRotating, onPositionChange, onRotationChange]);

    if (!character) return null;

    return (
        <div
            ref={elementRef}
            style={{
                transform: `translate(${position.x}px, ${position.y}px) rotate(${rotation}deg)`,
                position: 'absolute',
                top: 0,
                left: 0,
                cursor: isDragging ? 'grabbing' : 'grab',
                zIndex: isSelected ? 50 : undefined
            }}
            onMouseDown={handleMouseDown}
            className={`select-none transition-shadow ${isSelected ? 'z-50' : ''}`}
        >
            <div className={`relative ${isSelected ? 'ring-4 ring-indigo-500 rounded-lg shadow-2xl' : ''}`}>
                <img src={character.imageUrl} alt={character.name} className="w-48 h-auto object-contain pointer-events-none drop-shadow-lg" draggable={false} />
                {isSelected && (
                    <>
                        <div className="absolute -top-10 left-1/2 transform -translate-x-1/2 w-8 h-8 bg-white rounded-full shadow-2xl cursor-crosshair flex items-center justify-center border-2 border-indigo-600 hover:bg-indigo-50" onMouseDown={handleRotateMouseDown} title="Drag to rotate">
                            <div className="w-1.5 h-1.5 bg-indigo-600 rounded-full animate-pulse"></div>
                            <div className="absolute h-5 w-0.5 bg-indigo-500 top-full left-1/2 transform -translate-x-1/2"></div>
                        </div>
                        <div className="absolute -bottom-10 left-1/2 transform -translate-x-1/2 flex gap-3 p-1.5 bg-gray-900/95 backdrop-blur-md rounded-full border border-gray-600 shadow-2xl">
                            <button onClick={(e) => handleRotateStep(e, -15)} className="bg-gray-800 text-white p-2 rounded-full hover:bg-indigo-600 transition-colors" title="-15°"><RotateLeftIcon className="w-4 h-4" /></button>
                            <button onClick={(e) => handleRotateStep(e, 15)} className="bg-gray-800 text-white p-2 rounded-full hover:bg-indigo-600 transition-colors" title="+15°"><RotateRightIcon className="w-4 h-4" /></button>
                        </div>
                    </>
                )}
            </div>
        </div>
    );
};

export const Canvas: React.FC<CanvasProps> = ({ 
    isLoading, 
    loadingMessage, 
    generatedContent, 
    activeTool,
    editorState,
    error, 
    selectedCharacters, 
    onCharacterReorder,
    characterRotations,
    onRotationChange,
    characterPositions,
    onPositionChange
}) => {
  const [showDownloadModal, setShowDownloadModal] = useState(false);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setShowDownloadModal(false);
  }, [generatedContent, editorState.workingImage]);

  useEffect(() => {
    if (containerRef.current) {
        const { width, height } = containerRef.current.getBoundingClientRect();
        selectedCharacters.forEach((char, index) => {
            if (char && !characterPositions[char.id]) {
                const offset = index * 20; // Spread them out initially
                onPositionChange(char.id, { x: width / 2 - 100 + offset, y: height / 2 - 100 + offset });
            }
        });
    }
  }, [selectedCharacters.length]);

  const downloadMedia = (url: string, type: string) => {
      const a = document.createElement('a');
      a.href = url;
      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
      a.download = `project-${type}-${timestamp}.${type === 'audio' ? 'wav' : type === 'video' ? 'mp4' : 'json'}`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
  };

  const renderContent = () => {
    if (isLoading) return <Loader message={loadingMessage} />;

    if (error) {
      return (
        <div className="text-center text-red-400 bg-red-900/20 p-8 rounded-2xl border border-red-900/50 backdrop-blur-xl">
          <div className="bg-red-900/50 w-12 h-12 rounded-full flex items-center justify-center mx-auto mb-4">
             <CloseIcon className="w-6 h-6" />
          </div>
          <h3 className="font-bold text-lg mb-2">System Interruption</h3>
          <p className="text-sm opacity-80">{error}</p>
          <Button variant="secondary" onClick={() => window.location.reload()} className="mt-6 text-xs px-6">Reset Workspace</Button>
        </div>
      );
    }

    if (activeTool === 'IMAGE_EDITOR' && editorState.workingImage) {
        return (
          <div className="relative group max-w-full max-h-full flex flex-col items-center animate-in fade-in zoom-in-95 duration-500">
            <img src={editorState.workingImage} alt="Workspace" className="max-w-full max-h-full object-contain rounded-2xl shadow-[0_32px_64px_-16px_rgba(0,0,0,0.5)] border border-white/5" />
            <div className="absolute top-4 left-4 bg-indigo-600/90 backdrop-blur-md px-3 py-1.5 rounded-full text-[10px] font-bold uppercase tracking-widest shadow-xl ring-1 ring-white/20">Working Canvas</div>
            <button onClick={() => setShowDownloadModal(true)} className="absolute top-4 right-4 bg-gray-900/90 hover:bg-indigo-600 text-white p-3 rounded-full opacity-0 group-hover:opacity-100 transition-all shadow-2xl backdrop-blur-md"><DownloadIcon className="w-6 h-6" /></button>
          </div>
        );
    }

    if (generatedContent) {
      const { type, url } = generatedContent;
      if (type === 'image') {
        return (
          <div className="relative group max-w-full max-h-full flex flex-col items-center animate-in fade-in zoom-in-95 duration-500">
            {generatedContent.soundEffectUrl && <AudioPlayer url={generatedContent.soundEffectUrl} />}
            <img src={url} alt="Result" className="max-w-full max-h-full object-contain rounded-2xl shadow-2xl" />
            <button onClick={() => setShowDownloadModal(true)} className="absolute top-4 right-4 bg-gray-900/90 hover:bg-indigo-600 text-white p-3 rounded-full opacity-0 group-hover:opacity-100 transition-all shadow-2xl"><DownloadIcon className="w-6 h-6" /></button>
          </div>
        );
      }
      if (type === 'video') {
        return (
          <div className="relative group max-w-full max-h-full flex flex-col items-center animate-in fade-in duration-500">
             <video src={url} controls autoPlay loop className="max-w-full max-h-full object-contain rounded-2xl shadow-2xl" />
             <button onClick={() => downloadMedia(url, 'video')} className="absolute top-4 right-4 bg-gray-900/90 hover:bg-indigo-600 text-white p-3 rounded-full opacity-0 group-hover:opacity-100 transition-all shadow-2xl z-10"><DownloadIcon className="w-6 h-6" /></button>
          </div>
        );
      }
      if (type === 'audio') {
          const char = selectedCharacters.find(c => c.id === generatedContent.characterId) || selectedCharacters[0];
          return (
              <div className="flex flex-col items-center gap-8 bg-gray-800/40 p-12 rounded-3xl border border-white/5 backdrop-blur-3xl max-w-lg w-full relative shadow-2xl animate-in slide-in-from-bottom-8 duration-700">
                  <div className="relative w-56 h-56 rounded-3xl overflow-hidden border-2 border-indigo-500/30 shadow-2xl">
                      {char ? <img src={char.imageUrl} alt={char.name} className="w-full h-full object-cover" /> : <div className="w-full h-full bg-gray-700 flex items-center justify-center"><MicrophoneIcon className="w-16 h-16 text-gray-700" /></div>}
                      <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-transparent to-transparent"></div>
                      <div className="absolute bottom-4 left-0 right-0 text-center px-4"><h3 className="text-xl font-bold text-white truncate">{char?.name || 'Vocal Identity'}</h3></div>
                  </div>
                  <div className="w-full flex items-center gap-3">
                    <audio src={url} controls autoPlay className="w-full accent-indigo-500 rounded-lg" />
                    <button onClick={() => downloadMedia(url, 'audio')} className="bg-indigo-600 hover:bg-indigo-500 text-white p-3 rounded-2xl transition-all shadow-lg" title="Export Audio"><DownloadIcon className="w-5 h-5" /></button>
                  </div>
              </div>
          )
      }
      if (type === 'json') {
          return (
              <div className="flex flex-col w-full h-full max-w-4xl bg-gray-800/40 p-8 rounded-3xl border border-white/5 backdrop-blur-3xl relative shadow-2xl animate-in fade-in duration-500">
                  <div className="flex justify-between items-center mb-6">
                      <div className="flex items-center gap-3"><CodeBracketIcon className="w-8 h-8 text-indigo-400" /><h3 className="text-2xl font-bold text-white">Advanced Profile</h3></div>
                      <div className="flex gap-3">
                        <Button onClick={() => { navigator.clipboard.writeText(JSON.stringify(generatedContent.data, null, 2)); alert("Profile copied!"); }} variant="secondary" className="text-xs px-4">Copy</Button>
                        <Button onClick={() => downloadMedia(url, 'json')} className="text-xs px-4">Download</Button>
                      </div>
                  </div>
                  <div className="flex-grow overflow-auto bg-black/40 rounded-2xl border border-white/5 p-6 font-mono text-sm text-indigo-300 leading-relaxed custom-scrollbar"><pre>{JSON.stringify(generatedContent.data, null, 2)}</pre></div>
              </div>
          )
      }
    }

    if (selectedCharacters.length > 0) {
        return (
            <div ref={containerRef} className="w-full h-full relative overflow-hidden bg-black/20 rounded-3xl border-2 border-dashed border-gray-700/50 backdrop-blur-sm shadow-inner" onClick={() => setSelectedId(null)}>
                <div className="absolute inset-0 pointer-events-none opacity-20 bg-[radial-gradient(#4f46e5_1px,transparent_1px)] [background-size:40px_40px]"></div>
                <div className="absolute top-6 left-6 text-gray-500 pointer-events-none z-0"><p className="text-[10px] uppercase font-bold tracking-widest text-gray-400 mb-1">Scene Orchestration</p><p className="text-xs opacity-60">Arrange up to 8 characters on stage.</p></div>
                {selectedCharacters.map((char, index) => (
                    char && <TransformableCharacter key={`${char.id}-${index}`} character={char} rotation={characterRotations[char.id] || 0} position={characterPositions[char.id] || {x: 0, y: 0}} onRotationChange={(rot) => onRotationChange(char.id, rot)} onPositionChange={(pos) => onPositionChange(char.id, pos)} isSelected={selectedId === char.id} onSelect={() => setSelectedId(char.id)} containerRef={containerRef} />
                ))}
            </div>
        )
    }

    return (
      <div className="text-center text-gray-600 flex flex-col items-center gap-6 animate-in fade-in duration-1000">
        <div className="relative">
            <SceneIcon className="w-32 h-32 text-gray-800" />
            <div className="absolute -top-2 -right-2 w-8 h-8 bg-indigo-600 rounded-full flex items-center justify-center animate-bounce shadow-lg">
                <SparklesIcon className="w-5 h-5 text-white" />
            </div>
        </div>
        <div className="space-y-2">
            <h2 className="text-3xl font-black text-gray-400 tracking-tighter uppercase">Creative Void</h2>
            <p className="text-sm max-w-xs mx-auto opacity-60">Add up to 8 characters to your library and orchestrate your first scene.</p>
        </div>
      </div>
    );
  };

  return (
    <main className="relative flex-grow min-w-0 p-8 flex items-center justify-center bg-gray-900/90 overflow-hidden">
      <div className="w-full h-full flex items-center justify-center">
        {renderContent()}
      </div>
      {/* Fixed: onReorder={onCharacterReorder} instead of handleCharacterReorder */}
      <LayerManager characters={selectedCharacters} onReorder={onCharacterReorder} />
      {showDownloadModal && (activeTool === 'IMAGE_EDITOR' ? editorState.workingImage : generatedContent?.type === 'image') && (
        <ImageDownloadModal imageUrl={activeTool === 'IMAGE_EDITOR' ? (editorState.workingImage || '') : (generatedContent?.url || '')} onClose={() => setShowDownloadModal(false)} />
      )}
    </main>
  );
};

import React, { useState, useCallback, useEffect } from 'react';
import { AspectRatio, Character, ToolType, SoundEffect, Scene, EditorState } from '../types';
import { Button } from './common/Button';
import { 
  generateScene, 
  generateVideo, 
  generateCharacterSpeech, 
  generateImageFromInput, 
  animateImage, 
  generateJsonContextProfile, 
  generateCharacterFromJson, 
  generateCharacterDirectly, 
  refineCharacter, 
  generateRandomName,
  transformImageWithAI,
  applySnowLandscapePreset
} from '../services/geminiService';
import { ApiKeySelector } from './ApiKeySelector';
import { 
  SaveIcon, 
  VOICE_NAMES, 
  UploadIcon, 
  MusicIcon, 
  TrashIcon, 
  FilePlusIcon, 
  ExportIcon, 
  PhotoIcon, 
  SparklesIcon, 
  CodeBracketIcon, 
  AddUserIcon, 
  STYLE_ENGINE, 
  DownloadIcon 
} from '../constants';
import { fileToBase64 } from '../utils/fileUtils';

interface ControlsPanelProps {
  activeTool: ToolType;
  selectedCharacters: Character[];
  characters: Character[];
  setLoading: (isLoading: boolean, message: string) => void;
  setError: (error: string | null) => void;
  onGenerationComplete: (content: { type: 'image' | 'video' | 'audio' | 'json'; url: string; data?: any; characterId?: string; soundEffectUrl?: string }) => void;
  onSaveCharacter: (character: Character) => void;
  onUpdateCharacter: (character: Character) => void;

  // Editor State Props
  editorState: EditorState;
  setEditorState: React.Dispatch<React.SetStateAction<EditorState>>;

  // Scene Builder Props
  scenePrompt: string;
  // Fixed: setScenePrompt should accept a string, not void
  setScenePrompt: (prompt: string) => void;
  onSaveScene: (name: string) => void;
  currentSceneName?: string;
  sceneSoundEffect: SoundEffect | undefined;
  setSceneSoundEffect: (sound: SoundEffect | undefined) => void;
  soundLibrary: SoundEffect[];
  setSoundLibrary: (library: SoundEffect[]) => void;
  characterRotations: Record<string, number>;
  onResetScene: () => void;
  scenes: Scene[];
  onLoadScene: (scene: Scene) => void;
  onExportScene: () => void;
}

const SceneBuilder: React.FC<Omit<ControlsPanelProps, 'activeTool'>> = ({ 
  selectedCharacters, 
  setLoading, 
  setError, 
  onGenerationComplete,
  scenePrompt,
  setScenePrompt,
  onSaveScene,
  currentSceneName,
  sceneSoundEffect,
  setSceneSoundEffect,
  soundLibrary,
  setSoundLibrary,
  characterRotations,
  onResetScene,
  scenes,
  onLoadScene,
  onExportScene
}) => {
  const [isSaving, setIsSaving] = useState(false);
  const [sceneName, setSceneName] = useState('');
  const [soundTab, setSoundTab] = useState<'SELECT' | 'UPLOAD'>('SELECT');
  const [sceneToLoad, setSceneToLoad] = useState('');

  const handleGenerate = useCallback(async () => {
    if (selectedCharacters.length === 0) {
      setError("Please select at least one character from the library.");
      return;
    }
    setLoading(true, "Building your scene...");
    setError(null);
    try {
      const imageUrl = await generateScene(
          selectedCharacters, 
          scenePrompt, 
          characterRotations, 
          (msg) => setLoading(true, msg)
      );
      onGenerationComplete({ 
        type: 'image', 
        url: imageUrl, 
        soundEffectUrl: sceneSoundEffect?.url 
      });
    } catch (err: any) {
      setError(err.message || "Failed to generate scene.");
    } finally {
      setLoading(false, "");
    }
  }, [selectedCharacters, scenePrompt, setLoading, setError, onGenerationComplete, sceneSoundEffect, characterRotations]);

  const initiateSave = () => {
    if (selectedCharacters.length === 0) {
        setError("Add characters to save a scene.");
        return;
    }
    setError(null);
    setSceneName(currentSceneName || '');
    setIsSaving(true);
  }

  const confirmSave = () => {
      if (sceneName.trim()) {
          onSaveScene(sceneName);
          setIsSaving(false);
      }
  };

  const handleSoundUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          const file = e.target.files[0];
          try {
              const base64 = await fileToBase64(file);
              const newSound: SoundEffect = {
                  id: crypto.randomUUID(),
                  name: file.name.replace(/\.[^/.]+$/, ""),
                  url: base64
              };
              setSoundLibrary([...soundLibrary, newSound]);
              setSceneSoundEffect(newSound);
          } catch (err) {
              console.error("Audio upload failed", err);
              setError("Failed to upload audio.");
          }
      }
  };

  const handleLoadSelect = (e: React.ChangeEvent<HTMLSelectElement>) => {
      const sceneId = e.target.value;
      setSceneToLoad(sceneId);
      const scene = scenes.find(s => s.id === sceneId);
      if (scene) {
          onLoadScene(scene);
      }
  };

  return (
    <div className="flex flex-col h-full">
      <div className="flex justify-between items-center mb-4">
        <h2 className="text-xl font-bold text-white">Scene Builder</h2>
        <div className="flex gap-2">
           <Button onClick={onResetScene} variant="secondary" className="px-2" title="New Scene">
              <FilePlusIcon className="w-4 h-4" />
           </Button>
           <div className="relative">
              <select 
                value={sceneToLoad} 
                onChange={handleLoadSelect}
                className="bg-gray-700 text-white text-xs rounded px-2 py-2 border border-gray-600 focus:outline-none focus:border-indigo-500 max-w-[100px]"
              >
                  <option value="" disabled>Load...</option>
                  {scenes.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
              </select>
           </div>
        </div>
      </div>

      <div className="flex-grow overflow-y-auto pr-2 space-y-6">
          <div className="space-y-2">
            <label className="block text-sm font-medium text-gray-300">Scene Description</label>
            <textarea
              className="w-full h-32 p-3 bg-gray-800 border border-gray-700 rounded-md focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-white placeholder-gray-500 resize-none"
              placeholder="Describe the scene setting, lighting, and action..."
              value={scenePrompt}
              onChange={(e) => setScenePrompt(e.target.value)}
            />
          </div>

          <div className="space-y-2 bg-gray-800/50 p-3 rounded-lg border border-gray-700">
             <div className="flex justify-between items-center mb-2">
                 <label className="text-sm font-medium text-gray-300 flex items-center gap-2">
                    <MusicIcon className="w-4 h-4 text-indigo-400" />
                    Sound Effect / Ambience
                 </label>
                 {sceneSoundEffect && (
                     <button 
                        onClick={() => setSceneSoundEffect(undefined)}
                        className="text-xs text-red-400 hover:text-red-300 flex items-center gap-1"
                     >
                         <TrashIcon className="w-3 h-3" /> Clear
                     </button>
                 )}
             </div>

             <div className="flex gap-2 mb-2">
                 <button 
                    onClick={() => setSoundTab('SELECT')}
                    className={`flex-1 text-xs py-1 rounded ${soundTab === 'SELECT' ? 'bg-indigo-600 text-white' : 'bg-gray-700 text-gray-400'}`}
                 >
                     Library
                 </button>
                 <button 
                    onClick={() => setSoundTab('UPLOAD')}
                    className={`flex-1 text-xs py-1 rounded ${soundTab === 'UPLOAD' ? 'bg-indigo-600 text-white' : 'bg-gray-700 text-gray-400'}`}
                 >
                     Upload
                 </button>
             </div>

             {soundTab === 'SELECT' ? (
                 <select 
                    value={sceneSoundEffect?.id || ''}
                    onChange={(e) => setSceneSoundEffect(soundLibrary.find(s => s.id === e.target.value))}
                    className="w-full bg-gray-900 border border-gray-600 rounded p-2 text-sm text-white"
                 >
                     <option value="">None selected</option>
                     {soundLibrary.map(sound => (
                         <option key={sound.id} value={sound.id}>{sound.name}</option>
                     ))}
                 </select>
             ) : (
                 <div className="border-2 border-dashed border-gray-600 rounded p-4 text-center hover:bg-gray-700/50 transition-colors cursor-pointer relative">
                     <input 
                        type="file" 
                        accept="audio/*" 
                        onChange={handleSoundUpload}
                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                     />
                     <UploadIcon className="w-6 h-6 mx-auto text-gray-400 mb-1" />
                     <p className="text-xs text-gray-400">Click to upload audio</p>
                 </div>
             )}

             {sceneSoundEffect && (
                 <div className="text-xs text-indigo-300 mt-1 flex items-center gap-1">
                     <span>Selected: {sceneSoundEffect.name}</span>
                 </div>
             )}
          </div>
      </div>

      <div className="pt-4 mt-auto border-t border-gray-700 flex flex-col gap-3">
        <Button onClick={handleGenerate} className="w-full py-3 text-lg shadow-lg shadow-indigo-500/20">
          Generate Scene
        </Button>

        <div className="flex gap-2">
            {isSaving ? (
                <div className="flex-1 flex gap-2">
                    <input 
                        type="text" 
                        value={sceneName}
                        onChange={(e) => setSceneName(e.target.value)}
                        placeholder="Scene Name"
                        className="flex-1 bg-gray-800 border border-gray-600 rounded px-2 text-sm"
                        autoFocus
                    />
                    <Button onClick={confirmSave} className="px-3 py-1 text-sm">Save</Button>
                    <Button onClick={() => setIsSaving(false)} variant="secondary" className="px-3 py-1 text-sm">Cancel</Button>
                </div>
            ) : (
                <Button onClick={initiateSave} variant="secondary" className="flex-1" title="Save Scene">
                  <SaveIcon className="w-4 h-4 mr-2" /> Save Scene
                </Button>
            )}
            <Button onClick={onExportScene} variant="secondary" className="px-3" title="Export JSON">
                <ExportIcon className="w-5 h-5" />
            </Button>
        </div>
      </div>
    </div>
  );
};

const JSONProfilerPanel: React.FC<Pick<ControlsPanelProps, 'setLoading' | 'setError' | 'onGenerationComplete' | 'onSaveCharacter'>> = ({ setLoading, setError, onGenerationComplete, onSaveCharacter }) => {
    const [imageFile, setImageFile] = useState<File | null>(null);
    const [previewUrl, setPreviewUrl] = useState<string>('');
    const [userPrompt, setUserPrompt] = useState('');
    const [lastJson, setLastJson] = useState<any | null>(null);

    const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const file = e.target.files[0];
            setImageFile(file);
            setPreviewUrl(URL.createObjectURL(file));
            setLastJson(null);
        }
    };

    const runAnalysis = async (customPrompt?: string) => {
        if (!imageFile) {
            setError("Please upload an image first.");
            return;
        }
        setLoading(true, "Analyzing image structure...");
        setError(null);
        try {
            const data = await generateJsonContextProfile(imageFile, customPrompt);
            setLastJson(data);
            const jsonString = JSON.stringify(data, null, 2);
            const blob = new Blob([jsonString], { type: 'application/json' });
            const url = URL.createObjectURL(blob);
            onGenerationComplete({ 
                type: 'json', 
                url: url,
                data: data 
            });
        } catch (err: any) {
            setError(err.message || "JSON Profile extraction failed.");
        } finally {
            setLoading(false, "");
        }
    };

    const handleCreateCharacterFromJson = async () => {
        if (!lastJson) return;
        setLoading(true, "Creating character from JSON profile...");
        setError(null);
        try {
            const { url, prompt } = await generateCharacterFromJson(lastJson);
            const name = lastJson.objects?.[0]?.label || "New Character";
            const newChar: Character = {
                id: crypto.randomUUID(),
                name,
                imageUrl: url,
                prompt: prompt,
                jsonProfile: { ...lastJson, character_name: name },
                version: 1
            };
            onSaveCharacter(newChar);
            onGenerationComplete({ type: 'image', url: url });
        } catch (err: any) {
            setError(err.message || "Failed to create character from JSON.");
        } finally {
            setLoading(false, "");
        }
    };

    const handleDirectCharacterCreation = async () => {
        if (!imageFile) return;
        setLoading(true, "Directly creating character from image...");
        setError(null);
        try {
            const { url, prompt, json } = await generateCharacterDirectly(imageFile);
            const name = "Direct Character";
            const newChar: Character = {
                id: crypto.randomUUID(),
                name,
                imageUrl: url,
                prompt: prompt,
                jsonProfile: json ? { ...json, character_name: name } : undefined,
                version: 1
            };
            onSaveCharacter(newChar);
            onGenerationComplete({ type: 'image', url: url });
        } catch (err: any) {
            setError(err.message || "Failed to directly create character.");
        } finally {
            setLoading(false, "");
        }
    };

    return (
        <div className="flex flex-col h-full space-y-4">
            <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <CodeBracketIcon className="w-6 h-6 text-indigo-400" /> JSON Profiler
            </h2>
            <div className="flex-grow space-y-4 overflow-y-auto pr-2">
                <div className="border-2 border-dashed border-gray-600 rounded-lg p-4 text-center hover:border-indigo-500 transition-colors cursor-pointer relative h-40 flex items-center justify-center bg-gray-800/30">
                    <input
                        type="file"
                        accept="image/*"
                        onChange={handleFileChange}
                        className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                    />
                    {previewUrl ? (
                        <img src={previewUrl} alt="Preview" className="max-h-full max-w-full object-contain rounded" />
                    ) : (
                        <div className="flex flex-col items-center">
                            <UploadIcon className="w-8 h-8 text-gray-400 mb-2" />
                            <p className="text-gray-400 text-xs">Upload Image</p>
                        </div>
                    )}
                </div>

                <div className="space-y-3">
                    <div className="flex gap-2">
                         <Button 
                            onClick={handleDirectCharacterCreation} 
                            disabled={!imageFile}
                            className="flex-1 bg-emerald-600 hover:bg-emerald-500 text-xs py-2"
                        >
                            <AddUserIcon className="w-4 h-4" /> Direct Character
                        </Button>
                    </div>

                    <div className="p-3 bg-gray-800/50 rounded-lg border border-gray-700 space-y-3">
                        <div className="space-y-2">
                             <Button onClick={() => runAnalysis()} disabled={!imageFile} className="w-full bg-indigo-600 hover:bg-indigo-500 text-xs">
                                Extract JSON Profile
                            </Button>

                            <Button 
                                onClick={handleCreateCharacterFromJson} 
                                disabled={!lastJson}
                                variant="secondary"
                                className={`w-full text-xs ${lastJson ? 'border-indigo-500 text-indigo-300' : ''}`}
                            >
                                <AddUserIcon className="w-4 h-4" /> Create Character (from Profile)
                            </Button>
                        </div>

                        <div className="border-t border-gray-700 pt-3">
                            <p className="text-[10px] uppercase font-bold text-gray-500 mb-2">Prompt-Based Extraction</p>
                            <textarea
                                className="w-full h-16 p-2 bg-gray-900 border border-gray-600 rounded-md focus:ring-1 focus:ring-indigo-500 text-xs text-white placeholder-gray-600"
                                placeholder='Focus e.g. "Color psychology..."'
                                value={userPrompt}
                                onChange={(e) => setUserPrompt(e.target.value)}
                            />
                            <Button 
                                onClick={() => runAnalysis(userPrompt)} 
                                variant="secondary" 
                                className="w-full mt-2 text-xs py-1"
                                disabled={!userPrompt.trim() || !imageFile}
                            >
                                Run Guided Analysis
                            </Button>
                        </div>
                    </div>
                </div>
            </div>
            <div className="text-[10px] text-gray-500 italic leading-tight">
                "Direct" skips extraction. "Create Character" uses the extracted profile for high-fidelity attributes.
            </div>
        </div>
    );
};

const CharacterEditorPanel: React.FC<Pick<ControlsPanelProps, 'selectedCharacters' | 'characters' | 'setLoading' | 'setError' | 'onGenerationComplete' | 'onSaveCharacter' | 'onUpdateCharacter'>> = ({ selectedCharacters, characters, setLoading, setError, onGenerationComplete, onSaveCharacter, onUpdateCharacter }) => {
    const [activeCharId, setActiveCharId] = useState<string>('');
    const [charName, setCharName] = useState('');
    const [editJson, setEditJson] = useState<any>(null);
    const [changeInstructions, setChangeInstructions] = useState('');
    const [activeCategory, setActiveCategory] = useState<'FACE' | 'HAIR' | 'CLOTHING' | 'BODY' | 'STYLE'>('FACE');
    const [isGeneratingName, setIsGeneratingName] = useState(false);

    useEffect(() => {
        if (selectedCharacters.length > 0 && !activeCharId) {
            setActiveCharId(selectedCharacters[0].id);
        }
    }, [selectedCharacters, activeCharId]);

    const activeChar = characters.find(c => c.id === activeCharId);

    useEffect(() => {
        if (activeChar) {
            setCharName(activeChar.name);
            setEditJson(activeChar.jsonProfile || {});
        }
    }, [activeChar]);

    const handleApplyEdits = async () => {
        if (!activeChar) return;
        if (!charName.trim()) {
            setError("Character name cannot be empty.");
            return;
        }
        setLoading(true, "Refining character appearance...");
        setError(null);
        try {
            const updatedJson = { ...editJson, character_name: charName };
            const newUrl = await refineCharacter(activeChar, updatedJson, changeInstructions);

            const updatedChar: Character = {
                ...activeChar,
                name: charName,
                imageUrl: newUrl,
                jsonProfile: updatedJson
            };

            onUpdateCharacter(updatedChar);
            onGenerationComplete({ type: 'image', url: newUrl });
        } catch (err: any) {
            setError(err.message || "Refinement failed.");
        } finally {
            setLoading(false, "");
        }
    };

    const handleNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const newName = e.target.value;
        setCharName(newName);
        if (activeChar) {
            onUpdateCharacter({ ...activeChar, name: newName });
        }
    };

    const handleRandomName = async () => {
        setIsGeneratingName(true);
        try {
            const style = editJson?.style?.technique || "general";
            const newName = await generateRandomName(style);
            setCharName(newName);
            if (activeChar) {
                onUpdateCharacter({ ...activeChar, name: newName });
            }
        } catch (err) {
            console.error("Failed to generate random name", err);
        } finally {
            setIsGeneratingName(false);
        }
    };

    const handleSaveVersion = () => {
        if (!activeChar) return;
        const newVersion: Character = {
            ...activeChar,
            id: crypto.randomUUID(),
            name: `${charName} (v${(activeChar.version || 1) + 1})`,
            version: (activeChar.version || 1) + 1,
            originalId: activeChar.originalId || activeChar.id,
            jsonProfile: { ...editJson, character_name: charName }
        };
        onSaveCharacter(newVersion);
        alert("New version saved to library!");
    };

    const updateJsonField = (path: string, value: any) => {
        const newJson = { ...editJson };
        const keys = path.split('.');
        let current = newJson;
        for (let i = 0; i < keys.length - 1; i++) {
            if (!current[keys[i]]) current[keys[i]] = {};
            current = current[keys[i]];
        }
        current[keys[keys.length - 1]] = value;
        setEditJson(newJson);
    };

    const handleReset = () => {
        if (activeChar) {
            setEditJson(activeChar.jsonProfile || {});
            setCharName(activeChar.name);
            setChangeInstructions('');
        }
    };

    if (!activeChar) {
        return <div className="p-4 text-center text-gray-500">Select a character to edit.</div>;
    }

    return (
        <div className="flex flex-col h-full space-y-4">
            <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <SparklesIcon className="w-6 h-6 text-indigo-400" /> Character Editor
            </h2>
            <div className="p-3 bg-gray-800/80 rounded-lg border border-gray-700 space-y-2">
                <label className="block text-[10px] uppercase font-bold text-gray-500">Character Identity</label>
                <div className="flex gap-2">
                    <input type="text" value={charName} onChange={handleNameChange} className="flex-1 bg-gray-900 border border-gray-600 rounded px-2 py-1.5 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none" placeholder="Character Name" />
                    <button onClick={handleRandomName} disabled={isGeneratingName} className="p-1.5 bg-gray-700 hover:bg-gray-600 text-indigo-400 rounded transition-colors disabled:opacity-50" title="Random Name Generator"><SparklesIcon className={`w-4 h-4 ${isGeneratingName ? 'animate-spin' : ''}`} /></button>
                </div>
            </div>
            <div className="flex gap-1 bg-gray-800 p-1 rounded-lg">
                {(['FACE', 'HAIR', 'CLOTHING', 'BODY', 'STYLE'] as const).map(cat => (
                    <button key={cat} onClick={() => setActiveCategory(cat)} className={`flex-1 py-1.5 text-[10px] font-bold rounded transition-colors ${activeCategory === cat ? 'bg-indigo-600 text-white' : 'text-gray-400 hover:text-white'}`}>{cat}</button>
                ))}
            </div>
            <div className="flex-grow overflow-y-auto pr-2 space-y-4">
                <div className="space-y-4 p-3 bg-gray-800/50 rounded-lg border border-gray-700">
                    {activeCategory === 'FACE' && (
                        <div className="space-y-3">
                            <div><label className="block text-xs text-gray-400 mb-1">Eyes & Expression</label><input type="text" className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs text-white" placeholder="e.g. Sharp blue eyes" onChange={(e) => updateJsonField('visual_analysis.eyes', e.target.value)} /></div>
                            <div><label className="block text-xs text-gray-400 mb-1">Face Shape & Features</label><input type="text" className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs text-white" placeholder="e.g. Angular jawline" onChange={(e) => updateJsonField('visual_analysis.face_shape', e.target.value)} /></div>
                        </div>
                    )}
                    {activeCategory === 'HAIR' && (
                        <div className="space-y-3">
                            <div><label className="block text-xs text-gray-400 mb-1">Hair Style & Length</label><input type="text" className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs text-white" placeholder="e.g. Messy undercut" onChange={(e) => updateJsonField('visual_analysis.hair_style', e.target.value)} /></div>
                            <div><label className="block text-xs text-gray-400 mb-1">Hair Color & Gradients</label><input type="text" className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs text-white" placeholder="e.g. Silver white" onChange={(e) => updateJsonField('visual_analysis.hair_color', e.target.value)} /></div>
                        </div>
                    )}
                    {activeCategory === 'CLOTHING' && (
                        <div className="space-y-3">
                            <div><label className="block text-xs text-gray-400 mb-1">Jersey / Clothing Style</label><input type="text" className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs text-white" placeholder="e.g. Cyberpunk jersey" onChange={(e) => updateJsonField('visual_analysis.clothing_style', e.target.value)} /></div>
                            <div><label className="block text-xs text-gray-400 mb-1">Logos & Graphics</label><input type="text" className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs text-white" placeholder="e.g. Neon tiger logo" onChange={(e) => updateJsonField('visual_analysis.graphics', e.target.value)} /></div>
                        </div>
                    )}
                    {activeCategory === 'STYLE' && (
                        <div className="space-y-3">
                            <div><label className="block text-xs text-gray-400 mb-1">Art Style Preset</label><select className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs text-white" onChange={(e) => updateJsonField('style.technique', e.target.value)}><option value="high-detail sports illustration">Sports Illustration</option><option value="cartoon exaggeration">Cartoonish</option><option value="minimalist vector style">Minimalist Vector</option><option value="realistic proportions">Realistic</option></select></div>
                            <div><label className="block text-xs text-gray-400 mb-1">Line Weight / Shading</label><input type="text" className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs text-white" placeholder="e.g. Bold outlines" onChange={(e) => updateJsonField('style.rendering', e.target.value)} /></div>
                        </div>
                    )}
                    <div className="border-t border-gray-700 pt-3">
                        <label className="block text-xs font-bold text-indigo-400 mb-2">Live Refinement Instruction</label>
                        <textarea className="w-full h-20 p-2 bg-gray-900 border border-gray-600 rounded-md focus:ring-1 focus:ring-indigo-500 text-xs text-white placeholder-gray-600" placeholder='e.g. "Make the hair longer..."' value={changeInstructions} onChange={(e) => setChangeInstructions(e.target.value)} />
                    </div>
                </div>
                <div className="p-2 bg-gray-900 rounded border border-gray-800">
                    <p className="text-[9px] uppercase font-bold text-gray-600 mb-1">Live JSON Profile Sync</p>
                    <pre className="text-[9px] text-emerald-500 font-mono overflow-x-auto max-h-32">{JSON.stringify({ ...editJson, character_name: charName }, null, 2)}</pre>
                </div>
            </div>
            <div className="space-y-2 pt-2 border-t border-gray-700">
                <Button onClick={handleApplyEdits} className="w-full py-2 bg-indigo-600 shadow-lg shadow-indigo-500/10">Apply & Preview Changes</Button>
                <div className="flex gap-2">
                    <Button onClick={handleSaveVersion} variant="secondary" className="flex-1 text-xs">Save Version</Button>
                    <Button onClick={handleReset} variant="secondary" className="px-3 text-xs">Reset</Button>
                </div>
            </div>
        </div>
    );
};

