const CharacterVoicePanel: React.FC<Pick<ControlsPanelProps, 'selectedCharacters' | 'setLoading' | 'setError' | 'onGenerationComplete'>> = ({ selectedCharacters, setLoading, setError, onGenerationComplete }) => {
  const [text, setText] = useState('');
  const [selectedVoice, setSelectedVoice] = useState(VOICE_NAMES[0]);
  const [targetCharacterId, setTargetCharacterId] = useState<string>('');
  useEffect(() => {
      if (selectedCharacters.length > 0 && !targetCharacterId) setTargetCharacterId(selectedCharacters[0].id);
  }, [selectedCharacters, targetCharacterId]);
  const handleGenerate = async () => {
    if (!text) return;
    setLoading(true, "Generating speech...");
    setError(null);
    try {
      const audioUrl = await generateCharacterSpeech(text, selectedVoice);
      onGenerationComplete({ type: 'audio', url: audioUrl, characterId: targetCharacterId || undefined });
    } catch (err: any) {
      setError(err.message || "Failed to generate speech.");
    } finally {
      setLoading(false, "");
    }
  };
  return (
    <div className="flex flex-col h-full space-y-6">
      <h2 className="text-xl font-bold text-white">Character Voice</h2>
      <div className="flex-grow space-y-6">
        <div><label className="block text-sm font-medium text-gray-300 mb-2">Character</label><select value={targetCharacterId} onChange={(e) => setTargetCharacterId(e.target.value)} className="w-full bg-gray-800 border border-gray-700 rounded-md p-3 text-white focus:ring-2 focus:ring-indigo-500"><option value="">-- No Specific Character --</option>{selectedCharacters.map(char => (<option key={char.id} value={char.id}>{char.name}</option>))}</select></div>
        <div><label className="block text-sm font-medium text-gray-300 mb-2">Spoken Text</label><textarea className="w-full h-40 p-3 bg-gray-800 border border-gray-700 rounded-md focus:ring-2 focus:ring-indigo-500 text-white placeholder-gray-500 resize-none" placeholder="Enter text..." value={text} onChange={(e) => setText(e.target.value)} /></div>
        <div><label className="block text-sm font-medium text-gray-300 mb-2">Voice Style</label><div className="grid grid-cols-2 gap-2">{VOICE_NAMES.map(voice => (<button key={voice} onClick={() => setSelectedVoice(voice)} className={`py-2 px-3 rounded-md text-sm border transition-colors ${selectedVoice === voice ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-gray-800 border-gray-600 text-gray-300 hover:bg-gray-700'}`}>{voice}</button>))}</div></div>
