const getGenAI = () => {
  if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
}

/**
 * Resilient Request Wrapper
 * Implements exponential backoff to handle 503 (Timeout) and 429 (Rate Limit) errors.
 */
async function resilientRequest<T>(
  requestFn: () => Promise<T>,
  onRetry?: (attempt: number, error: string) => void,
  maxRetries: number = 3
): Promise<T> {
  let lastError: any;
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      return await requestFn();
    } catch (error: any) {
      lastError = error;
      const isTransient = error.message?.includes("503") || 
                          error.message?.includes("429") || 
                          error.message?.includes("deadline") ||
                          error.message?.includes("expired");

      if (isTransient && attempt < maxRetries) {
        const delay = Math.pow(2, attempt) * 1000;
        if (onRetry) onRetry(attempt, error.message || "Transient error");
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw error;
    }
  }
  throw lastError;
}

/**
 * Applies a watermark to a base64 image string.
 */
export const applyWatermark = (base64Image: string, watermarkBase64: string): Promise<string> => {
  return new Promise((resolve, reject) => {
    const mainImg = new Image();
    mainImg.crossOrigin = "anonymous";
    mainImg.onload = () => {
      const watermarkImg = new Image();
      watermarkImg.crossOrigin = "anonymous";
      watermarkImg.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = mainImg.width;
        canvas.height = mainImg.height;
        const ctx = canvas.getContext('2d');
        if (!ctx) return reject("Could not get canvas context");

        // Draw main image
        ctx.drawImage(mainImg, 0, 0);

        // Calculate watermark dimensions (15% of main image width)
        const watermarkWidth = mainImg.width * 0.15;
        const watermarkHeight = (watermarkImg.height / watermarkImg.width) * watermarkWidth;

        // Calculate position (bottom-right with 2% padding)
        const padding = mainImg.width * 0.02;
        const x = mainImg.width - watermarkWidth - padding;
        const y = mainImg.height - watermarkHeight - padding;

        // Apply watermark with 25% opacity
        ctx.globalAlpha = 0.25;
        ctx.drawImage(watermarkImg, x, y, watermarkWidth, watermarkHeight);
        ctx.globalAlpha = 1.0;

        resolve(canvas.toDataURL('image/png', 1.0));
      };
      watermarkImg.onerror = reject;
      watermarkImg.src = watermarkBase64;
    };
    mainImg.onerror = reject;
    mainImg.src = base64Image;
  });
};

export const transformImageWithAI = async (
  imageFile: File,
  userPrompt: string,
  jsonContext?: string,
  onProgress?: (msg: string) => void
): Promise<string> => {
  const ai = getGenAI();
  const imagePart = await fileToGenerativePart(imageFile);

  const systemConstraints = `
    TASK: Comprehensive Image Modification.
    CORE CAPABILITIES:
    1. STYLE: Interpret any artistic style (watercolor, cyberpunk, retro, etc.).
    2. OBJECTS: Remove specified elements context-aware; Add new objects matching scene lighting and perspective.
    3. ADJUSTMENTS: Modify colors, tones, atmosphere, lighting, and textures.
    4. STRUCTURE: Support compositional changes, cropping, framing, and perspective shifts if requested.
    5. CHARACTERS: Modify hair, features, expressions, or clothing while preserving base identity.
    6. ENVIRONMENT: Redesign or stylize backgrounds and materials.

    EXECUTION RULES:
    - Interpret the prompt strictly according to user intent.
    - Preserve original image structure and identity unless modifications are explicitly requested.
    - Ensure all changes are visually coherent and perspective-correct.
  `;

  const contextInstruction = jsonContext 
    ? `PRIMARY STYLE/CONTEXT DATA (JSON Profile): ${jsonContext}. Apply these specific visual attributes.`
    : "";

  const finalPrompt = `
    ${systemConstraints}
    ${contextInstruction}
    USER MODIFICATION REQUEST: ${userPrompt}
    Render the modified result with professional-grade fidelity.
  `;

  return resilientRequest(
    async () => {
      const requestAi = getGenAI();
      const response = await requestAi.models.generateContent({
        model: MODEL_NAMES.IMAGE_EDITING,
        contents: { parts: [imagePart, { text: finalPrompt }] },
      });

      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
      throw new Error("AI Transformation failed to return an image.");
    },
    (attempt, err) => {
      if (onProgress) onProgress(`Server processing heavy edits. Retrying (Attempt ${attempt}/3)...`);
    }
  );
};

