    { name: "Café Scene", prompt: "The uploaded artwork displayed in a frame on a textured wall inside a cozy café. Warm ambient lighting, wooden tables, subtle bokeh, inviting atmosphere, lifestyle Etsy mockup." },
    { name: "Rustic Home", prompt: "The uploaded artwork in a wooden frame hanging on a rustic farmhouse wall. Warm sunlight, natural textures, dried flowers, cozy homestead feeling, high‑quality Etsy mockup." },
    { name: "Minimalist Gallery Wall", prompt: "The uploaded artwork framed as part of a curated gallery wall with neutral abstract art. White wall, balanced composition, soft shadows, modern minimalist interior, professional Etsy mockup." },
    { name: "Modern City Apartment", prompt: "Large framed version of the uploaded artwork displayed on a raw concrete wall in a modern industrial loft. Metal accents, warm Edison lighting, leather sofa, urban atmosphere, high‑contrast textures, stylish Etsy mockup." },
    { name: "Hallway / Entryway", prompt: "Minimalist hallway scene with the uploaded artwork framed above a narrow console table. Soft warm lighting, natural wood, small decorative bowl and keys, welcoming home vibe, clean Etsy mockup aesthetic." }
  ];

  let completed = 0;
  const tasks = variations.map(async (v, index) => {
    return resilientRequest(
      async () => {
        const requestAi = getGenAI();
        const response = await requestAi.models.generateContent({
          model: MODEL_NAMES.IMAGE_EDITING,
          contents: { parts: [imagePart, { text: v.prompt }] },
        });

        for (const part of response.candidates[0].content.parts) {
          if (part.inlineData) {
            const primaryUrl = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
            const watermarkedUrl = await applyWatermark(primaryUrl, watermarkSource);
            completed++;
            if (onProgress) onProgress(`Generating mockups: ${completed}/11...`);
            return [primaryUrl, watermarkedUrl];
          }
        }
        throw new Error(`Variation ${index + 1} failed.`);
      },
      (attempt, err) => {
        if (onProgress) onProgress(`Variation ${index + 1} retry ${attempt}/3...`);
      }
    );
  });

  const allPairs = await Promise.all(tasks);
  return allPairs.flat();
};

export const generateRandomName = async (style?: string): Promise<string> => {
  const ai = getGenAI();
  const prompt = `Generate a single, cool, and fitting name for a character with this style: ${style || 'general'}. Return ONLY the name, no extra text.`;
  const response = await ai.models.generateContent({
    model: MODEL_NAMES.ANALYSIS,
    contents: prompt,
  });
  return response.text?.trim() || "Unnamed Character";
};

export const generateCharacterWithStyle = async (
  characterName: string,
  characterDescription: string,
  characterStyle?: string
): Promise<any> => {
  const styleObj = CHARACTER_STYLES.find(s => s.name === characterStyle);
  const appliedStyle = styleObj ? styleObj.name : 'Default';
  const styleDescription = styleObj ? styleObj.description : 'Standard studio character design aesthetic.';

  const stylePrompt = styleObj 
    ? `Style: ${appliedStyle}. Definition: ${styleDescription}. Follow this style strictly.` 
    : "Style: High quality modern character design sheet aesthetic, isolated on white.";

  const fullPrompt = `Character Name: ${characterName}. Description: ${characterDescription}. ${stylePrompt} Isolated on white background, full body shot.`;

  return resilientRequest(async () => {
    const requestAi = getGenAI();
    const response = await requestAi.models.generateContent({
      model: MODEL_NAMES.IMAGE_EDITING,
      contents: { parts: [{ text: fullPrompt }] },
      config: {
        imageConfig: { aspectRatio: "1:1" },
      }
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return {
          image: `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`,
          appliedStyle,
          metadata: { styleDescription, generationNotes: "Style applied via instruction block." }
        };
      }
    }
    throw new Error("Failed to generate character image.");
  });
};

