export const generateCharacterDirectly = async (imageFile: File): Promise<{ url: string; prompt: string; json?: any }> => {
  const description = await generateCharacterDescription(imageFile);
  const jsonProfile = await generateJsonContextProfile(imageFile);
  const result = await generateCharacterWithStyle("Direct Character", description);
  return { url: result.image, prompt: description, json: jsonProfile };
