                        <div className="border-t border-gray-700 pt-3">
                            <p className="text-[10px] uppercase font-bold text-gray-500 mb-2">Prompt-Based Extraction</p>
                            <textarea
                                className="w-full h-16 p-2 bg-gray-900 border border-gray-600 rounded-md focus:ring-1 focus:ring-indigo-500 text-xs text-white placeholder-gray-600"
                                placeholder='Focus e.g. "Color psychology..."'
                                value={userPrompt}
                                onChange={(e) => setUserPrompt(e.target.value)}
                            />
                            <Button 
                                onClick={() => runAnalysis(userPrompt)} 
                                variant="secondary" 
                                className="w-full mt-2 text-xs py-1"
                                disabled={!userPrompt.trim() || !imageFile}
                            >
                                Run Guided Analysis
                            </Button>
                        </div>
                    </div>
                </div>
            </div>
            <div className="text-[10px] text-gray-500 italic leading-tight">
                "Direct" skips extraction. "Create Character" uses the extracted profile for high-fidelity attributes.
            </div>
        </div>
    );
};

const CharacterEditorPanel: React.FC<Pick<ControlsPanelProps, 'selectedCharacters' | 'characters' | 'setLoading' | 'setError' | 'onGenerationComplete' | 'onSaveCharacter' | 'onUpdateCharacter'>> = ({ selectedCharacters, characters, setLoading, setError, onGenerationComplete, onSaveCharacter, onUpdateCharacter }) => {
    const [activeCharId, setActiveCharId] = useState<string>('');
    const [charName, setCharName] = useState('');
    const [editJson, setEditJson] = useState<any>(null);
    const [changeInstructions, setChangeInstructions] = useState('');
    const [activeCategory, setActiveCategory] = useState<'FACE' | 'HAIR' | 'CLOTHING' | 'BODY' | 'STYLE'>('FACE');
    const [isGeneratingName, setIsGeneratingName] = useState(false);

    useEffect(() => {
        if (selectedCharacters.length > 0 && !activeCharId) {
            setActiveCharId(selectedCharacters[0].id);
        }
    }, [selectedCharacters, activeCharId]);

    const activeChar = characters.find(c => c.id === activeCharId);

    useEffect(() => {
        if (activeChar) {
            setCharName(activeChar.name);
            setEditJson(activeChar.jsonProfile || {});
        }
    }, [activeChar]);

    const handleApplyEdits = async () => {
        if (!activeChar) return;
        if (!charName.trim()) {
            setError("Character name cannot be empty.");
            return;
        }
        setLoading(true, "Refining character appearance...");
        setError(null);
        try {
            const updatedJson = { ...editJson, character_name: charName };
            const newUrl = await refineCharacter(activeChar, updatedJson, changeInstructions);

            const updatedChar: Character = {
                ...activeChar,
                name: charName,
                imageUrl: newUrl,
                jsonProfile: updatedJson
            };

            onUpdateCharacter(updatedChar);
            onGenerationComplete({ type: 'image', url: newUrl });
        } catch (err: any) {
            setError(err.message || "Refinement failed.");
        } finally {
            setLoading(false, "");
        }
    };

    const handleNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const newName = e.target.value;
        setCharName(newName);
        if (activeChar) {
            onUpdateCharacter({ ...activeChar, name: newName });
        }
    };

    const handleRandomName = async () => {
        setIsGeneratingName(true);
        try {
            const style = editJson?.style?.technique || "general";
            const newName = await generateRandomName(style);
            setCharName(newName);
            if (activeChar) {
                onUpdateCharacter({ ...activeChar, name: newName });
            }
        } catch (err) {
            console.error("Failed to generate random name", err);
        } finally {
            setIsGeneratingName(false);
        }
    };

    const handleSaveVersion = () => {
        if (!activeChar) return;
        const newVersion: Character = {
            ...activeChar,
            id: crypto.randomUUID(),
            name: `${charName} (v${(activeChar.version || 1) + 1})`,
            version: (activeChar.version || 1) + 1,
            originalId: activeChar.originalId || activeChar.id,
            jsonProfile: { ...editJson, character_name: charName }
        };
        onSaveCharacter(newVersion);
        alert("New version saved to library!");
    };

    const updateJsonField = (path: string, value: any) => {
        const newJson = { ...editJson };
        const keys = path.split('.');
        let current = newJson;
        for (let i = 0; i < keys.length - 1; i++) {
            if (!current[keys[i]]) current[keys[i]] = {};
            current = current[keys[i]];
        }
        current[keys[keys.length - 1]] = value;
        setEditJson(newJson);
    };

    const handleReset = () => {
        if (activeChar) {
            setEditJson(activeChar.jsonProfile || {});
            setCharName(activeChar.name);
            setChangeInstructions('');
        }
    };

    if (!activeChar) {
        return <div className="p-4 text-center text-gray-500">Select a character to edit.</div>;
    }

    return (
        <div className="flex flex-col h-full space-y-4">
            <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <SparklesIcon className="w-6 h-6 text-indigo-400" /> Character Editor
            </h2>
            <div className="p-3 bg-gray-800/80 rounded-lg border border-gray-700 space-y-2">
                <label className="block text-[10px] uppercase font-bold text-gray-500">Character Identity</label>
                <div className="flex gap-2">
                    <input type="text" value={charName} onChange={handleNameChange} className="flex-1 bg-gray-900 border border-gray-600 rounded px-2 py-1.5 text-sm text-white focus:ring-1 focus:ring-indigo-500 outline-none" placeholder="Character Name" />
                    <button onClick={handleRandomName} disabled={isGeneratingName} className="p-1.5 bg-gray-700 hover:bg-gray-600 text-indigo-400 rounded transition-colors disabled:opacity-50" title="Random Name Generator"><SparklesIcon className={`w-4 h-4 ${isGeneratingName ? 'animate-spin' : ''}`} /></button>
                </div>
            </div>
            <div className="flex gap-1 bg-gray-800 p-1 rounded-lg">
                {(['FACE', 'HAIR', 'CLOTHING', 'BODY', 'STYLE'] as const).map(cat => (
                    <button key={cat} onClick={() => setActiveCategory(cat)} className={`flex-1 py-1.5 text-[10px] font-bold rounded transition-colors ${activeCategory === cat ? 'bg-indigo-600 text-white' : 'text-gray-400 hover:text-white'}`}>{cat}</button>
                ))}
            </div>
            <div className="flex-grow overflow-y-auto pr-2 space-y-4">
                <div className="space-y-4 p-3 bg-gray-800/50 rounded-lg border border-gray-700">
                    {activeCategory === 'FACE' && (
                        <div className="space-y-3">
                            <div><label className="block text-xs text-gray-400 mb-1">Eyes & Expression</label><input type="text" className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs text-white" placeholder="e.g. Sharp blue eyes" onChange={(e) => updateJsonField('visual_analysis.eyes', e.target.value)} /></div>
                            <div><label className="block text-xs text-gray-400 mb-1">Face Shape & Features</label><input type="text" className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs text-white" placeholder="e.g. Angular jawline" onChange={(e) => updateJsonField('visual_analysis.face_shape', e.target.value)} /></div>
                        </div>
                    )}
                    {activeCategory === 'HAIR' && (
                        <div className="space-y-3">
                            <div><label className="block text-xs text-gray-400 mb-1">Hair Style & Length</label><input type="text" className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs text-white" placeholder="e.g. Messy undercut" onChange={(e) => updateJsonField('visual_analysis.hair_style', e.target.value)} /></div>
                            <div><label className="block text-xs text-gray-400 mb-1">Hair Color & Gradients</label><input type="text" className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs text-white" placeholder="e.g. Silver white" onChange={(e) => updateJsonField('visual_analysis.hair_color', e.target.value)} /></div>
                        </div>
                    )}
                    {activeCategory === 'CLOTHING' && (
                        <div className="space-y-3">
                            <div><label className="block text-xs text-gray-400 mb-1">Jersey / Clothing Style</label><input type="text" className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs text-white" placeholder="e.g. Cyberpunk jersey" onChange={(e) => updateJsonField('visual_analysis.clothing_style', e.target.value)} /></div>
                            <div><label className="block text-xs text-gray-400 mb-1">Logos & Graphics</label><input type="text" className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs text-white" placeholder="e.g. Neon tiger logo" onChange={(e) => updateJsonField('visual_analysis.graphics', e.target.value)} /></div>
                        </div>
                    )}
                    {activeCategory === 'STYLE' && (
                        <div className="space-y-3">
                            <div><label className="block text-xs text-gray-400 mb-1">Art Style Preset</label><select className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs text-white" onChange={(e) => updateJsonField('style.technique', e.target.value)}><option value="high-detail sports illustration">Sports Illustration</option><option value="cartoon exaggeration">Cartoonish</option><option value="minimalist vector style">Minimalist Vector</option><option value="realistic proportions">Realistic</option></select></div>
                            <div><label className="block text-xs text-gray-400 mb-1">Line Weight / Shading</label><input type="text" className="w-full bg-gray-900 border border-gray-700 rounded px-2 py-1 text-xs text-white" placeholder="e.g. Bold outlines" onChange={(e) => updateJsonField('style.rendering', e.target.value)} /></div>
                        </div>
                    )}
                    <div className="border-t border-gray-700 pt-3">
                        <label className="block text-xs font-bold text-indigo-400 mb-2">Live Refinement Instruction</label>
                        <textarea className="w-full h-20 p-2 bg-gray-900 border border-gray-600 rounded-md focus:ring-1 focus:ring-indigo-500 text-xs text-white placeholder-gray-600" placeholder='e.g. "Make the hair longer..."' value={changeInstructions} onChange={(e) => setChangeInstructions(e.target.value)} />
                    </div>
                </div>
                <div className="p-2 bg-gray-900 rounded border border-gray-800">
                    <p className="text-[9px] uppercase font-bold text-gray-600 mb-1">Live JSON Profile Sync</p>
                    <pre className="text-[9px] text-emerald-500 font-mono overflow-x-auto max-h-32">{JSON.stringify({ ...editJson, character_name: charName }, null, 2)}</pre>
                </div>
            </div>
            <div className="space-y-2 pt-2 border-t border-gray-700">
                <Button onClick={handleApplyEdits} className="w-full py-2 bg-indigo-600 shadow-lg shadow-indigo-500/10">Apply & Preview Changes</Button>
                <div className="flex gap-2">
                    <Button onClick={handleSaveVersion} variant="secondary" className="flex-1 text-xs">Save Version</Button>
                    <Button onClick={handleReset} variant="secondary" className="px-3 text-xs">Reset</Button>
                </div>
            </div>
        </div>
    );
};

