                  <div className="flex-grow overflow-auto bg-black/40 rounded-2xl border border-white/5 p-6 font-mono text-sm text-indigo-300 architect-mono leading-relaxed custom-scrollbar"><pre>{JSON.stringify(generatedContent.data, null, 2)}</pre></div>
