const getGenAI = () => {
  if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable not set");
  }
  return new GoogleGenAI({ apiKey: process.env.API_KEY });
}

/**
 * Resilient Request Wrapper
 */
async function resilientRequest<T>(
  requestFn: () => Promise<T>,
  onRetry?: (attempt: number, error: string) => void,
  maxRetries: number = 3
): Promise<T> {
  let lastError: any;
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      return await requestFn();
    } catch (error: any) {
      lastError = error;
      const isTransient = error.message?.includes("503") || 
                          error.message?.includes("429") || 
                          error.message?.includes("deadline") ||
                          error.message?.includes("expired");

      if (isTransient && attempt < maxRetries) {
        const delay = Math.pow(2, attempt) * 1000;
        if (onRetry) onRetry(attempt, error.message || "Transient error");
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw error;
    }
  }
  throw lastError;
}

/**
 * Uses AI to isolate the subject of an image on a plain white background
 * to facilitate background removal for watermarking.
 */
export const isolateWatermark = async (imageSource: string): Promise<string> => {
  const ai = getGenAI();
  const matches = imageSource.match(/^data:(.+);base64,(.+)$/);
  if (!matches) throw new Error("Invalid image source for isolation");

  const imagePart = {
    inlineData: {
      data: matches[2],
      mimeType: matches[1]
    }
  };

  const prompt = "TASK: Isolate the main subject of this image. Return ONLY the subject perfectly centered on a PURE WHITE (#FFFFFF) background. Remove all shadows, distractions, and existing backgrounds. The result must be suitable for use as a logo or watermark icon.";

  return resilientRequest(async () => {
    const response = await ai.models.generateContent({
      model: MODEL_NAMES.IMAGE_EDITING,
      contents: { parts: [imagePart, { text: prompt }] },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }
    throw new Error("Watermark isolation failed.");
  });
};

/**
 * Programmatically applies 10 watermark instances with random transforms.
 * Attempts to remove the white background from the isolated watermark source.
 */
export const applyMultiWatermark = (base64Image: string, watermarkBase64: string): Promise<string> => {
  return new Promise((resolve, reject) => {
    const mainImg = new Image();
    mainImg.crossOrigin = "anonymous";
    mainImg.onload = () => {
      const wmImg = new Image();
      wmImg.crossOrigin = "anonymous";
      wmImg.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = mainImg.width;
        canvas.height = mainImg.height;
        const ctx = canvas.getContext('2d');
        if (!ctx) return reject("Could not get canvas context");

        // Create a temporary canvas for the watermark to remove white background
        const wmCanvas = document.createElement('canvas');
        wmCanvas.width = wmImg.width;
        wmCanvas.height = wmImg.height;
        const wmCtx = wmCanvas.getContext('2d');
        if (!wmCtx) return reject("Could not get watermark context");
        wmCtx.drawImage(wmImg, 0, 0);

        const wmImageData = wmCtx.getImageData(0, 0, wmCanvas.width, wmCanvas.height);
        const data = wmImageData.data;
        // Simple white-to-transparent removal
        for (let i = 0; i < data.length; i += 4) {
          const r = data[i], g = data[i+1], b = data[i+2];
          if (r > 240 && g > 240 && b > 240) {
            data[i + 3] = 0; // Alpha
          }
        }
        wmCtx.putImageData(wmImageData, 0, 0);

        // Draw main scene image
        ctx.drawImage(mainImg, 0, 0);

        // Watermark Config
        const count = 10;
        const wmWidth = canvas.width * 0.12; // 12% width average
        const wmHeight = (wmImg.height / wmImg.width) * wmWidth;

        // Define 'Safe Zone' where the main artwork usually is (center 60%)
        const safeZone = {
          x: canvas.width * 0.2,
          y: canvas.height * 0.2,
          w: canvas.width * 0.6,
          h: canvas.height * 0.6
        };

        for (let i = 0; i < count; i++) {
          let x, y;
          let attempts = 0;

          // Try to find a position outside the safe zone or at least scattered
          do {
            x = Math.random() * (canvas.width - wmWidth);
            y = Math.random() * (canvas.height - wmHeight);
            attempts++;
            // If it's in the safe zone, try again up to 5 times
          } while (
            attempts < 5 &&
            x > safeZone.x && x < safeZone.x + safeZone.w &&
            y > safeZone.y && y < safeZone.y + safeZone.h
          );

          const rotation = (Math.random() * 20 - 10) * (Math.PI / 180); // -10 to +10 degrees
          const opacity = Math.random() * 0.1 + 0.2; // 20-30% opacity

          ctx.save();
          ctx.globalAlpha = opacity;
          ctx.translate(x + wmWidth / 2, y + wmHeight / 2);
          ctx.rotate(rotation);
          ctx.drawImage(wmCanvas, -wmWidth / 2, -wmHeight / 2, wmWidth, wmHeight);
          ctx.restore();
        }

        resolve(canvas.toDataURL('image/png', 1.0));
      };
      wmImg.onerror = reject;
      wmImg.src = watermarkBase64;
    };
    mainImg.onerror = reject;
    mainImg.src = base64Image;
  });
};

export const transformImageWithAI = async (
  imageFile: File,
  userPrompt: string,
  jsonContext?: string,
  onProgress?: (msg: string) => void
): Promise<string> => {
  const imagePart = await fileToGenerativePart(imageFile);

  const systemConstraints = `
    TASK: Comprehensive Image Modification.
    CORE CAPABILITIES:
    1. STYLE: Interpret any artistic style (watercolor, cyberpunk, retro, etc.).
    2. OBJECTS: Remove specified elements context-aware; Add new objects matching scene lighting and perspective.
    3. ADJUSTMENTS: Modify colors, tones, atmosphere, lighting, and textures.
    4. STRUCTURE: Support compositional changes, cropping, framing, and perspective shifts if requested.
    5. CHARACTERS: Modify hair, features, expressions, or clothing while preserving base identity.
    6. ENVIRONMENT: Redesign or stylize backgrounds and materials.

    EXECUTION RULES:
    - Interpret the prompt strictly according to user intent.
    - Preserve original image structure and identity unless modifications are explicitly requested.
    - Ensure all changes are visually coherent and perspective-correct.
  `;

  const contextInstruction = jsonContext 
    ? `PRIMARY STYLE/CONTEXT DATA (JSON Profile): ${jsonContext}. Apply these specific visual attributes.`
    : "";

  const finalPrompt = `
    ${systemConstraints}
    ${contextInstruction}
    USER MODIFICATION REQUEST: ${userPrompt}
    Render the modified result with professional-grade fidelity.
  `;

  return resilientRequest(
    async () => {
      const requestAi = getGenAI();
      const response = await requestAi.models.generateContent({
        model: MODEL_NAMES.IMAGE_EDITING,
        contents: { parts: [imagePart, { text: finalPrompt }] },
      });

      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
      throw new Error("AI Transformation failed to return an image.");
    },
    (attempt, err) => {
      if (onProgress) onProgress(`Server processing heavy edits. Retrying (Attempt ${attempt}/3)...`);
    }
  );
};

