export const generateCharacterWithStyle = async (
  characterName: string,
  characterDescription: string,
  characterStyle?: string
): Promise<any> => {
  const styleObj = CHARACTER_STYLES.find(s => s.name === characterStyle);
  const appliedStyle = styleObj ? styleObj.name : 'Default';
  const styleDescription = styleObj ? styleObj.description : 'Standard studio character design aesthetic.';

  const stylePrompt = styleObj 
    ? `Style: ${appliedStyle}. Definition: ${styleDescription}. Follow this style strictly.` 
    : "Style: High quality modern character design sheet aesthetic, isolated on white.";

  const fullPrompt = `Character Name: ${characterName}. Description: ${characterDescription}. ${stylePrompt} Isolated on white background, full body shot.`;

  return resilientRequest(async () => {
    const requestAi = getGenAI();
    const response = await requestAi.models.generateContent({
      model: MODEL_NAMES.IMAGE_EDITING,
      contents: { parts: [{ text: fullPrompt }] },
      config: {
        imageConfig: { aspectRatio: "1:1" },
      }
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return {
          image: `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`,
          appliedStyle,
          metadata: { styleDescription, generationNotes: "Style applied via instruction block." }
        };
      }
    }
    throw new Error("Failed to generate character image.");
  });
};

