export const generateScene = async (characters: Character[], prompt: string, rotations: Record<string, number>, onProgress: (msg: string) => void): Promise<string> => {
  const parts: Part[] = characters.map(c => {
    const m = c.imageUrl.match(/^data:(.+);base64,(.+)$/);
    return m ? { inlineData: { data: m[2], mimeType: m[1] } } : null;
  }).filter((p): p is Part => p !== null);
  parts.push({ text: `Cinematic scene: ${prompt}` });

  return resilientRequest(async () => {
    const requestAi = getGenAI();
    const response = await requestAi.models.generateContent({ 
      model: MODEL_NAMES.IMAGE_EDITING, 
      contents: { parts }, 
    });
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
    throw new Error("Scene failed.");
  });
};

export const generateVideo = async (imageFile: File, prompt: string, aspectRatio: AspectRatio, onProgress: (msg: string) => void): Promise<string> => {
  const base64 = await fileToBase64(imageFile);
  const data = base64.split(',')[1];
  let ai = getGenAI();
  let operation = await ai.models.generateVideos({ model: MODEL_NAMES.VIDEO_GENERATION, prompt, image: { imageBytes: data, mimeType: imageFile.type }, config: { numberOfVideos: 1, resolution: '720p', aspectRatio } });
  while (!operation.done) {
    await new Promise(r => setTimeout(r, 10000));
    ai = getGenAI();
    operation = await ai.operations.getVideosOperation({ operation });
  }
  const link = operation.response?.generatedVideos?.[0]?.video?.uri;
  const res = await fetch(`${link}&key=${process.env.API_KEY}`);
  return URL.createObjectURL(await res.blob());
};

export const generateCharacterSpeech = async (text: string, voiceName: string): Promise<string> => {
  const ai = getGenAI();
  const response = await ai.models.generateContent({ model: MODEL_NAMES.TTS, contents: [{ parts: [{ text }] }], config: { responseModalities: [Modality.AUDIO], speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName } } } } });
  const base64 = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
  if (!base64) throw new Error("Audio failed.");
  return URL.createObjectURL(createWavBlob(base64ToUint8Array(base64)));
};

export const generateImageFromInput = async (input: string, onProgress: (msg: string) => void): Promise<string> => {
    const ai = getGenAI();
    const response = await ai.models.generateImages({ model: MODEL_NAMES.IMAGE_GENERATION, prompt: input, config: { numberOfImages: 1, aspectRatio: "1:1", outputMimeType: 'image/jpeg' } });
    if (response.generatedImages?.[0]) return `data:image/jpeg;base64,${response.generatedImages[0].image.imageBytes}`;
    throw new Error("Image failed.");
};

export const animateImage = async (imageFile: File, input: string, aspectRatio: AspectRatio, onProgress: (msg: string) => void): Promise<string> => {
    return generateVideo(imageFile, input, aspectRatio, onProgress);
};

