// Added missing TransformableCharacter component
const TransformableCharacter: React.FC<{
    character: Character;
    rotation: number;
    position: { x: number; y: number };
    onRotationChange: (rot: number) => void;
    onPositionChange: (pos: { x: number; y: number }) => void;
    isSelected: boolean;
    onSelect: () => void;
    containerRef: React.RefObject<HTMLDivElement>;
}> = ({ character, rotation, position, onRotationChange, onPositionChange, isSelected, onSelect }) => {
    const handleMouseDown = (e: React.MouseEvent) => {
        e.stopPropagation();
        onSelect();
        const startX = e.clientX - position.x;
        const startY = e.clientY - position.y;

        const onMouseMove = (moveEvent: MouseEvent) => {
            onPositionChange({ x: moveEvent.clientX - startX, y: moveEvent.clientY - startY });
        };

        const onMouseUp = () => {
            window.removeEventListener('mousemove', onMouseMove);
            window.removeEventListener('mouseup', onMouseUp);
        };

        window.addEventListener('mousemove', onMouseMove);
        window.addEventListener('mouseup', onMouseUp);
    };

    return (
        <div 
            style={{ 
                position: 'absolute', 
                left: position.x, 
                top: position.y, 
                transform: `rotate(${rotation}deg)`,
                cursor: 'grab',
                zIndex: isSelected ? 50 : 10
            }}
            onMouseDown={handleMouseDown}
            className={`group transition-shadow select-none ${isSelected ? 'ring-2 ring-indigo-500 ring-offset-4 ring-offset-transparent rounded-xl' : 'hover:ring-1 hover:ring-indigo-500/30 rounded-xl'}`}
        >
            <img 
                src={character.imageUrl} 
                alt={character.name} 
                className="w-48 h-48 object-contain pointer-events-none drop-shadow-2xl" 
                draggable={false}
            />
            {isSelected && (
                <div className="absolute -bottom-12 left-1/2 -translate-x-1/2 flex gap-1.5 bg-gray-900/90 backdrop-blur-md p-1.5 rounded-xl shadow-2xl border border-white/10">
                    <button 
                        onClick={(e) => { e.stopPropagation(); onRotationChange(rotation - 15); }} 
                        className="p-1.5 hover:bg-gray-800 rounded-lg transition-colors"
                        title="Rotate Left"
                    >
                        <RotateLeftIcon className="w-4 h-4 text-white" />
                    </button>
                    <button 
                        onClick={(e) => { e.stopPropagation(); onRotationChange(rotation + 15); }} 
                        className="p-1.5 hover:bg-gray-800 rounded-lg transition-colors"
                        title="Rotate Right"
                    >
                        <RotateRightIcon className="w-4 h-4 text-white" />
                    </button>
                </div>
            )}
        </div>
    );
};

