  const imagePart = await fileToGenerativePart(imageFile);
  const prompt = "Transform this scene into a realistic settled snow landscape. Preserve original composition.";
  return resilientRequest(async () => {
    const ai = getGenAI();
    const response = await ai.models.generateContent({
      model: MODEL_NAMES.IMAGE_EDITING,
      contents: { parts: [imagePart, { text: prompt }] },
    });
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
    throw new Error("Snow transformation failed.");
  });
};

export const generateBotanicMockups = async (
  imageFile: File,
  watermarkSource: string,
  onProgress?: (msg: string) => void
): Promise<string[]> => {
  const imagePart = await fileToGenerativePart(imageFile);
  const variations = [
    { prompt: "Botanical line art print in a white frame, Scandinavian minimalist living room, soft natural lighting." },
    { prompt: "Botanical line art framed print on a warm beige wall, cozy interior styling, editorial photography." },
    { prompt: "Botanical line art print in a light oak frame, serene bedroom wall, soft morning light." }
  ];

  let completed = 0;
  const tasks = variations.map(async (v) => {
    return resilientRequest(async () => {
      const ai = getGenAI();
      const response = await ai.models.generateContent({
        model: MODEL_NAMES.IMAGE_EDITING,
        contents: { parts: [imagePart, { text: v.prompt }] },
      });
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          const primaryUrl = `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
          const watermarkedUrl = await applyMultiWatermark(primaryUrl, watermarkSource);
          completed++;
          if (onProgress) onProgress(`Generating Botanic Scenes: ${completed}/${variations.length}...`);
          return [primaryUrl, watermarkedUrl];
        }
      }
      throw new Error("Variation failed.");
    });
  });

  const allPairs = await Promise.all(tasks);
  return allPairs.flat();
};

