/**
 * Resilient Request Wrapper
 */
async function resilientRequest<T>(
  requestFn: () => Promise<T>,
  onRetry?: (attempt: number, error: string) => void,
  maxRetries: number = 3
): Promise<T> {
  let lastError: any;
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      return await requestFn();
    } catch (error: any) {
      lastError = error;
      const isTransient = error.message?.includes("503") || 
                          error.message?.includes("429") || 
                          error.message?.includes("deadline") ||
                          error.message?.includes("expired");

      if (isTransient && attempt < maxRetries) {
        const delay = Math.pow(2, attempt) * 1000;
        if (onRetry) onRetry(attempt, error.message || "Transient error");
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw error;
    }
  }
  throw lastError;
}

/**
 * Uses AI to isolate the subject of an image on a plain white background
 */
export const isolateWatermark = async (imageSource: string): Promise<string> => {
  const ai = getGenAI();
  const matches = imageSource.match(/^data:(.+);base64,(.+)$/);
  if (!matches) throw new Error("Invalid image source for isolation");

  const imagePart = {
    inlineData: {
      data: matches[2],
      mimeType: matches[1]
    }
  };

  const prompt = "TASK: Isolate the main subject of this image. Return ONLY the subject perfectly centered on a PURE WHITE (#FFFFFF) background. Remove all shadows, distractions, and existing backgrounds. This will be used as a high-quality watermark icon.";

  return resilientRequest(async () => {
    const response = await ai.models.generateContent({
      model: MODEL_NAMES.IMAGE_EDITING,
      contents: { parts: [imagePart, { text: prompt }] },
    });

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }
    throw new Error("Watermark isolation failed.");
  });
};

/**
 * Programmatically applies 10 watermark instances along a path.
 * Path: Top-left -> Center -> Bottom-right.
 * Rules: 20-30% opacity, 25-30% width, random rotation -10 to +10, non-obstruction of center artwork.
 */
export const applyMultiWatermark = (base64Image: string, watermarkBase64: string): Promise<string> => {
  return new Promise((resolve, reject) => {
    const mainImg = new Image();
    mainImg.crossOrigin = "anonymous";
    mainImg.onload = () => {
      const wmImg = new Image();
      wmImg.crossOrigin = "anonymous";
      wmImg.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = mainImg.width;
        canvas.height = mainImg.height;
        const ctx = canvas.getContext('2d');
        if (!ctx) return reject("Could not get canvas context");

        // Create watermark canvas for background removal
        const wmCanvas = document.createElement('canvas');
        wmCanvas.width = wmImg.width;
        wmCanvas.height = wmImg.height;
        const wmCtx = wmCanvas.getContext('2d');
        if (!wmCtx) return reject("Could not get watermark context");
        wmCtx.drawImage(wmImg, 0, 0);

        const wmImageData = wmCtx.getImageData(0, 0, wmCanvas.width, wmCanvas.height);
        const data = wmImageData.data;
        // White-to-transparent removal
        for (let i = 0; i < data.length; i += 4) {
          const r = data[i], g = data[i+1], b = data[i+2];
          if (r > 240 && g > 240 && b > 240) {
            data[i + 3] = 0; 
          }
        }
        wmCtx.putImageData(wmImageData, 0, 0);

        // Draw main artwork
        ctx.drawImage(mainImg, 0, 0);

        const count = 10;
        // Define center zone to avoid (approx 40% center)
        const centerZone = {
          x: canvas.width * 0.3,
          y: canvas.height * 0.3,
          w: canvas.width * 0.4,
          h: canvas.height * 0.4
        };

        for (let i = 0; i < count; i++) {
          const progress = i / (count - 1); // 0 to 1

          // Size: 25-30% of final image width
          const wmWidth = canvas.width * (0.25 + Math.random() * 0.05);
          const wmHeight = (wmImg.height / wmImg.width) * wmWidth;

          // Path: Top-left (0,0) to Bottom-right (maxW, maxH)
          // Add significant jitter but keep the diagonal trend
          let x = (canvas.width - wmWidth) * progress + (Math.random() - 0.5) * (canvas.width * 0.2);
          let y = (canvas.height - wmHeight) * progress + (Math.random() - 0.5) * (canvas.height * 0.2);

          // Bound checking
          x = Math.max(0, Math.min(x, canvas.width - wmWidth));
          y = Math.max(0, Math.min(y, canvas.height - wmHeight));

          // Non-obstruction: If it overlaps center significantly, nudge it
          if (x + wmWidth > centerZone.x && x < centerZone.x + centerZone.w &&
              y + wmHeight > centerZone.y && y < centerZone.y + centerZone.h) {
             // Push outwards from center
             if (x + wmWidth / 2 < canvas.width / 2) x -= wmWidth * 0.5;
             else x += wmWidth * 0.5;

             if (y + wmHeight / 2 < canvas.height / 2) y -= wmHeight * 0.5;
             else y += wmHeight * 0.5;
          }

          // Re-bound check after nudge
          x = Math.max(0, Math.min(x, canvas.width - wmWidth));
          y = Math.max(0, Math.min(y, canvas.height - wmHeight));

          const rotation = (Math.random() * 20 - 10) * (Math.PI / 180);
          const opacity = 0.20 + Math.random() * 0.10; // 20-30%

          ctx.save();
          ctx.globalAlpha = opacity;
          ctx.translate(x + wmWidth / 2, y + wmHeight / 2);
          ctx.rotate(rotation);
          ctx.drawImage(wmCanvas, -wmWidth / 2, -wmHeight / 2, wmWidth, wmHeight);
          ctx.restore();
        }

        resolve(canvas.toDataURL('image/png', 1.0));
      };
      wmImg.onerror = reject;
      wmImg.src = watermarkBase64;
    };
    mainImg.onerror = reject;
    mainImg.src = base64Image;
  });
};

export const transformImageWithAI = async (
  imageFile: File,
  userPrompt: string,
  jsonContext?: string,
  onProgress?: (msg: string) => void
): Promise<string> => {
  const imagePart = await fileToGenerativePart(imageFile);
  const systemConstraints = "TASK: Comprehensive Image Modification. Ensure changes are visually coherent and perspective-correct.";
  const contextInstruction = jsonContext ? `PRIMARY STYLE/CONTEXT DATA (JSON Profile): ${jsonContext}` : "";
  const finalPrompt = `${systemConstraints} ${contextInstruction} USER MODIFICATION REQUEST: ${userPrompt}`;

  return resilientRequest(async () => {
    const ai = getGenAI();
    const response = await ai.models.generateContent({
      model: MODEL_NAMES.IMAGE_EDITING,
      contents: { parts: [imagePart, { text: finalPrompt }] },
    });
    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
    }
    throw new Error("AI Modification failed.");
  });
};

