    setLoading(true, "Generating speech...");
    setError(null);
    try {
      const audioUrl = await generateCharacterSpeech(text, selectedVoice);
      onGenerationComplete({ type: 'audio', url: audioUrl, characterId: targetCharacterId || undefined });
